window.__BOOK__={"meta": {"title_fr": "Le Petit Prince", "title_zh": "小王子", "author_fr": "Antoine de Saint-Exupéry", "author_zh": "安托万·德·圣埃克苏佩里", "voice": "fr-FR-DeniseNeural (edge-tts)", "ipa_note": "音标为宽式音位转写（法语近似发音，不标重音、不处理联诵），仅供参考。", "n_chapters": 28, "n_paras": 783, "n_sents": 1653, "audio_paras": 783}, "chapters": [{"id": "ch00", "title_fr": "À Léon Werth", "title_zh": "献词", "paras": [{"id": "ch00p00", "audio": true, "sents": [{"fr": "À Léon Werth.", "zh": "献给列翁·维尔特。", "t": [100, 1962]}, {"fr": "Je demande aux enfants de m'excuser de dédier ce livre à une grande personne.", "zh": "请孩子们原谅我把这本书献给一位大人。", "t": [1962, 6538]}, {"fr": "J'ai une excuse sérieuse : cette grande personne est le meilleur ami que j'ai au monde.", "zh": "这位大人是我世间至交。", "t": [6538, 11725]}, {"fr": "J'ai une autre excuse : cette grande personne peut tout comprendre, même les livres pour enfants.", "zh": "这位大人通晓一切，即便是对孩子的书籍也能心领神会。", "t": [11725, 17450]}, {"fr": "J'ai une troisième excuse : cette grande personne habite la France où elle a faim et froid.", "zh": "这位大人住在法国，忍饥受寒。", "t": [17450, 22900]}, {"fr": "Elle a besoin d'être consolée.", "zh": "她需要得到慰藉。", "t": [22900, 25388]}, {"fr": "Si toutes ces raisons ne suffisent pas, je veux dédier ce livre à l'enfant qu'a été autrefois cette grande personne.", "zh": "若这些理由仍不足够，我愿将此书献予那位曾为孩童的大人。", "t": [25388, 31550]}, {"fr": "Toutes les grandes personnes ont d'abord été des enfants.", "zh": "所有的大人起初都是孩子。", "t": [31550, 34662]}, {"fr": "(Mais peu d'entre elles s'en souviennent.) Je corrige donc ma dédicace : À LEON WERTH, QUAND IL ÉTAIT PETIT GARÇON.", "zh": "然而，他们中的多数已遗忘。因此，我更正我的献辞：献予列翁·维尔特，他曾是那个小男孩。", "t": [34662, 41287]}]}]}, {"id": "ch01", "title_fr": "Chapitre I", "title_zh": "第 1 章", "paras": [{"id": "ch01p00", "audio": true, "sents": [{"fr": "Lorsque j’avais six ans j’ai vu, une fois, une magnifique image, dans un livre sur la Forêt Vierge qui s’appelait \"Histoires Vécues\".", "zh": "六岁那年，我在一本名为《处女林历险记》的书里，瞥见了一幅壮丽的图画。", "t": [100, 7875]}, {"fr": "Ça représentait un serpent boa qui avalait un fauve.", "zh": "这是一条蟒蛇正在吞噬一只猎豹。", "t": [7875, 11488]}, {"fr": "Voilà la copie du dessin.", "zh": "这是这幅画的复印件。", "t": [11488, 12938]}]}, {"id": "ch01p01", "audio": true, "sents": [{"fr": "On disait dans le livre : \"Les serpents boas avalent leur proie tout entière, sans la mâcher.", "zh": "书中写道：“蟒蛇将猎物整个吞下，未曾咀嚼。”", "t": [100, 6088]}, {"fr": "Ensuite ils ne peuvent plus bouger et ils dorment pendant les six mois de leur digestion\".", "zh": "随后，它们便无法动弹，在消化期间沉睡六个月。", "t": [6088, 10013]}]}, {"id": "ch01p02", "audio": true, "sents": [{"fr": "J’ai alors beaucoup réfléchi sur les aventures de la jungle et, à mon tour, j’ai réussi, avec un crayon de couleur, à tracer mon premier dessin.", "zh": "那时，我对丛林历险沉思良久，终于用彩色铅笔成功勾勒出我的第一幅画。", "t": [100, 9025]}, {"fr": "Mon dessin numéro 1.", "zh": "我的第一幅画。", "t": [9025, 10038]}, {"fr": "Il était comme ça :", "zh": "它就是这样。", "t": [10038, 12825]}]}, {"id": "ch01p03", "audio": true, "sents": [{"fr": "J’ai montré mon chef d’œuvre aux grandes personnes et je leur ai demandé si mon dessin leur faisait peur.", "zh": "我把我的杰作展示给大人看，问他们我的画是否吓到了他们。", "t": [100, 4650]}]}, {"id": "ch01p04", "audio": true, "sents": [{"fr": "Elles m’ont répondu : \"Pourquoi un chapeau ferait-il peur ?\"", "zh": "他们答道：“一顶帽子怎么会吓人呢？”", "t": [100, 4250]}]}, {"id": "ch01p05", "audio": true, "sents": [{"fr": "Mon dessin ne représentait pas un chapeau.", "zh": "我的画并非一顶帽子。", "t": [100, 2962]}, {"fr": "Il représentait un serpent boa qui digérait un éléphant.", "zh": "它描绘了一条蟒蛇正在消化一头大象。", "t": [2962, 6725]}, {"fr": "J’ai alors dessiné l’intérieur du serpent boa, afin que les grandes personnes puissent comprendre.", "zh": "于是，我画出了蟒蛇的内部，以便大人们能够理解。", "t": [6725, 12488]}, {"fr": "Elles ont toujours besoin d’explications.", "zh": "他们总是需要解释。", "t": [12488, 15350]}, {"fr": "Mon dessin numéro 2 était comme ça :", "zh": "我的第二号画就是这样：", "t": [15350, 17937]}]}, {"id": "ch01p06", "audio": true, "sents": [{"fr": "Les grandes personnes m’ont conseillé de laisser de côté les dessins de serpents boas ouverts ou fermés, et de m’intéresser plutôt à la géographie, à l’histoire, au calcul et à la grammaire.", "zh": "大人们建议我放弃画那些张着嘴或闭着嘴的蟒蛇，转而关注地理、历史、算术和语法。", "t": [100, 10600]}, {"fr": "C’est ainsi que j’ai abandonné, à l’âge de six ans, une magnifique carrière de peintre.", "zh": "就这样，我在六岁那年放弃了那幅灿烂的画家生涯。", "t": [10600, 16188]}, {"fr": "J’avais été découragé par l’insuccès de mon dessin numéro 1 et de mon dessin numéro 2.", "zh": "我的第一幅画和第二幅画的失败让我倍感沮丧。", "t": [16188, 20638]}, {"fr": "Les grandes personnes ne comprennent jamais rien toutes seules, et c’est fatigant, pour les enfants, de toujours leur donner des explications.", "zh": "大人永远无法独自理解，孩子们总是得不厌其烦地为他们解释，这实在累人。", "t": [20638, 28612]}]}, {"id": "ch01p07", "audio": true, "sents": [{"fr": "J’ai donc dû choisir un autre métier et j’ai appris à piloter des avions.", "zh": "于是，我选择了另一门职业，并学会了驾驶飞机。", "t": [100, 4812]}, {"fr": "J’ai volé un peu partout dans le monde.", "zh": "我飞遍世界各地。", "t": [4812, 7550]}, {"fr": "Et la géographie, c’est exact, m’a beaucoup servi.", "zh": "地理，确实帮了我大忙。", "t": [7550, 11812]}, {"fr": "Je savais reconnaître, du premier coup d’œil, la Chine de l’Arizona.", "zh": "我一眼就能认出亚利桑那的中国。", "t": [11812, 16825]}, {"fr": "C’est très utile, si l’on est égaré pendant la nuit.", "zh": "若夜航迷途，颇为管用。", "t": [16825, 19500]}]}, {"id": "ch01p08", "audio": true, "sents": [{"fr": "J’ai ainsi eu, au cours de ma vie, des tas de contacts avec des tas de gens sérieux.", "zh": "我一生中与许多严肃的人有过众多交往。", "t": [100, 5200]}, {"fr": "J’ai beaucoup vécu chez les grandes personnes.", "zh": "我在大人中间度过了许多时光。", "t": [5200, 8188]}, {"fr": "Je les ai vues de très près.", "zh": "我近距离观察过他们。", "t": [8188, 10350]}, {"fr": "Ça n’a pas trop amélioré mon opinion.", "zh": "这并未改善我的看法。", "t": [10350, 12325]}]}, {"id": "ch01p09", "audio": true, "sents": [{"fr": "Quand j’en rencontrais une qui me paraissait un peu lucide, je faisais l’expérience sur elle de mon dessin n° 1 que j’ai toujours conservé.", "zh": "当我遇到一个看似有点明事理的大人时，我便用我始终保留的一号画进行试验。", "t": [100, 7850]}, {"fr": "Je voulais savoir si elle était vraiment compréhensive.", "zh": "我想知道她是否真的懂了。", "t": [7850, 11400]}, {"fr": "Mais toujours elle me répondait : \"C’est un chapeau.\" Alors je ne lui parlais ni de serpents boas, ni de forêts vierges, ni d’étoiles.", "zh": "但她总是回答我：“这是一顶帽子。”于是我便不再与她谈论蟒蛇、原始森林和星星。", "t": [11400, 20888]}, {"fr": "Je me mettais à sa portée.", "zh": "我靠近了他。", "t": [20888, 23238]}, {"fr": "Je lui parlais de bridge, de golf, de politique et de cravates.", "zh": "我同他谈论桥牌、高尔夫、政治和领带。", "t": [23238, 27888]}, {"fr": "Et la grande personne était bien contente de connaître un homme aussi raisonnable.", "zh": "那位重要的大人对此感到非常满意，以为认识了一个如此通情达理的人。", "t": [27888, 31688]}]}, {"id": "ch01p10", "audio": true, "sents": []}]}, {"id": "ch02", "title_fr": "Chapitre II", "title_zh": "第 2 章", "paras": [{"id": "ch02p00", "audio": true, "sents": [{"fr": "J’ai ainsi vécu seul, sans personne avec qui parler véritablement, jusqu’à une panne dans le désert du Sahara, il y a six ans.", "zh": "就这样，我孤独地生活着，无人可以真正交谈，直至六年前在撒哈拉沙漠的一次故障。", "t": [100, 7825]}, {"fr": "Quelque chose s’était cassé dans mon moteur.", "zh": "发动机里出了故障。", "t": [7825, 10888]}, {"fr": "Et comme je n’avais avec moi ni mécanicien, ni passagers, je me préparai à essayer de réussir, tout seul, une réparation difficile.", "zh": "于是，身边既无机械师，亦无乘客，我独自准备尝试完成一次艰难的修理。", "t": [10888, 19675]}, {"fr": "C’était pour moi une question de vie ou de mort.", "zh": "生死攸关。", "t": [19675, 22750]}, {"fr": "J’avais à peine de l’eau à boire pour huit jours.", "zh": "仅剩八天的饮水。", "t": [22750, 25025]}]}, {"id": "ch02p01", "audio": true, "sents": [{"fr": "Le premier soir je me suis donc endormi sur le sable à mille milles de toute terre habitée.", "zh": "于是，我就在千里之外、人迹罕至的沙地上沉沉睡去。", "t": [100, 5175]}, {"fr": "J’étais bien plus isolé qu’un naufragé sur un radeau au milieu de l’océan.", "zh": "比漂泊在汪洋中的孤舟遇险者更为孤立无援。", "t": [5175, 9762]}, {"fr": "Alors vous imaginez ma surprise, au lever du jour, quand une drôle de petite voix m’a réveillé.", "zh": "清晨，那奇异的细小声音将我唤醒，我惊讶不已。", "t": [9762, 15850]}, {"fr": "Elle disait :", "zh": "她说道：", "t": [15850, 17274]}]}, {"id": "ch02p02", "audio": true, "sents": [{"fr": "— S’il vous plaît…", "zh": "请…", "t": [100, 2125]}, {"fr": "dessine-moi un mouton !", "zh": "画一只绵羊吧！", "t": [2125, 3887]}]}, {"id": "ch02p03", "audio": true, "sents": [{"fr": "— Hein !", "zh": "哎！", "t": [100, 2163]}]}, {"id": "ch02p04", "audio": true, "sents": [{"fr": "— Dessine-moi un mouton…", "zh": "画一只羊吧…", "t": [100, 2387]}]}, {"id": "ch02p05", "audio": true, "sents": [{"fr": "J’ai sauté sur mes pieds comme si j’avais été frappé par la foudre.", "zh": "我猛地跳了起来，仿佛被雷电击中。", "t": [100, 4088]}, {"fr": "J’ai bien frotté mes yeux.", "zh": "我用力擦了擦眼睛。", "t": [4088, 6225]}, {"fr": "J’ai bien regardé.", "zh": "我仔细端详。", "t": [6225, 8200]}, {"fr": "Et j’ai vu un petit bonhomme tout à fait extraordinaire qui me considérait gravement.", "zh": "我瞧见一个模样奇特的小人儿，正郑重其事地打量着我。", "t": [8200, 13100]}, {"fr": "Voilà le meilleur portrait que, plus tard, j’ai réussi à faire de lui.", "zh": "这就是后来我成功为他画出的最好的一幅肖像。", "t": [13100, 17962]}, {"fr": "Mais mon dessin, bien sûr, est beaucoup moins ravissant que le modèle.", "zh": "但我的画，当然，远不及原型迷人。", "t": [17962, 22712]}, {"fr": "Ce n’est pas ma faute.", "zh": "这不是我的错。", "t": [22712, 24688]}, {"fr": "J’avais été découragé dans ma carrière de peintre par les grandes personnes, à l’âge de six ans, et je n’avais rien appris à dessiner, sauf les boas fermés et les boas ouverts.", "zh": "六岁时，我被大人挫败了画家生涯，除了画闭嘴的蟒蛇和开口的蟒蛇，我未曾学过其他绘画。", "t": [24688, 33812]}]}, {"id": "ch02p06", "audio": true, "sents": [{"fr": "Je regardai donc cette apparition avec des yeux tout ronds d’étonnement.", "zh": "我惊讶地瞪大了眼睛，凝视着这突如其来的身影。", "t": [100, 4875]}, {"fr": "N’oubliez pas que je me trouvais à mille milles de toute région habitée.", "zh": "别忘了，我正身处千里之外，人烟稀少之地。", "t": [4875, 8300]}, {"fr": "Or mon petit bonhomme ne me semblait ni égaré, ni mort de fatigue, ni mort de faim, ni mort de soif, ni mort de peur.", "zh": "他既不像是迷路的，也不像是因劳累、饥饿、口渴或恐惧而死的。", "t": [8300, 16250]}, {"fr": "Il n’avait en rien l’apparence d’un enfant perdu au milieu du désert, à mille milles de toute région habitée.", "zh": "他看上去绝非是在人烟稀少的沙漠中迷失的孩子。", "t": [16250, 22388]}, {"fr": "Quand je réussis enfin à parler, je lui dis :", "zh": "当我终于开口说话，我对他说：", "t": [22388, 25538]}]}, {"id": "ch02p07", "audio": true, "sents": [{"fr": "— Mais…", "zh": "但…", "t": [100, 1650]}, {"fr": "qu’est-ce que tu fais là ?", "zh": "你在此处做什么？", "t": [1650, 3263]}]}, {"id": "ch02p08", "audio": true, "sents": [{"fr": "Et il me répéta alors, tout doucement, comme une chose très sérieuse :", "zh": "他随后轻声地、郑重其事地重复道：", "t": [100, 4387]}]}, {"id": "ch02p09", "audio": true, "sents": [{"fr": "— S’il vous plaît…", "zh": "请…", "t": [100, 2112]}, {"fr": "dessine-moi un mouton…", "zh": "画一只羊吧…", "t": [2112, 3162]}]}, {"id": "ch02p10", "audio": true, "sents": [{"fr": "Quand le mystère est trop impressionnant, on n’ose pas désobéir.", "zh": "神秘之物令人震撼，不敢违抗。", "t": [100, 4150]}, {"fr": "Aussi absurde que cela me semblât à mille milles de tous les endroits habités et en danger de mort, je sortis de ma poche une feuille de papier et un stylographe.", "zh": "即便在这荒无人烟、生死攸关的千里之外，我还是从口袋里掏出一张纸和一支钢笔。", "t": [4150, 13125]}, {"fr": "Mais je me rappelai alors que j’avais surtout étudié la géographie, l’histoire, le calcul et la grammaire et je dis au petit bonhomme (avec un peu de mauvaise humeur) que je ne savais pas dessiner.", "zh": "然而，我忽然想起自己主要研习的是地理、历史、算术和语法，便带着几分不悦对那位小家伙说，我不会画画。", "t": [13125, 24125]}, {"fr": "Il me répondit :", "zh": "他回答道：", "t": [24125, 25850]}]}, {"id": "ch02p11", "audio": true, "sents": [{"fr": "— Ça ne fait rien.", "zh": "没关系。", "t": [100, 2912]}, {"fr": "Dessine-moi un mouton.", "zh": "画一只羊吧。", "t": [2912, 4126]}]}, {"id": "ch02p12", "audio": true, "sents": [{"fr": "Comme je n’avais jamais dessiné un mouton je refis, pour lui, l’un des deux seuls dessins dont j’étais capable.", "zh": "便又给他画了那两张画中之一。", "t": [100, 6462]}, {"fr": "Celui du boa fermé.", "zh": "闭嘴的蟒蛇", "t": [6462, 8588]}, {"fr": "Et je fus stupéfait d’entendre le petit bonhomme me répondre :", "zh": "我惊讶地听到小家伙回答我：", "t": [8588, 12162]}]}, {"id": "ch02p13", "audio": true, "sents": [{"fr": "— Non !", "zh": "不！", "t": [100, 3125]}, {"fr": "Non !", "zh": "不！", "t": [3125, 5112]}, {"fr": "Je ne veux pas d’un éléphant dans un boa.", "zh": "我不想在蟒蛇肚子里有一只大象。", "t": [5112, 7950]}, {"fr": "Un boa c’est très dangereux, et un éléphant c’est très encombrant.", "zh": "蟒蛇太可怕，象又太占地方。", "t": [7950, 12025]}, {"fr": "Chez moi c’est tout petit.", "zh": "在我那儿地方很小。", "t": [12025, 14150]}, {"fr": "J’ai besoin d’un mouton.", "zh": "我需要一只羊。", "t": [14150, 16300]}, {"fr": "Dessine-moi un mouton.", "zh": "画一只羊吧。", "t": [16300, 17513]}]}, {"id": "ch02p14", "audio": true, "sents": [{"fr": "Alors j’ai dessiné.", "zh": "于是，我画了。", "t": [100, 1237]}]}, {"id": "ch02p15", "audio": true, "sents": [{"fr": "Il regarda attentivement, puis :", "zh": "他仔细端详，然后说：", "t": [100, 2687]}]}, {"id": "ch02p16", "audio": true, "sents": [{"fr": "— Non !", "zh": "不！", "t": [100, 3125]}, {"fr": "Celui-là est déjà très malade.", "zh": "这头羊已经病得很重了。", "t": [3125, 5775]}, {"fr": "Fais-en un autre.", "zh": "再画一个吧。", "t": [5775, 6750]}]}, {"id": "ch02p17", "audio": true, "sents": [{"fr": "Je dessinai :", "zh": "我画了：", "t": [100, 1750]}]}, {"id": "ch02p18", "audio": true, "sents": [{"fr": "Mon ami sourit gentiment, avec indulgence :", "zh": "我的朋友微笑着，带着宽容。", "t": [100, 3287]}]}, {"id": "ch02p19", "audio": true, "sents": [{"fr": "— Tu vois bien…", "zh": "你瞧瞧……", "t": [100, 2100]}, {"fr": "ce n’est pas un mouton, c’est un bélier.", "zh": "这不是羊，是公羊。", "t": [2100, 4938]}, {"fr": "Il a des cornes…", "zh": "它长着角呢。", "t": [4938, 5837]}]}, {"id": "ch02p20", "audio": true, "sents": [{"fr": "Je refis donc encore mon dessin :", "zh": "于是，我又重新画了我的画：", "t": [100, 2600]}]}, {"id": "ch02p21", "audio": true, "sents": [{"fr": "Mais il fut refusé, comme les précédents :", "zh": "但也被拒绝了，就像之前的那些一样：", "t": [100, 3100]}]}, {"id": "ch02p22", "audio": true, "sents": [{"fr": "— Celui-là est trop vieux.", "zh": "这头羊太老了。", "t": [100, 3200]}, {"fr": "Je veux un mouton qui vive longtemps.", "zh": "我要一只能活很久的绵羊。", "t": [3200, 4974]}]}, {"id": "ch02p23", "audio": true, "sents": [{"fr": "Alors, faute de patience, comme j’avais hâte de commencer le démontage de mon moteur, je griffonnai ce dessin-ci.", "zh": "于是，耐性尽失，急于开始拆卸发动机，我便草草地画了这幅画。", "t": [100, 6788]}]}, {"id": "ch02p24", "audio": true, "sents": [{"fr": "Et je lançai :", "zh": "我便说：", "t": [100, 1687]}]}, {"id": "ch02p25", "audio": true, "sents": [{"fr": "— Ça c’est la caisse.", "zh": "这就是箱子。", "t": [100, 3038]}, {"fr": "Le mouton que tu veux est dedans.", "zh": "那你要的绵羊就在里面。", "t": [3038, 4612]}]}, {"id": "ch02p26", "audio": true, "sents": [{"fr": "Mais je fus bien surpris de voir s’illuminer le visage de mon jeune juge :", "zh": "但见我的小法官脸上露出了惊喜之光。", "t": [100, 4063]}]}, {"id": "ch02p27", "audio": true, "sents": [{"fr": "— C’est tout à fait comme ça que je le voulais !", "zh": "这正是我想要的！", "t": [100, 4575]}, {"fr": "Crois-tu qu’il faille beaucoup d’herbe à ce mouton ?", "zh": "你觉得这绵羊需要很多草吗？", "t": [4575, 7512]}]}, {"id": "ch02p28", "audio": true, "sents": [{"fr": "— Pourquoi ?", "zh": "为什么？", "t": [100, 2462]}]}, {"id": "ch02p29", "audio": true, "sents": [{"fr": "— Parce que chez moi c’est tout petit…", "zh": "因为在我的家里地方很小…", "t": [100, 2687]}]}, {"id": "ch02p30", "audio": true, "sents": [{"fr": "— Ça suffira sûrement.", "zh": "这肯定够了。", "t": [100, 3200]}, {"fr": "Je t’ai donné un tout petit mouton.", "zh": "我给你的是一只很小很小的绵羊。", "t": [3200, 4975]}]}, {"id": "ch02p31", "audio": true, "sents": [{"fr": "Il pencha la tête vers le dessin :", "zh": "他低头看画。", "t": [100, 2538]}]}, {"id": "ch02p32", "audio": true, "sents": [{"fr": "— Pas si petit que ça…", "zh": "倒也不小嘛…", "t": [100, 3025]}, {"fr": "Tiens !", "zh": "等等！", "t": [3025, 5088]}, {"fr": "Il s’est endormi…", "zh": "它睡着了…", "t": [5088, 6150]}]}, {"id": "ch02p33", "audio": true, "sents": [{"fr": "Et c’est ainsi que je fis la connaissance du petit prince.", "zh": "就这样，我遇见了小王子。", "t": [100, 2750]}]}, {"id": "ch02p34", "audio": true, "sents": []}]}, {"id": "ch03", "title_fr": "Chapitre III", "title_zh": "第 3 章", "paras": [{"id": "ch03p00", "audio": true, "sents": [{"fr": "Il me fallut longtemps pour comprendre d’où il venait.", "zh": "我费了好长时间才弄懂他来自何方。", "t": [100, 3325]}, {"fr": "Le petit prince, qui me posait beaucoup de questions, ne semblait jamais entendre les miennes.", "zh": "小王子虽向我提问无数，却似乎对我的话充耳不闻。", "t": [3325, 8988]}, {"fr": "Ce sont des mots prononcés par hasard qui, peu à peu, m’ont tout révélé.", "zh": "偶然间说出的只言片语，渐渐向我道出了他的全部秘密。", "t": [8988, 13850]}, {"fr": "Ainsi, quand il aperçut pour la première fois mon avion (je ne dessinerai pas mon avion, c’est un dessin beaucoup trop compliqué pour moi) il me demanda :", "zh": "就这样，他第一次看到我的飞机（我不愿画飞机，这对我说来太复杂了）便问我：", "t": [13850, 22400]}]}, {"id": "ch03p01", "audio": true, "sents": [{"fr": "— Qu’est ce que c’est que cette chose-là ?", "zh": "这是什么玩意儿？", "t": [100, 3388]}]}, {"id": "ch03p02", "audio": true, "sents": [{"fr": "— Ce n’est pas une chose.", "zh": "这不是东西。", "t": [100, 3150]}, {"fr": "Ça vole.", "zh": "这东西会飞。", "t": [3150, 4725]}, {"fr": "C’est un avion.", "zh": "这是飞机。", "t": [4725, 6488]}, {"fr": "C’est mon avion.", "zh": "这是我的飞机。", "t": [6488, 7388]}]}, {"id": "ch03p03", "audio": true, "sents": [{"fr": "Et j’étais fier de lui apprendre que je volais.", "zh": "我自豪地告诉他我会飞。", "t": [100, 3100]}, {"fr": "Alors il s’écria :", "zh": "他突然喊道：", "t": [3100, 5050]}]}, {"id": "ch03p04", "audio": true, "sents": [{"fr": "— Comment !", "zh": "怎么！", "t": [100, 3238]}, {"fr": "tu es tombé du ciel !", "zh": "你是从天上掉下来的吗？", "t": [3238, 4988]}]}, {"id": "ch03p05", "audio": true, "sents": [{"fr": "— Oui, fis-je modestement.", "zh": "是的，我谦逊地回答。", "t": [100, 2750]}]}, {"id": "ch03p06", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "ça c’est drôle…", "zh": "这真有趣…", "t": [3038, 3974]}]}, {"id": "ch03p07", "audio": true, "sents": [{"fr": "Et le petit prince eut un très joli éclat de rire qui m’irrita beaucoup.", "zh": "小王子发出一声清脆的笑声，那笑声让我颇为不快。", "t": [100, 4300]}, {"fr": "Je désire que l’on prenne mes malheurs au sérieux.", "zh": "愿人重视我的不幸。", "t": [4300, 7450]}, {"fr": "Puis il ajouta :", "zh": "然后他又说：", "t": [7450, 9162]}]}, {"id": "ch03p08", "audio": true, "sents": [{"fr": "— Alors, toi aussi tu viens du ciel !", "zh": "那么，你也来自天空！", "t": [100, 4700]}, {"fr": "De quelle planète es-tu ?", "zh": "你来自哪个星球？", "t": [4700, 6524]}]}, {"id": "ch03p09", "audio": true, "sents": [{"fr": "J’entrevis aussitôt une lueur, dans le mystère de sa présence, et j’interrogeai brusquement :", "zh": "我立刻在神秘的他身上瞥见一线光亮，便突然问道：", "t": [100, 5812]}]}, {"id": "ch03p10", "audio": true, "sents": [{"fr": "— Tu viens donc d’une autre planète ?", "zh": "你果然是从另一个星球来的？", "t": [100, 3500]}]}, {"id": "ch03p11", "audio": true, "sents": [{"fr": "Mais il ne me répondit pas.", "zh": "他并未回答。", "t": [100, 2200]}, {"fr": "Il hochait la tête doucement tout en regardant mon avion :", "zh": "轻轻点头，目光落在我的飞机上。", "t": [2200, 5512]}]}, {"id": "ch03p12", "audio": true, "sents": [{"fr": "— C’est vrai que, là-dessus, tu ne peux pas venir de bien loin…", "zh": "这确实，就这架飞机来看，你不可能来自太远的地方……", "t": [100, 4463]}]}, {"id": "ch03p13", "audio": true, "sents": [{"fr": "Et il s’enfonça dans une rêverie qui dura longtemps.", "zh": "他陷入了一段漫长的遐想之中。", "t": [100, 3350]}, {"fr": "Puis, sortant mon mouton de sa poche, il se plongea dans la contemplation de son trésor.", "zh": "然后，他从口袋里掏出我的绵羊，凝视着他的珍宝。", "t": [3350, 8362]}]}, {"id": "ch03p14", "audio": true, "sents": [{"fr": "Vous imaginez combien j’avais pu être intrigué par cette demi-confidence sur \"les autres planètes\".", "zh": "你难以想象，我有多么好奇于他对“其他星球”的半信半疑。", "t": [100, 5950]}, {"fr": "Je m’efforçai donc d’en savoir plus long :", "zh": "我竭力想了解更多……", "t": [5950, 8688]}]}, {"id": "ch03p15", "audio": true, "sents": [{"fr": "— D’où viens-tu mon petit bonhomme ?", "zh": "你这个小家伙是从哪里来的？", "t": [100, 4162]}, {"fr": "Où est-ce \"chez toi\" ?", "zh": "你的家在何方？", "t": [4162, 6775]}, {"fr": "Où veux-tu emporter mon mouton ?", "zh": "你想把我的绵羊带到哪里去？", "t": [6775, 8950]}]}, {"id": "ch03p16", "audio": true, "sents": [{"fr": "Il me répondit après un silence méditatif :", "zh": "他沉思片刻后回答道：", "t": [100, 3138]}]}, {"id": "ch03p17", "audio": true, "sents": [{"fr": "— Ce qui est bien, avec la caisse que tu m’as donnée, c’est que, la nuit, ça lui servira de maison.", "zh": "这箱子给你带来了便利，夜里它就能成为绵羊的住所。", "t": [100, 6587]}]}, {"id": "ch03p18", "audio": true, "sents": [{"fr": "— Bien sûr.", "zh": "当然。", "t": [100, 2750]}, {"fr": "Et si tu es gentil, je te donnerai aussi une corde pour l’attacher pendant le jour.", "zh": "若你听话，我还会给你一根绳子，白天用来拴住它。", "t": [2750, 7788]}, {"fr": "Et un piquet.", "zh": "一根桩子。", "t": [7788, 8513]}]}, {"id": "ch03p19", "audio": true, "sents": [{"fr": "La proposition parut choquer le petit prince :", "zh": "这提议让小王子感到震惊：", "t": [100, 3063]}]}, {"id": "ch03p20", "audio": true, "sents": [{"fr": "— L’attacher ?", "zh": "拴住它？", "t": [100, 3462]}, {"fr": "Quelle drôle d’idée !", "zh": "多么荒唐的想法啊！", "t": [3462, 5200]}]}, {"id": "ch03p21", "audio": true, "sents": [{"fr": "— Mais si tu ne l’attaches pas, il ira n’importe où, et il se perdra…", "zh": "但若不拴住它，它会随意乱跑，迷失了方向。", "t": [100, 4650]}]}, {"id": "ch03p22", "audio": true, "sents": [{"fr": "Et mon ami eut un nouvel éclat de rire :", "zh": "我的朋友又笑了出来：", "t": [100, 2675]}]}, {"id": "ch03p23", "audio": true, "sents": [{"fr": "— Mais où veux-tu qu’il aille !", "zh": "它要去哪里呢？", "t": [100, 2937]}]}, {"id": "ch03p24", "audio": true, "sents": [{"fr": "— N’importe où.", "zh": "无论哪里。", "t": [100, 2775]}, {"fr": "Droit devant lui…", "zh": "正前方…", "t": [2775, 3763]}]}, {"id": "ch03p25", "audio": true, "sents": [{"fr": "Alors le petit prince remarqua gravement :", "zh": "小王子严肃地注意到了：", "t": [100, 2838]}]}, {"id": "ch03p26", "audio": true, "sents": [{"fr": "— Ça ne fait rien, c’est tellement petit, chez moi !", "zh": "那没关系，在我的星球上，它实在太小了！", "t": [100, 4488]}]}, {"id": "ch03p27", "audio": true, "sents": [{"fr": "Et, avec un peu de mélancolie, peut-être, il ajouta :", "zh": "带着一丝淡淡的忧伤，他或许补充道：", "t": [100, 4088]}]}, {"id": "ch03p28", "audio": true, "sents": [{"fr": "Droit devant soi on ne peut pas aller bien loin…", "zh": "身前无路，难行千里。", "t": [100, 2250]}]}, {"id": "ch03p29", "audio": true, "sents": []}, {"id": "ch03p30", "audio": true, "sents": []}]}, {"id": "ch04", "title_fr": "Chapitre IV", "title_zh": "第 4 章", "paras": [{"id": "ch04p00", "audio": true, "sents": [{"fr": "J’avais ainsi appris une seconde chose très importante : C’est que sa planète d’origine était à peine plus grande qu’une maison !", "zh": "他的星球原本不过比一座房子大些。", "t": [100, 7250]}]}, {"id": "ch04p01", "audio": true, "sents": [{"fr": "Ça ne pouvait pas m’étonner beaucoup.", "zh": "这并不让我感到特别惊讶。", "t": [100, 2662]}, {"fr": "Je savais bien qu’en dehors des grosses planètes comme la Terre, Jupiter, Mars, Vénus, auxquelles on a donné des noms, il y en a des centaines d’autres qui sont quelque-fois si petites qu’on a beaucoup de mal à les apercevoir au télescope.", "zh": "我知道，除了那些被赋予名字的大行星，如地球、木星、火星、金星，还有无数其他星球，有时它们如此之小，以至于用望远镜都很难辨认。", "t": [2662, 15575]}, {"fr": "Quand un astronome découvre l’une d’elles, il lui donne pour nom un numéro.", "zh": "当一位天文学家发现其中一颗，便以数字为其命名。", "t": [15575, 20338]}, {"fr": "Il l’appelle par exemple : \"l’astéroïde 3251.\"", "zh": "他称之为“小行星3251号”。", "t": [20338, 24713]}]}, {"id": "ch04p02", "audio": true, "sents": [{"fr": "J’ai de sérieuses raisons de croire que la planète d’où venait le petit prince est l’astéroïde B 612.", "zh": "我有充分的理由相信小王子来自B612号小行星。", "t": [100, 4638]}, {"fr": "Cet astéroïde n’a été aperçu qu’une fois au télescope, en 1909, par un astronome turc.", "zh": "这颗小行星仅在一九〇九年被一位土耳其天文学家通过望远镜观测到一次。", "t": [4638, 12162]}]}, {"id": "ch04p03", "audio": true, "sents": [{"fr": "Il avait fait alors une grande démonstration de sa découverte à un Congrès International d’Astronomie.", "zh": "他在国际天文会议上为他的发现做了精彩的展示。", "t": [100, 6175]}, {"fr": "Mais personne ne l’avait cru à cause de son costume.", "zh": "但无人信他，只因他身着土耳其装束。", "t": [6175, 9525]}, {"fr": "Les grandes personnes sont comme ça.", "zh": "大人们就是这样。", "t": [9525, 11225]}]}, {"id": "ch04p04", "audio": true, "sents": [{"fr": "Heureusement pour la réputation de l’astéroïde B 612 un dictateur turc imposa à son peuple, sous peine de mort, de s’habiller à l’Européenne.", "zh": "幸而，为了B612小行星的声誉，土耳其独裁者强迫其国民欧洲化着装，违者处以死刑。", "t": [100, 9550]}, {"fr": "L’astronome refit sa démonstration en 1920, dans un habit très élégant.", "zh": "1920年，天文学家身着盛装，再次进行了他的论证。", "t": [9550, 14162]}, {"fr": "Et cette fois-ci tout le monde fut de son avis.", "zh": "这次所有人都赞同他的观点。", "t": [14162, 16400]}]}, {"id": "ch04p05", "audio": true, "sents": [{"fr": "Si je vous ai raconté ces détails sur l’astéroïde B 612 et si je vous ai confié son numéro, c’est à cause des grandes personnes.", "zh": "若非因大人之故，我才不会向你们透露B612小行星的细节与它的编号。", "t": [100, 7838]}, {"fr": "Les grandes personnes aiment les chiffres.", "zh": "大人们偏爱数字。", "t": [7838, 10325]}, {"fr": "Quand vous leur parlez d’un nouvel ami, elles ne vous questionnent jamais sur l’essentiel.", "zh": "谈及新朋友，他们从不询问其本质。", "t": [10325, 15112]}, {"fr": "Elles ne vous disent jamais : \"Quel est le son de sa voix ?", "zh": "他们从不会问：“他的嗓音如何？”", "t": [15112, 19850]}, {"fr": "Quels sont les jeux qu’il préfère ?", "zh": "他最喜欢玩什么游戏？", "t": [19850, 22725]}, {"fr": "Est-ce qu’il collectionne les papillons ?\" Elles vous demandent : \"Quel âge a-t-il ?", "zh": "她问：“他收集蝴蝶吗？”", "t": [22725, 29912]}, {"fr": "Combien a-t-il de frères ?", "zh": "他有多少个兄弟？", "t": [29912, 32612]}, {"fr": "Combien pèse-t-il ?", "zh": "他有多重？", "t": [32612, 34988]}, {"fr": "Combien gagne son père ?\" Alors seulement elles croient le connaître.", "zh": "他父亲挣多少钱？那时她们才相信他们了解这个人。", "t": [34988, 40262]}, {"fr": "Si vous dites aux grandes personnes : \"J’ai vu une belle maison en briques roses, avec des géraniums aux fenêtres et des colombes sur le toit…\" elles ne parviennent pas à s’imaginer cette maison.", "zh": "您若对大人说：“我看见一幢粉红砖砌的房子，窗台上种着天竺葵，屋顶栖息着鸽子……”他们便无法想象这房子的模样。", "t": [40262, 51275]}, {"fr": "Il faut leur dire : \"J’ai vu une maison de cent mille francs.\" Alors elles s’écrient : \"Comme c’est joli !\"", "zh": "那得对他们说：“我看见一幢值十万法郎的房子。”她们就会惊叹：“多漂亮的房子啊！”", "t": [51275, 59050]}]}, {"id": "ch04p06", "audio": true, "sents": [{"fr": "Ainsi, si vous leur dites : \"La preuve que le petit prince a existé c’est qu’il était ravissant, qu’il riait, et qu’il voulait un mouton.", "zh": "因此，若你对大人说：“小王子曾存在过，是因为他可爱、爱笑，且渴望拥有一只绵羊。”", "t": [100, 8488]}, {"fr": "Quand on veut un mouton, c’est la preuve qu’on existe\" elles hausseront les épaules et vous traiteront d’enfant !", "zh": "若一个人渴望拥有一只绵羊，那便是他存在的证明，她们便会耸耸肩，把你当作孩子看待。", "t": [8488, 14612]}, {"fr": "Mais si vous leur dites : \"La planète d’où il venait est l’astéroïde B 612\" alors elles seront convaincues, et elles vous laisseront tranquille avec leurs questions.", "zh": "但若你对她们说：“他来自B612号小行星”，她们便会信服，不再用那些没完没了的问题打扰你。", "t": [14612, 23888]}, {"fr": "Elles sont comme ça.", "zh": "她们就是这样。", "t": [23888, 25725]}, {"fr": "Il ne faut pas leur en vouloir.", "zh": "不必怪罪他们。", "t": [25725, 28088]}, {"fr": "Les enfants doivent être très indulgents envers les grandes personnes.", "zh": "孩子们对大人应当格外宽容。", "t": [28088, 31312]}]}, {"id": "ch04p07", "audio": true, "sents": [{"fr": "Mais, bien sûr, nous qui comprenons la vie, nous nous moquons bien des numéros !", "zh": "然而，我们这些懂得生活的人，对数字根本不屑一顾！", "t": [100, 6125]}, {"fr": "J’aurais aimé commencer cette histoire à la façon des contes de fées.", "zh": "我本想以童话的方式开始这个故事。", "t": [6125, 10262]}, {"fr": "J’aurais aimé dire :", "zh": "我本想告诉你们：", "t": [10262, 11925]}]}, {"id": "ch04p08", "audio": true, "sents": [{"fr": "\"Il était une fois un petit prince qui habitait une planète à peine plus grande que lui, et qui avait besoin d’un ami…\" Pour ceux qui comprennent la vie, ça aurait eu l’air beaucoup plus vrai.", "zh": "从前有个小王子，他住在一颗比他本人略大的星球上，渴望一位朋友……对于懂得生活的人来说，这样的说法似乎更为真实。", "t": [100, 9538]}]}, {"id": "ch04p09", "audio": true, "sents": [{"fr": "Car je n’aime pas qu’on lise mon livre à la légère.", "zh": "我不喜欢别人轻率地读我的书。", "t": [100, 3375]}, {"fr": "J’éprouve tant de chagrin à raconter ces souvenirs.", "zh": "讲述这些往事，我心中满是忧伤。", "t": [3375, 6925]}, {"fr": "Il y a six ans déjà que mon ami s’en est allé avec son mouton.", "zh": "六年前，我的朋友带着他的绵羊离去了。", "t": [6925, 10812]}, {"fr": "Si j’essaie ici de le décrire, c’est afin de ne pas l’oublier.", "zh": "我试图在此描述他，以免将他遗忘。", "t": [10812, 15262]}, {"fr": "C’est triste d’oublier un ami.", "zh": "遗忘朋友是件悲伤的事。", "t": [15262, 17562]}, {"fr": "Tout le monde n’a pas eu un ami.", "zh": "并非人人都有过朋友。", "t": [17562, 20050]}, {"fr": "Et je puis devenir comme les grandes personnes qui ne s’intéressent plus qu’aux chiffres.", "zh": "我或许会变成像大人们那样，只对数字感兴趣的人。", "t": [20050, 24525]}, {"fr": "C’est donc pour ça encore que j’ai acheté une boîte de couleurs et des crayons.", "zh": "因此，我这才又买了一盒颜料和几枝铅笔。", "t": [24525, 29188]}, {"fr": "C’est dur de se remettre au dessin, à mon âge, quand on n’a jamais fait d’autres tentatives que celle d’un boa fermé et celle d’un boa ouvert, à l’âge de six ans !", "zh": "重拾画笔，对我而言，已是难事，毕竟我六岁时仅尝试过画一条闭合的蟒蛇和一条开口的蟒蛇！", "t": [29188, 38762]}, {"fr": "J’essaierai, bien sûr, de faire des portraits le plus ressemblants possible.", "zh": "我将尽力画出尽可能逼真的肖像。", "t": [38762, 43912]}, {"fr": "Mais je ne suis pas tout à fait certain de réussir.", "zh": "但我并不完全确信能成功。", "t": [43912, 47112]}, {"fr": "Un dessin va, et l’autre ne ressemble plus.", "zh": "一幅画得可以，另一幅却画得不像。", "t": [47112, 50375]}, {"fr": "Je me trompe un peu aussi sur la taille.", "zh": "我也对它的尺寸有些误差。", "t": [50375, 53250]}, {"fr": "Ici le petit prince est trop grand.", "zh": "小王子在这里太大了。", "t": [53250, 55738]}, {"fr": "Là il est trop petit.", "zh": "那里他太小了。", "t": [55738, 57738]}, {"fr": "J’hésite aussi sur la couleur de son costume.", "zh": "我也犹豫不决于他服装的颜色。", "t": [57738, 60925]}, {"fr": "Alors je tâtonne comme ci et comme ça, tant bien que mal.", "zh": "我摸索着，笨拙地前行。", "t": [60925, 64912]}, {"fr": "Je me tromperai enfin sur certains détails plus importants.", "zh": "最终，我在某些重要细节上也会出错。", "t": [64912, 68650]}, {"fr": "Mais ça, il faudra me le pardonner.", "zh": "但这一点，你们要原谅我。", "t": [68650, 71588]}, {"fr": "Mon ami ne donnait jamais d’explications.", "zh": "我的朋友从不解释。", "t": [71588, 74588]}, {"fr": "Il me croyait peut-être semblable à lui.", "zh": "他或许觉得我与他相似。", "t": [74588, 77588]}, {"fr": "Mais moi, malheureusement, je ne sais pas voir les moutons à travers les caisses.", "zh": "但我，不幸的是，我看不见箱子里的绵羊。", "t": [77588, 82488]}, {"fr": "Je suis peut-être un peu comme les grandes personnes.", "zh": "也许我有点像大人们了。", "t": [82488, 85612]}, {"fr": "J’ai dû vieillir.", "zh": "我已老去。", "t": [85612, 86674]}]}, {"id": "ch04p10", "audio": true, "sents": []}]}, {"id": "ch05", "title_fr": "Chapitre V", "title_zh": "第 5 章", "paras": [{"id": "ch05p00", "audio": true, "sents": [{"fr": "Chaque jour j’apprenais quelque chose sur la planète, sur le départ, sur le voyage.", "zh": "每日，我都能从这颗星球、启程、旅行中领悟到些什么。", "t": [100, 5562]}, {"fr": "Ça venait tout doucement, au hasard des réflexions.", "zh": "这都是在闲聊中不经意间领悟到的。", "t": [5562, 9162]}, {"fr": "C’est ainsi que, le troisième jour, je connus le drame des baobabs.", "zh": "就这样，第三天，我了解了猴面包树的悲剧。", "t": [9162, 13026]}]}, {"id": "ch05p01", "audio": true, "sents": [{"fr": "Cette fois-ci encore ce fut grâce au mouton, car brusquement le petit prince m’interrogea, comme pris d’un doute grave :", "zh": "这次又是多亏了绵羊，因为小王子突然向我提出一个严重的疑问：", "t": [100, 6563]}]}, {"id": "ch05p02", "audio": true, "sents": [{"fr": "— C’est bien vrai, n’est-ce pas, que les moutons mangent les arbustes ?", "zh": "这真是的，羊儿确实会吃灌木吗？", "t": [100, 5025]}]}, {"id": "ch05p03", "audio": true, "sents": [{"fr": "— Oui.", "zh": "是的。", "t": [100, 2400]}, {"fr": "C’est vrai.", "zh": "是真的。", "t": [2400, 3000]}]}, {"id": "ch05p04", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "Je suis content.", "zh": "我挺高兴。", "t": [3038, 3938]}]}, {"id": "ch05p05", "audio": true, "sents": [{"fr": "Je ne compris pas pourquoi il était si important que les moutons mangeassent les arbustes.", "zh": "我不明白为什么绵羊吃灌木这么重要。", "t": [100, 5062]}, {"fr": "Mais le petit prince ajouta :", "zh": "小王子接着说：", "t": [5062, 7288]}]}, {"id": "ch05p06", "audio": true, "sents": [{"fr": "— Par conséquent ils mangent aussi les baobabs ?", "zh": "因此，它们也吃猴面包树吗？", "t": [100, 3850]}]}, {"id": "ch05p07", "audio": true, "sents": [{"fr": "Je fis remarquer au petit prince que les baobabs ne sont pas des arbustes, mais des arbres grand comme des églises et que, si même il emportait avec lui tout un troupeau d’éléphants, ce troupeau ne viendrait pas à bout d’un seul baobab.", "zh": "我向小王子指出，猴面包树并非灌木，而是像教堂一般高大的树木，即便他带上一群大象，也无法将一棵猴面包树啃食殆尽。", "t": [100, 11200]}]}, {"id": "ch05p08", "audio": true, "sents": [{"fr": "L’idée du troupeau d’éléphants fit rire le petit prince :", "zh": "那群大象的念头让小王子忍不住笑了。", "t": [100, 3338]}]}, {"id": "ch05p09", "audio": true, "sents": [{"fr": "— Il faudrait les mettre les uns sur les autres…", "zh": "它们得一个挨一个地叠上去…", "t": [100, 3013]}]}, {"id": "ch05p10", "audio": true, "sents": [{"fr": "Mais il remarqua avec sagesse :", "zh": "但他明智地注意到了：", "t": [100, 2437]}]}, {"id": "ch05p11", "audio": true, "sents": [{"fr": "— Les baobabs, avant de grandir, ça commence par être petit.", "zh": "猴面包树，在长成大树之前，起初只是小小的。", "t": [100, 4837]}]}, {"id": "ch05p12", "audio": true, "sents": [{"fr": "— C’est exact !", "zh": "是的，没错！", "t": [100, 3512]}, {"fr": "Mais pourquoi veux-tu que tes moutons mangent les petits baobabs ?", "zh": "可你为何要让你的绵羊吃掉那些小猴面包树呢？", "t": [3512, 6974]}]}, {"id": "ch05p13", "audio": true, "sents": [{"fr": "Il me répondit : \"Ben !", "zh": "嘿！", "t": [100, 3875]}, {"fr": "Voyons !\" comme s’il s’agissait là d’une évidence.", "zh": "嘿！这还用说吗！", "t": [3875, 8162]}, {"fr": "Et il me fallut un grand effort d’intelligence pour comprendre à moi seul ce problème.", "zh": "我费尽心思才独自想明白这个问题。", "t": [8162, 12213]}]}, {"id": "ch05p14", "audio": true, "sents": [{"fr": "Et en effet, sur la planète du petit prince, il y avait comme sur toutes les planètes, de bonnes herbes et de mauvaises herbes.", "zh": "在这颗小王子的星球上，正如所有星球一样，既有好草也有坏草。", "t": [100, 7512]}, {"fr": "Par conséquent de bonnes graines de bonnes herbes et de mauvaises graines de mauvaises herbes.", "zh": "因此，既有好草的种子，也有坏草的种子。", "t": [7512, 12162]}, {"fr": "Mais les graines sont invisibles.", "zh": "种子是看不见的。", "t": [12162, 14675]}, {"fr": "Elles dorment dans le secret de la terre jusqu’à ce qu’il prenne fantaisie à l’une d’elles de se réveiller.", "zh": "它们在土地的秘密中沉睡，直至其中一颗突发奇想，苏醒过来。", "t": [14675, 19900]}, {"fr": "Alors elle s’étire, et pousse d’abord timidement vers le soleil une ravissante petite brindille inoffensive.", "zh": "于是她伸展身躯，首先怯生生地向着太阳伸出一片迷人的小嫩枝。", "t": [19900, 26212]}, {"fr": "S’il s’agît d’une brindille de radis ou de rosier, on peut la laisser pousser comme elle veut.", "zh": "若是一株萝卜苗或玫瑰苗，任其生长也无妨。", "t": [26212, 61863]}, {"fr": "Mais s’il s’agit d’une mauvaise plante, il faut arracher la plante aussitôt, dès qu’on a su la reconnaître.", "zh": "若是有毒的植物，一经认出，就必须立刻拔除。", "t": [61863, 62363]}, {"fr": "Or il y avait des graines terribles sur la planète du petit prince…", "zh": "在这颗小王子的星球上，埋藏着可怕的种子……", "t": [62363, 62863]}, {"fr": "c’étaient les graines de baobabs.", "zh": "那是猴面包树的种子。", "t": [62863, 63363]}, {"fr": "Le sol de la planète en était infesté.", "zh": "这颗星球的土壤里满是它们。", "t": [63363, 63863]}, {"fr": "Or un baobab, si l’on s’y prend trop tard, on ne peut jamais plus s’en débarrasser.", "zh": "若是对抗猴面包树，一旦错过时机，便永远无法摆脱。", "t": [63863, 64363]}, {"fr": "Il encombre toute la planète.", "zh": "它占据了整个星球。", "t": [64363, 64863]}, {"fr": "Il la perfore de ses racines.", "zh": "它用根须穿透大地。", "t": [64863, 65363]}, {"fr": "Et si la planète est trop petite, et si les baobabs sont trop nombreux, ils la font éclater.", "zh": "若星球太小，而猴面包树又太多，它们就会把星球撑爆。", "t": [65363, 65863]}]}, {"id": "ch05p15", "audio": true, "sents": [{"fr": "\"C’est une question de discipline, me disait plus tard le petit prince.", "zh": "这是纪律问题，小王子后来对我说。", "t": [100, 4625]}, {"fr": "Quand on a terminé sa toilette du matin, il faut faire soigneusement la toilette de la planète.", "zh": "晨起梳洗后，须细心打理地球之容。", "t": [4625, 10500]}, {"fr": "Il faut s’astreindre régulièrement à arracher les baobabs dès qu’on les distingue d’avec les rosiers auxquels ils ressemblent beaucoup quand ils sont très jeunes.", "zh": "必须经常努力，一旦将它们与极相似的玫瑰花苗区分开来，就拔除那些猴面包树。", "t": [10500, 18362]}, {"fr": "C’est un travail très ennuyeux, mais très facile.\"", "zh": "这是一件单调乏味，却也容易完成的工作。", "t": [18362, 21100]}]}, {"id": "ch05p16", "audio": true, "sents": [{"fr": "Et un jour il me conseilla de m’appliquer à réussir un beau dessin, pour bien faire entrer ça dans la tête des enfants de chez moi.", "zh": "他建议我精心绘制一幅美丽的图画，以便让我的家乡孩子们深刻记住这一切。", "t": [100, 7075]}, {"fr": "\"S’ils voyagent un jour, me disait-il, ça pourra leur servir.", "zh": "若他们日后旅行，他说，这或许能帮上忙。", "t": [7075, 11762]}, {"fr": "Il est quelquefois sans inconvénient de remettre à plus tard son travail.", "zh": "有时推迟工作并无不妥。", "t": [11762, 16062]}, {"fr": "Mais, s’il s’agit des baobabs, c’est toujours une catastrophe.", "zh": "但若是猴面包树，那便是一场灾难。", "t": [16062, 20550]}, {"fr": "J’ai connu une planète, habitée par un paresseux.", "zh": "我曾见过一颗被懒惰者居住的星球。", "t": [20550, 24062]}, {"fr": "Il avait négligé trois arbustes…\"", "zh": "他忽略了三棵灌木……", "t": [24062, 25825]}]}, {"id": "ch05p17", "audio": true, "sents": [{"fr": "Et, sur les indications du petit prince, j’ai dessiné cette planète-là.", "zh": "根据小王子的指引，我画下了这颗星球。", "t": [100, 4775]}, {"fr": "Je n’aime guère prendre le ton d’un moraliste.", "zh": "我不喜欢摆出一副道德家的架势。", "t": [4775, 7812]}, {"fr": "Mais le danger des baobabs est si peu connu, et les risques courus par celui qui s’égarerait dans un astéroïde sont si considérables, que, pour une fois, je fais exception à ma réserve.", "zh": "但猴面包树的危险鲜为人知，而在小行星上迷路的风险又如此巨大，我这次破例打破了我的矜持。", "t": [7812, 18612]}, {"fr": "Je dis : \"Enfants !", "zh": "孩子们！", "t": [18612, 22125]}, {"fr": "Faites attention aux baobabs !\" C’est pour avertir mes amis d’un danger qu’ils frôlaient depuis longtemps, comme moi-même, sans le connaître, que j’ai tant travaillé ce dessin-là.", "zh": "孩子们，当心猴面包树！这是为了警示我的朋友们一个他们长期以来几乎不知晓的危险，就像我自己一样。", "t": [22125, 33025]}, {"fr": "La leçon que je donnais en valait la peine.", "zh": "这课教得值。", "t": [33025, 35912]}, {"fr": "Vous vous demanderez peut-être : Pourquoi n’y a-t-il pas, dans ce livre, d’autres dessins aussi grandioses que le dessin des baobabs ?", "zh": "你们或许会问：为什么在这本书里，没有其他图画像猴面包树的画那样雄伟壮观？", "t": [35912, 44550]}, {"fr": "La réponse est bien simple : J’ai essayé mais je n’ai pas pu réussir.", "zh": "答案很简单：我尽力了，但未能成功。", "t": [44550, 49688]}, {"fr": "Quand j’ai dessiné les baobabs j’ai été animé par le sentiment de l’urgence.", "zh": "我绘制猴面包树时，心中充满了紧迫感。", "t": [49688, 53475]}]}, {"id": "ch05p18", "audio": true, "sents": []}]}, {"id": "ch06", "title_fr": "Chapitre VI", "title_zh": "第 6 章", "paras": [{"id": "ch06p00", "audio": true, "sents": [{"fr": "Ah !", "zh": "啊！", "t": [100, 2012]}, {"fr": "petit prince, j’ai compris, peu à peu, ainsi, ta petite vie mélancolique.", "zh": "小王子，我逐渐明白，你的小生活充满了忧郁。", "t": [2012, 7712]}, {"fr": "Tu n’avais eu longtemps pour distraction que la douceur des couchers de soleil.", "zh": "你长久以来，唯一的慰藉便是那夕阳的温柔。", "t": [7712, 12088]}, {"fr": "J’ai appris ce détail nouveau, le quatrième jour au matin, quand tu m’as dit :", "zh": "第四天早晨，你告诉我这个新细节：", "t": [12088, 16788]}]}, {"id": "ch06p01", "audio": true, "sents": [{"fr": "— J’aime bien les couchers de soleil.", "zh": "我喜爱那夕阳的降临。", "t": [100, 3738]}, {"fr": "Allons voir un coucher de soleil…", "zh": "我们去看看日落吧…", "t": [3738, 5387]}]}, {"id": "ch06p02", "audio": true, "sents": [{"fr": "— Mais il faut attendre…", "zh": "但得耐心等待…", "t": [100, 2362]}]}, {"id": "ch06p03", "audio": true, "sents": [{"fr": "— Attendre quoi ?", "zh": "等待什么？", "t": [100, 2750]}]}, {"id": "ch06p04", "audio": true, "sents": [{"fr": "— Attendre que le soleil se couche.", "zh": "等待太阳落山。", "t": [100, 2987]}]}, {"id": "ch06p05", "audio": true, "sents": [{"fr": "Tu as eu l’air très surpris d’abord, et puis tu as ri de toi-même.", "zh": "你先是惊讶不已，接着又对自己笑了出来。", "t": [100, 4325]}, {"fr": "Et tu m’as dit :", "zh": "你曾对我说：", "t": [4325, 5775]}]}, {"id": "ch06p06", "audio": true, "sents": [{"fr": "— Je me crois toujours chez moi !", "zh": "我总觉得还在自己家里！", "t": [100, 3212]}]}, {"id": "ch06p07", "audio": true, "sents": [{"fr": "En effet.", "zh": "的确如此。", "t": [100, 1550]}, {"fr": "Quand il est midi aux États-Unis, le soleil, tout le monde le sait, se couche sur la France.", "zh": "当美国正午时分，众所周知，太阳便西沉法国。", "t": [1550, 7600]}, {"fr": "Il suffirait de pouvoir aller en France en une minute pour assister au coucher de soleil.", "zh": "只需片刻便可达法国，目睹落日余晖。", "t": [7600, 12838]}, {"fr": "Malheureusement la France est bien trop éloignée.", "zh": "遗憾的是法国太远了。", "t": [12838, 15975]}, {"fr": "Mais, sur ta si petite planète, il te suffisait de tirer ta chaise de quelques pas.", "zh": "然而，在你的那颗小小星球上，你只需把椅子挪动几步。", "t": [15975, 21350]}, {"fr": "Et tu regardais le crépuscule chaque fois que tu le désirais…", "zh": "你随时想看，便观赏那黄昏时分。", "t": [21350, 24200]}]}, {"id": "ch06p08", "audio": true, "sents": [{"fr": "— Un jour, j’ai vu le soleil se coucher quarante-trois fois !", "zh": "那天，我目睹了四十三次日落。", "t": [100, 4750]}]}, {"id": "ch06p09", "audio": true, "sents": [{"fr": "Et un peu plus tard tu ajoutais :", "zh": "过了一会儿，你又说道：", "t": [100, 2400]}]}, {"id": "ch06p10", "audio": true, "sents": [{"fr": "— Tu sais…", "zh": "你知道……", "t": [100, 1888]}, {"fr": "quand on est tellement triste on aime les couchers de soleil…", "zh": "当极度悲伤时，我们偏爱那日落时分。", "t": [1888, 4325]}]}, {"id": "ch06p11", "audio": true, "sents": [{"fr": "Le jour des quarante-trois fois tu étais donc tellement triste ?", "zh": "那天，你为何如此悲伤至极？", "t": [100, 4400]}, {"fr": "Mais le petit prince ne répondit pas.", "zh": "小王子并未作答。", "t": [4400, 6162]}]}, {"id": "ch06p12", "audio": true, "sents": []}]}, {"id": "ch07", "title_fr": "Chapitre VII", "title_zh": "第 7 章", "paras": [{"id": "ch07p00", "audio": true, "sents": [{"fr": "Le cinquième jour, toujours grâce au mouton, ce secret de la vie du petit prince me fut révélé.", "zh": "第五天，多亏了那只绵羊，小王子的生活秘密终于被揭露。", "t": [100, 6162]}, {"fr": "Il me demanda avec brusquerie, sans préambule, comme le fruit d’un problème longtemps médité en silence :", "zh": "他突然打断我，未经任何寒暄，仿佛是长久沉默中深思熟虑后的产物，问道：", "t": [6162, 12300]}]}, {"id": "ch07p01", "audio": true, "sents": [{"fr": "— Un mouton, s’il mange les arbustes, il mange aussi les fleurs ?", "zh": "绵羊吃灌木，它也吃花吗？", "t": [100, 5113]}]}, {"id": "ch07p02", "audio": true, "sents": [{"fr": "— Un mouton mange tout ce qu’il rencontre.", "zh": "绵羊遇见什么吃什么。", "t": [100, 3126]}]}, {"id": "ch07p03", "audio": true, "sents": [{"fr": "— Même les fleurs qui ont des épines ?", "zh": "连带刺的花也吃吗？", "t": [100, 3350]}]}, {"id": "ch07p04", "audio": true, "sents": [{"fr": "— Oui.", "zh": "是的。", "t": [100, 2400]}, {"fr": "Même les fleurs qui ont des épines.", "zh": "连带刺的花也吃。", "t": [2400, 4050]}]}, {"id": "ch07p05", "audio": true, "sents": [{"fr": "— Alors les épines, à quoi servent-elles ?", "zh": "那么，刺有什么用呢？", "t": [100, 3800]}]}, {"id": "ch07p06", "audio": true, "sents": [{"fr": "Je ne le savais pas.", "zh": "我并不知情。", "t": [100, 1962]}, {"fr": "J’étais alors très occupé à essayer de dévisser un boulon trop serré de mon moteur.", "zh": "那时我正忙于拧下发动机上那个过紧的螺栓。", "t": [1962, 7075]}, {"fr": "J’étais très soucieux car ma panne commençait de m’apparaître comme très grave, et l’eau à boire qui s’épuisait me faisait craindre le pire.", "zh": "我忧心忡忡，因为故障似乎愈发严重，而饮水的日益减少让我担忧不已。", "t": [7075, 13762]}]}, {"id": "ch07p07", "audio": true, "sents": [{"fr": "— Les épines, à quoi servent-elles ?", "zh": "刺，它们有何用？", "t": [100, 3538]}]}, {"id": "ch07p08", "audio": true, "sents": [{"fr": "Le petit prince ne renonçait jamais à une question, une fois qu’il l’avait posée.", "zh": "小王子一旦提出疑问，便决不放弃。", "t": [100, 4950]}, {"fr": "J’étais irrité par mon boulon et je répondis n’importe quoi :", "zh": "我因那螺栓而烦躁，随口胡乱回答：", "t": [4950, 8800]}]}, {"id": "ch07p09", "audio": true, "sents": [{"fr": "— Les épines, ça ne sert à rien, c’est de la pure méchanceté de la part des fleurs !", "zh": "刺，不过是花儿们的一时恶作剧！", "t": [100, 5975]}]}, {"id": "ch07p10", "audio": true, "sents": [{"fr": "— Oh !", "zh": "哦！", "t": [100, 2176]}]}, {"id": "ch07p11", "audio": true, "sents": [{"fr": "Mais après un silence il me lança, avec une sorte de rancune :", "zh": "但沉默片刻后，他带着几分怨恨地向我投来：", "t": [100, 4063]}]}, {"id": "ch07p12", "audio": true, "sents": [{"fr": "— Je ne te crois pas !", "zh": "我不信你的话！", "t": [100, 3625]}, {"fr": "Les fleurs sont faibles.", "zh": "花儿柔弱无力。", "t": [3625, 5725]}, {"fr": "Elles sont naïves.", "zh": "她们天真无邪。", "t": [5725, 7462]}, {"fr": "Elles se rassurent comme elles peuvent.", "zh": "她们尽力安慰自己。", "t": [7462, 9875]}, {"fr": "Elles se croient terribles avec leurs épines…", "zh": "她们自以为有了刺就了不起。", "t": [9875, 11875]}]}, {"id": "ch07p13", "audio": true, "sents": [{"fr": "Je ne répondis rien.", "zh": "我无言以对。", "t": [100, 2225]}, {"fr": "A cet instant-là je me disais : \"Si ce boulon résiste encore, je le ferai sauter d’un coup de marteau.\" Le petit prince dérangea de nouveau mes réflexions :", "zh": "此刻我心想：“要是这螺栓还硬撑着，我就一锤子把它砸下来。”小王子又打断了我的思路：", "t": [2225, 12438]}]}, {"id": "ch07p14", "audio": true, "sents": [{"fr": "— Et tu crois, toi, que les fleurs…", "zh": "你也相信，你，相信花儿……", "t": [100, 3187]}]}, {"id": "ch07p15", "audio": true, "sents": [{"fr": "— Mais non !", "zh": "但不是！", "t": [100, 3200]}, {"fr": "Mais non !", "zh": "但不是！", "t": [3200, 5312]}, {"fr": "Je ne crois rien !", "zh": "我什么都不信！", "t": [5312, 7900]}, {"fr": "J’ai répondu n’importe quoi.", "zh": "随口胡言乱语。", "t": [7900, 10362]}, {"fr": "Je m’occupe, moi, de choses sérieuses !", "zh": "我忙的是正事！", "t": [10362, 13476]}]}, {"id": "ch07p16", "audio": true, "sents": [{"fr": "Il me regarda stupéfiait.", "zh": "他惊讶地望着我。", "t": [100, 1600]}]}, {"id": "ch07p17", "audio": true, "sents": [{"fr": "— De choses sérieuses !", "zh": "事关重大！", "t": [100, 2826]}]}, {"id": "ch07p18", "audio": true, "sents": [{"fr": "Il me voyait, mon marteau à la main, et les doigts noirs de cambouis, penché sur un objet qui lui semblait très laid.", "zh": "他瞧见我手持锤子，指头沾满油污，俯身对着他看来颇为丑陋的物件。", "t": [100, 6000]}]}, {"id": "ch07p19", "audio": true, "sents": [{"fr": "— Tu parles comme les grandes personnes !", "zh": "你说话就像大人一样！", "t": [100, 3375]}]}, {"id": "ch07p20", "audio": true, "sents": [{"fr": "Ça me fit un peu honte.", "zh": "我感到有些羞愧。", "t": [100, 2250]}, {"fr": "Mais, impitoyable, il ajouta :", "zh": "然而，无情地，他又补充道：", "t": [2250, 5250]}]}, {"id": "ch07p21", "audio": true, "sents": [{"fr": "— Tu confonds tout…", "zh": "你混淆了一切…", "t": [100, 2162]}, {"fr": "tu mélanges tout !", "zh": "你混淆了一切！", "t": [2162, 3675]}]}, {"id": "ch07p22", "audio": true, "sents": [{"fr": "Il était vraiment très irrité.", "zh": "他真的非常恼火。", "t": [100, 2550]}, {"fr": "Il secouait au vent des cheveux tout dorés :", "zh": "风中，那头金发随风飘扬。", "t": [2550, 5162]}]}, {"id": "ch07p23", "audio": true, "sents": [{"fr": "— Je connais une planète où il y a un Monsieur cramoisi.", "zh": "我认识一颗星球，上面住着一位红脸先生。", "t": [100, 4450]}, {"fr": "Il n’a jamais respiré une fleur.", "zh": "他从未呼吸过一朵花的气息。", "t": [4450, 7125]}, {"fr": "Il n’a jamais regardé une étoile.", "zh": "他从没看过一颗星星。", "t": [7125, 9838]}, {"fr": "Il n’a jamais aimé personne.", "zh": "他从未爱过任何人。", "t": [9838, 12225]}, {"fr": "Il n’a jamais rien fait d’autre que des additions.", "zh": "他一生只做过加法。", "t": [12225, 15325]}, {"fr": "Et toute la journée il répète comme toi : \"Je suis un homme sérieux !", "zh": "他整天就像你一样，反复地唠叨：“我是个正经人！”", "t": [15325, 20938]}, {"fr": "Je suis un homme sérieux !\" et ça le fait gonfler d’orgueil.", "zh": "“我是个严肃的人！”这话让他颇为自得。", "t": [20938, 25638]}, {"fr": "Mais ce n’est pas un homme, c’est un champignon !", "zh": "但这不是人，是蘑菇！", "t": [25638, 28562]}]}, {"id": "ch07p24", "audio": true, "sents": [{"fr": "— Un quoi ?", "zh": "这是什么？", "t": [100, 2412]}]}, {"id": "ch07p25", "audio": true, "sents": [{"fr": "— Un champignon !", "zh": "这不过是个蘑菇！", "t": [100, 2687]}]}, {"id": "ch07p26", "audio": true, "sents": [{"fr": "Le petit prince était maintenant tout pâle de colère.", "zh": "小王子气得脸色煞白。", "t": [100, 2662]}]}, {"id": "ch07p27", "audio": true, "sents": [{"fr": "— Il y a des millions d’années que les fleurs fabriquent des épines.", "zh": "数百万年来，花儿们一直在编织荆棘。", "t": [100, 4625]}, {"fr": "Il y a des millions d’années que les moutons mangent quand même les fleurs.", "zh": "数百万年来，绵羊依旧在吞噬花朵。", "t": [4625, 8500]}, {"fr": "Et ce n’est pas sérieux de chercher à comprendre pourquoi elles se donnent tant de mal pour se fabriquer des épines qui ne servent jamais à rien ?", "zh": "这岂是正经事，探究她们为何费尽心机长出那些毫无用处的刺？", "t": [8500, 16288]}, {"fr": "Ce n’est pas important la guerre des moutons et des fleurs ?", "zh": "羊与花的战争，这又何干？", "t": [16288, 20250]}, {"fr": "Ce n’est pas plus sérieux et plus important que les additions d’un gros Monsieur rouge ?", "zh": "这难道不比那位红脸先生的加法更严肃、更重要吗？", "t": [20250, 25388]}, {"fr": "Et si je connais, moi, une fleur unique au monde, qui n’existe nulle part, sauf dans ma planète, et qu’un petit mouton peut anéantir d’un seul coup, comme ça, un matin, sans se rendre compte de ce qu’il fait, ce n’est pas important ça !", "zh": "若我知晓，在这浩瀚宇宙中，唯有我星球上的一朵花独树一帜，而一只小绵羊却能在不经意间，一个清晨将其毁灭，这难道不是件重要的事吗？", "t": [25388, 38912]}]}, {"id": "ch07p28", "audio": true, "sents": [{"fr": "Il rougit, puis reprit :", "zh": "他涨红了脸，然后继续说道：", "t": [100, 2262]}]}, {"id": "ch07p29", "audio": true, "sents": [{"fr": "— Si quelqu’un aime une fleur qui n’existe qu’à un exemplaire dans les millions et les millions d’étoiles, ça suffit pour qu’il soit heureux quand il les regarde.", "zh": "若有人爱上了一朵世上仅此一朵的花，那么在仰望星空时，便能因这份独一无二而感到幸福。", "t": [100, 9375]}, {"fr": "Il se dit : \"Ma fleur est là quelque part…\" Mais si le mouton mange la fleur, c’est pour lui comme si, brusquement, toutes les étoiles s’éteignaient !", "zh": "他心想：“我的花儿在某个地方……”然而，如果绵羊吃掉了那朵花，对它来说，就好像突然间所有的星星都熄灭了！", "t": [9375, 19975]}, {"fr": "Et ce n’est pas important ça !", "zh": "这并不重要。", "t": [19975, 21937]}]}, {"id": "ch07p30", "audio": true, "sents": [{"fr": "Il ne put rien dire de plus.", "zh": "他无言以对。", "t": [100, 2275]}, {"fr": "Il éclata brusquement en sanglots.", "zh": "突然间，他放声大哭。", "t": [2275, 4962]}, {"fr": "La nuit était tombée.", "zh": "夜幕降临。", "t": [4962, 6950]}, {"fr": "J’avais lâché mes outils.", "zh": "我扔下了我的工具。", "t": [6950, 9188]}, {"fr": "Je me moquais bien de mon marteau, de mon boulon, de la soif et de la mort.", "zh": "我根本不在乎我的锤子、螺栓、干渴和死亡。", "t": [9188, 14162]}, {"fr": "Il y avait, sur une étoile, une planète, la mienne, la Terre, un petit prince à consoler !", "zh": "在那颗星星上，我的星球，地球上，有一个小王子需要安慰！", "t": [14162, 21125]}, {"fr": "Je le pris dans les bras.", "zh": "我把他抱在怀里。", "t": [21125, 23112]}, {"fr": "Je le berçai.", "zh": "轻柔地摇着他。", "t": [23112, 24900]}, {"fr": "Je lui disais : \"La fleur que tu aimes n’est pas en danger…", "zh": "我告诉他：“你爱的那朵花不会有危险的……”", "t": [24900, 29288]}, {"fr": "Je lui dessinerai une muselière, à ton mouton…", "zh": "我给你的绵羊画一个口罩…", "t": [29288, 32888]}, {"fr": "Je te dessinerai une armure pour ta fleur…", "zh": "我给你的花儿画一副铠甲…", "t": [32888, 36075]}, {"fr": "Je…\" Je ne savais pas trop quoi dire.", "zh": "我……不知该说些什么。", "t": [36075, 39838]}, {"fr": "Je me sentais très maladroit.", "zh": "我感到十分笨拙。", "t": [39838, 42275]}, {"fr": "Je ne savais comment l’atteindre, où le rejoindre…", "zh": "我不知如何抵达，如何与他重逢…", "t": [42275, 45675]}, {"fr": "C’est tellement mystérieux, le pays des larmes.", "zh": "泪水的王国如此神秘。", "t": [45675, 48212]}]}]}, {"id": "ch08", "title_fr": "Chapitre VIII", "title_zh": "第 8 章", "paras": [{"id": "ch08p00", "audio": true, "sents": [{"fr": "J’appris bien vite à mieux connaître cette fleur.", "zh": "我很快便更深入地了解了这朵花。", "t": [100, 3400]}, {"fr": "Il y avait toujours eu, sur la planète du petit prince, des fleurs très simples, ornées d’un seul rang de pétales, et qui ne tenaient point de place, et qui ne dérangeaient personne.", "zh": "那颗星球上，原本只有极简单的花朵，花瓣单层，不占地盘，也不扰人。", "t": [3400, 13575]}, {"fr": "Elles apparaissaient un matin dans l’herbe, et puis elles s’éteignaient le soir.", "zh": "它们在清晨绽放于草间，傍晚便凋谢。", "t": [13575, 17988]}, {"fr": "Mais celle-là avait germé un jour, d’une graine apportée d’on ne sait où, et le petit prince avait surveillé de très près cette brindille qui ne ressemblait pas aux autres brindilles.", "zh": "然而，那朵花却是在某一天，由一颗不知从何而来的种子萌发，小王子便密切地观察着这根与众不同的嫩枝。", "t": [17988, 27038]}, {"fr": "Ça pouvait être un nouveau genre de baobab.", "zh": "这可能是新种类的猴面包树。", "t": [27038, 30038]}, {"fr": "Mais l’arbuste cessa vite de croître, et commença de préparer une fleur.", "zh": "灌木很快停止了生长，开始孕育一朵花。", "t": [30038, 34938]}, {"fr": "Le petit prince, qui assistait à l’installation d’un bouton énorme, sentait bien qu’il en sortirait une apparition miraculeuse, mais la fleur n’en finissait pas de se préparer à être belle, à l’abri de sa chambre verte.", "zh": "小王子目睹那硕大的花蕾悄然绽放，深知它将化作一个奇迹般的倩影，然而花儿却在绿意盎然的屋内，不厌其烦地准备着如何让自己更加美丽。", "t": [34938, 47300]}, {"fr": "Elle choisissait avec soin ses couleurs.", "zh": "她精心挑选着色彩。", "t": [47300, 50262]}, {"fr": "Elle s’habillait lentement, elle ajustait un à un ses pétales.", "zh": "她缓缓穿衣，一片片地调整她的花瓣。", "t": [50262, 54188]}, {"fr": "Elle ne voulait pas sortir toute fripée comme les coquelicots.", "zh": "她不愿像罂粟花那样，皱巴巴地就露面。", "t": [54188, 57838]}, {"fr": "Elle ne voulait apparaître que dans le plein rayonnement de sa beauté.", "zh": "她只愿在美的极致中绽放。", "t": [57838, 61762]}, {"fr": "Eh !", "zh": "唉！", "t": [61762, 63650]}, {"fr": "oui.", "zh": "是的。", "t": [63650, 64912]}, {"fr": "Elle était très coquette !", "zh": "她极爱俏皮。", "t": [64912, 67488]}, {"fr": "Sa toilette mystérieuse avait donc duré des jours et des jours.", "zh": "她的神秘装扮持续了数日之久。", "t": [67488, 71625]}, {"fr": "Et puis voici qu’un matin, justement à l’heure du lever du soleil, elle s’était montrée.", "zh": "就在一个清晨，恰逢日出时分，她露面了。", "t": [71625, 76237]}]}, {"id": "ch08p01", "audio": true, "sents": [{"fr": "Et elle, qui avait travaillé avec tant de précision, dit en bâillant :", "zh": "她，经过如此精细的打扮，打着哈欠说：", "t": [100, 4413]}]}, {"id": "ch08p02", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "Je me réveille à peine…", "zh": "我刚醒过来…", "t": [3038, 5200]}, {"fr": "Je vous demande pardon…", "zh": "请您原谅……", "t": [5200, 7300]}, {"fr": "Je suis encore toute décoiffée…", "zh": "我仍是一头乱发。", "t": [7300, 8950]}]}, {"id": "ch08p03", "audio": true, "sents": [{"fr": "Le petit prince, alors, ne put contenir son admiration :", "zh": "小王子不禁赞叹不已：", "t": [100, 4488]}]}, {"id": "ch08p04", "audio": true, "sents": [{"fr": "— Que vous êtes belle !", "zh": "您真美啊！", "t": [100, 2638]}]}, {"id": "ch08p05", "audio": true, "sents": [{"fr": "— N’est-ce pas, répondit doucement la fleur.", "zh": "是啊，花儿轻声回应。", "t": [100, 4350]}, {"fr": "Et je suis née en même temps que le soleil…", "zh": "我与太阳同日而生……", "t": [4350, 6225]}]}, {"id": "ch08p06", "audio": true, "sents": [{"fr": "Le petit prince devina bien qu’elle n’était pas trop modeste, mais elle était si émouvante !", "zh": "小王子深知她并不谦逊，但她却如此动人。", "t": [100, 4937]}]}, {"id": "ch08p07", "audio": true, "sents": [{"fr": "— C’est l’heure, je crois, du petit déjeuner, avait-elle bientôt ajouté, auriez-vous la bonté de penser à moi…", "zh": "她很快又补充道：“我想现在是吃早餐的时候了，您能为我着想一下吗？”", "t": [100, 7313]}]}, {"id": "ch08p08", "audio": true, "sents": [{"fr": "Et le petit prince, tout confus, ayant été chercher un arrosoir d’eau fraîche, avait servi la fleur.", "zh": "小王子慌乱地找来一壶凉水，为花儿浇水。", "t": [100, 5774]}]}, {"id": "ch08p09", "audio": true, "sents": [{"fr": "Ainsi l’avait-elle bien vite tourmenté par sa vanité un peu ombrageuse.", "zh": "她很快便被那略显傲慢的虚荣所折磨。", "t": [100, 4450]}, {"fr": "Un jour, par exemple, parlant de ses quatre épines, elle avait dit au petit prince :", "zh": "有一天，比如，她向小王子提起她的四根刺。", "t": [4450, 9674]}]}, {"id": "ch08p10", "audio": true, "sents": [{"fr": "— Ils peuvent venir, les tigres, avec leurs griffes !", "zh": "老虎们，带着它们的爪子，可以来！", "t": [100, 4500]}]}, {"id": "ch08p11", "audio": true, "sents": [{"fr": "— Il n’y a pas de tigres sur ma planète, avait objecté le petit prince, et puis les tigres ne mangent pas l’herbe.", "zh": "小王子反驳道：“我的星球上没有老虎，再说，老虎不吃草。”", "t": [100, 6713]}]}, {"id": "ch08p12", "audio": true, "sents": [{"fr": "— Je ne suis pas une herbe, avait doucement répondu la fleur.", "zh": "我不是一株草，花儿柔声回答。", "t": [100, 4237]}]}, {"id": "ch08p13", "audio": true, "sents": [{"fr": "— Pardonnez-moi…", "zh": "请原谅……", "t": [100, 1963]}]}, {"id": "ch08p14", "audio": true, "sents": [{"fr": "— Je ne crains rien des tigres, mais j’ai horreur des courants d’air.", "zh": "我不怕老虎，却讨厌风。", "t": [100, 5250]}, {"fr": "Vous n’auriez pas un paravent ?", "zh": "您有屏风吗？", "t": [5250, 7338]}]}, {"id": "ch08p15", "audio": true, "sents": [{"fr": "\"Horreur des courants d’air…", "zh": "风，真讨厌……", "t": [100, 1525]}, {"fr": "ce n’est pas de chance, pour une plante, avait remarqué le petit prince.", "zh": "这并非植物之幸，小王子曾注意到。", "t": [1525, 6362]}, {"fr": "Cette fleur est bien compliquée…\"", "zh": "这朵花真复杂……", "t": [6362, 7975]}]}, {"id": "ch08p16", "audio": true, "sents": [{"fr": "— Le soir vous me mettrez sous globe.", "zh": "晚上您得给我罩上玻璃罩。", "t": [100, 3738]}, {"fr": "Il fait très froid chez vous.", "zh": "您这儿很冷。", "t": [3738, 5788]}, {"fr": "C’est mal installé.", "zh": "安置得不好。", "t": [5788, 7712]}, {"fr": "Là d’où je viens…", "zh": "我从哪里来…", "t": [7712, 8650]}]}, {"id": "ch08p17", "audio": true, "sents": [{"fr": "Mais elle s’était interrompue.", "zh": "她话音未落。", "t": [100, 2325]}, {"fr": "Elle était venue sous forme de graine.", "zh": "她以种子的形式到来。", "t": [2325, 4975]}, {"fr": "Elle n’avait rien pu connaître des autres mondes.", "zh": "她对其他世界一无所知。", "t": [4975, 8075]}, {"fr": "Humiliée de s’être laissé surprendre à préparer un mensonge aussi naïf, elle avait toussé deux ou trois fois, pour mettre le petit prince dans son tort :", "zh": "羞愧于让自己被揭露在准备这样一个幼稚的谎言，她咳嗽了两三声，想要让小王子承担过错：", "t": [8075, 15888]}]}, {"id": "ch08p18", "audio": true, "sents": [{"fr": "— Ce paravent ?…", "zh": "这屏风？", "t": [100, 2563]}]}, {"id": "ch08p19", "audio": true, "sents": [{"fr": "— J’allais le chercher mais vous me parliez !", "zh": "我正要去寻找它，却和你说话了！", "t": [100, 3663]}]}, {"id": "ch08p20", "audio": true, "sents": [{"fr": "Alors elle avait forcé sa toux pour lui infliger quand même des remords.", "zh": "她故意咳嗽，让他感到愧疚。", "t": [100, 3337]}]}, {"id": "ch08p21", "audio": true, "sents": [{"fr": "Ainsi le petit prince, malgré la bonne volonté de son amour, avait vite douté d’elle.", "zh": "小王子，尽管他的爱情充满善意，却很快对她产生了怀疑。", "t": [100, 5888]}, {"fr": "Il avait pris au sérieux des mots sans importance, et était devenu très malheureux.", "zh": "他认真对待了无关紧要的话，因而变得非常痛苦。", "t": [5888, 9962]}]}, {"id": "ch08p22", "audio": true, "sents": [{"fr": "\"J’aurais dû ne pas l’écouter, me confia-t-il un jour, il ne faut jamais écouter les fleurs.", "zh": "他有一天对我说：“我本不该听信她的话，永远也别信花儿讲的话。”", "t": [100, 5812]}, {"fr": "Il faut les regarder et les respirer.", "zh": "须得细赏其姿，深吸其香。", "t": [5812, 8562]}, {"fr": "La mienne embaumait ma planète, mais je ne savais pas m’en réjouir.", "zh": "我的玫瑰为我的星球增添了芬芳，我却未曾为此感到喜悦。", "t": [8562, 12888]}, {"fr": "Cette histoire de griffes, qui m’avait tellement agacé, eût dû m’attendrir…\"", "zh": "这关于爪子的故事，本该让我心生怜悯……", "t": [12888, 16912]}]}, {"id": "ch08p23", "audio": true, "sents": [{"fr": "Il me confia encore :", "zh": "他继续向我吐露：", "t": [100, 1962]}]}, {"id": "ch08p24", "audio": true, "sents": [{"fr": "\"Je n’ai alors rien su comprendre !", "zh": "我那时全然不懂！", "t": [100, 3288]}, {"fr": "J’aurais dû la juger sur les actes et non sur les mots.", "zh": "我应该根据她的行为而非言语来评判她。", "t": [3288, 6612]}, {"fr": "Elle m’embaumait et m’éclairait.", "zh": "她为我增添了芬芳，照亮了我的心。", "t": [6612, 8862]}, {"fr": "Je n’aurais jamais dû m’enfuir !", "zh": "我本不该逃避！", "t": [8862, 11825]}, {"fr": "J’aurais dû deviner sa tendresse derrière ses pauvres ruses.", "zh": "我本应猜透她那可怜的诡计背后的柔情。", "t": [11825, 15562]}, {"fr": "Les fleurs sont si contradictoires !", "zh": "花儿是如此矛盾！", "t": [15562, 18775]}, {"fr": "Mais j’étais trop jeune pour savoir l’aimer.\"", "zh": "但我那时太年轻，不懂如何去爱。", "t": [18775, 20712]}]}, {"id": "ch08p25", "audio": true, "sents": []}, {"id": "ch08p26", "audio": true, "sents": []}]}, {"id": "ch09", "title_fr": "Chapitre IX", "title_zh": "第 9 章", "paras": [{"id": "ch09p00", "audio": true, "sents": [{"fr": "Je crois qu’il profita, pour son évasion, d’une migration d’oiseaux sauvages.", "zh": "他大概是趁着野鸟迁徙之际逃离的。", "t": [100, 5275]}, {"fr": "Au matin du départ il mit sa planète bien en ordre.", "zh": "清晨，他将自己的星球整理得井井有条。", "t": [5275, 8788]}, {"fr": "Il ramona soigneusement ses volcans en activité.", "zh": "他精心照料着那些活火山。", "t": [8788, 12388]}, {"fr": "Il possédait deux volcans en activité.", "zh": "他拥有两座活火山。", "t": [12388, 15375]}, {"fr": "Et c’était bien commode pour faire chauffer le petit déjeuner du matin.", "zh": "早餐热饭颇为方便。", "t": [15375, 19450]}, {"fr": "Il possédait aussi un volcan éteint.", "zh": "他还拥有一座熄灭的火山。", "t": [19450, 22275]}, {"fr": "Mais, comme il disait, \"On ne sait jamais !\" Il ramona donc également le volcan éteint.", "zh": "然而，正如他所说：“世事难料！”因此，他也清理了那座熄灭的火山。", "t": [22275, 29275]}, {"fr": "S’ils sont bien ramonés, les volcans brûlent doucement et régulièrement, sans éruptions.", "zh": "火山若经清扫，火焰便缓缓而规律地燃烧，不致喷发。", "t": [29275, 34738]}, {"fr": "Les éruptions volcaniques sont comme des feux de cheminée.", "zh": "火山爆发犹如炉火燃烧。", "t": [34738, 38525]}, {"fr": "Évidemment sur notre terre nous sommes beaucoup trop petits pour ramoner nos volcans.", "zh": "显然，在我们地球上，我们实在太小了，无法清理我们的火山。", "t": [38525, 43138]}, {"fr": "C’est pourquoi ils nous causent des tas d’ennuis.", "zh": "因此，它们给我们带来诸多烦恼。", "t": [43138, 45250]}]}, {"id": "ch09p01", "audio": true, "sents": [{"fr": "Le petit prince arracha aussi, avec un peu de mélancolie, les dernières pousses de baobabs.", "zh": "小王子带着一丝忧郁，拔除了最后几株猴面包树苗。", "t": [100, 6162]}, {"fr": "Il croyait ne jamais devoir revenir.", "zh": "他以为永远不会再回来。", "t": [6162, 9050]}, {"fr": "Mais tous ces travaux familiers lui parurent, ce matin-là, extrêmement doux.", "zh": "但那天早晨，这些熟悉的工作在他看来分外温馨。", "t": [9050, 13875]}, {"fr": "Et, quand il arrosa une dernière fois la fleur, et se prépara à la mettre à l’abri sous son globe, il se découvrit l’envie de pleurer.", "zh": "最后一次给花儿浇水，准备给她盖上罩子，他突然想哭。", "t": [13875, 20913]}]}, {"id": "ch09p02", "audio": true, "sents": [{"fr": "— Adieu, dit-il à la fleur.", "zh": "再见了，他对花儿说。", "t": [100, 2875]}]}, {"id": "ch09p03", "audio": true, "sents": [{"fr": "Mais elle ne lui répondit pas.", "zh": "她没有回答他。", "t": [100, 1450]}]}, {"id": "ch09p04", "audio": true, "sents": [{"fr": "— Adieu, répéta-t-il.", "zh": "再见了，他又说。", "t": [100, 2762]}]}, {"id": "ch09p05", "audio": true, "sents": [{"fr": "La fleur toussa.", "zh": "花儿咳嗽。", "t": [100, 1950]}, {"fr": "Mais ce n’était pas à cause de son rhume.", "zh": "但这并非因她感冒。", "t": [1950, 3724]}]}, {"id": "ch09p06", "audio": true, "sents": [{"fr": "— J’ai été sotte, lui dit-elle enfin.", "zh": "她终于说：“我以前真傻。”", "t": [100, 4000]}, {"fr": "Je te demande pardon.", "zh": "请你原谅。", "t": [4000, 6138]}, {"fr": "Tâche d’être heureux.", "zh": "努力让自己快乐吧。", "t": [6138, 7124]}]}, {"id": "ch09p07", "audio": true, "sents": [{"fr": "Il fut surpris par l’absence de reproches.", "zh": "她没有责备他的意思。", "t": [100, 3162]}, {"fr": "Il restait là tout déconcerté, le globe en l’air.", "zh": "他愣在那里，球儿高高举起。", "t": [3162, 6775]}, {"fr": "Il ne comprenait pas cette douceur calme.", "zh": "他不懂这温柔而平静的柔情。", "t": [6775, 8712]}]}, {"id": "ch09p08", "audio": true, "sents": [{"fr": "— Mais oui, je t’aime, lui dit la fleur.", "zh": "但的确，我爱你，花儿对他说。", "t": [100, 4388]}, {"fr": "Tu n’en as rien su, par ma faute.", "zh": "你未曾察觉，皆因我的过错。", "t": [4388, 7338]}, {"fr": "Cela n’a aucune importance.", "zh": "这并无大碍。", "t": [7338, 9825]}, {"fr": "Mais tu as été aussi sot que moi.", "zh": "你也和我一样傻。", "t": [9825, 12438]}, {"fr": "Tâche d’être heureux…", "zh": "愿你幸福……", "t": [12438, 14262]}, {"fr": "Laisse ce globe tranquille.", "zh": "让这颗星球保持宁静。", "t": [14262, 16638]}, {"fr": "Je n’en veux plus.", "zh": "我已厌倦了。", "t": [16638, 17562]}]}, {"id": "ch09p09", "audio": true, "sents": [{"fr": "— Mais le vent…", "zh": "但风……", "t": [100, 1713]}]}, {"id": "ch09p10", "audio": true, "sents": [{"fr": "— Je ne suis pas si enrhumée que ça…", "zh": "我并未如此感冒。", "t": [100, 3575]}, {"fr": "L’air frais de la nuit me fera du bien.", "zh": "夜间的清风吹拂对我大有裨益。", "t": [3575, 6300]}, {"fr": "Je suis une fleur.", "zh": "我是一朵花。", "t": [6300, 7413]}]}, {"id": "ch09p11", "audio": true, "sents": [{"fr": "— Mais les bêtes…", "zh": "然而，那些野兽……", "t": [100, 1912]}]}, {"id": "ch09p12", "audio": true, "sents": [{"fr": "— Il faut bien que je supporte deux ou trois chenilles si je veux connaître les papillons.", "zh": "若想识得蝴蝶，自须忍受两三只毛虫。", "t": [100, 5925]}, {"fr": "Il paraît que c’est tellement beau.", "zh": "如此美景，令人陶醉。", "t": [5925, 8188]}, {"fr": "Sinon qui me rendra visite ?", "zh": "那谁会来看我呢？", "t": [8188, 11175]}, {"fr": "Tu seras loin, toi.", "zh": "你将远行。", "t": [11175, 13500]}, {"fr": "Quant aux grosses bêtes, je ne crains rien.", "zh": "至于那些大野兽，我无所畏惧。", "t": [13500, 16400]}, {"fr": "J’ai mes griffes.", "zh": "我有我的刺。", "t": [16400, 17288]}]}, {"id": "ch09p13", "audio": true, "sents": [{"fr": "Et elle montrait naïvement ses quatre épines.", "zh": "她天真地露出了她的四根刺。", "t": [100, 2988]}, {"fr": "Puis elle ajouta :", "zh": "然后，她补充道：", "t": [2988, 4700]}]}, {"id": "ch09p14", "audio": true, "sents": [{"fr": "— Ne traîne pas comme ça, c’est agaçant.", "zh": "别这样拖拖拉拉，真让人心烦。", "t": [100, 4050]}, {"fr": "Tu as décidé de partir.", "zh": "你已决定离去。", "t": [4050, 6412]}, {"fr": "Va-t’en.", "zh": "去吧。", "t": [6412, 6924]}]}, {"id": "ch09p15", "audio": true, "sents": [{"fr": "Car elle ne voulait pas qu’il la vît pleurer.", "zh": "她不愿让他看见自己哭泣。", "t": [100, 2812]}, {"fr": "C’était une fleur tellement orgueilleuse…", "zh": "她是一朵多么骄傲的花儿。", "t": [2812, 4637]}]}, {"id": "ch09p16", "audio": true, "sents": []}, {"id": "ch09p17", "audio": true, "sents": []}, {"id": "ch09p18", "audio": true, "sents": []}, {"id": "ch09p19", "audio": true, "sents": []}, {"id": "ch09p20", "audio": true, "sents": []}, {"id": "ch09p21", "audio": true, "sents": []}, {"id": "ch09p22", "audio": true, "sents": []}, {"id": "ch09p23", "audio": true, "sents": []}, {"id": "ch09p24", "audio": true, "sents": []}]}, {"id": "ch10", "title_fr": "Chapitre X", "title_zh": "第 10 章", "paras": [{"id": "ch10p00", "audio": true, "sents": [{"fr": "Il se trouvait dans la région des astéroïdes 325, 326, 327, 328, 329 et 330.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [100, 9888]}, {"fr": "Il commença donc par les visiter pour y chercher une occupation et pour s’instruire.", "zh": "于是他决定先去拜访它们，以便找些事做，增长见识。", "t": [9888, 14150]}]}, {"id": "ch10p01", "audio": true, "sents": [{"fr": "La première était habitée par un roi.", "zh": "那颗星球上住着一位国王。", "t": [100, 2912]}, {"fr": "Le roi siégeait, habillé de pourpre et d’hermine, sur un trône très simple et cependant majestueux.", "zh": "国王身着紫红与貂皮，端坐于简朴却威严的宝座之上。", "t": [2912, 8050]}]}, {"id": "ch10p02", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "Voilà un sujet, s’écria le roi quand il aperçut le petit prince.", "zh": "啊，来了一位臣民！", "t": [3038, 6900]}]}, {"id": "ch10p03", "audio": true, "sents": [{"fr": "Et le petit prince se demanda :", "zh": "小王子心想：", "t": [100, 2500]}]}, {"id": "ch10p04", "audio": true, "sents": [{"fr": "— Comment peut-il me reconnaître puisqu’il ne m’a encore jamais vu !", "zh": "他怎能认出我呢，他从未见过我！", "t": [100, 4838]}]}, {"id": "ch10p05", "audio": true, "sents": [{"fr": "Il ne savait pas que, pour les rois, le monde est très simplifié.", "zh": "国王们以为世界很简单。", "t": [100, 4325]}, {"fr": "Tous les hommes sont des sujets.", "zh": "所有的人都是臣民。", "t": [4325, 5675]}]}, {"id": "ch10p06", "audio": true, "sents": [{"fr": "— Approche-toi que je te voie mieux, lui dit le roi qui était tout fier d’être roi pour quelqu’un.", "zh": "国王得意洋洋地说：“走近点，让我更好地看看你。”", "t": [100, 5612]}]}, {"id": "ch10p07", "audio": true, "sents": [{"fr": "Le petit prince chercha des yeux où s’asseoir, mais la planète était toute encombrée par le magnifique manteau d’hermine.", "zh": "小王子四处寻找可坐之地，但整个星球都被那件华丽的貂皮大衣占据了。", "t": [100, 6812]}, {"fr": "Il resta donc debout, et, comme il était fatigué, il bâilla.", "zh": "于是他站着，疲惫不堪，打了个哈欠。", "t": [6812, 10574]}]}, {"id": "ch10p08", "audio": true, "sents": [{"fr": "— Il est contraire à l’étiquette de bâiller en présence d’un roi, lui dit le monarque.", "zh": "在国王面前打哈欠，有失礼节。", "t": [100, 6250]}, {"fr": "Je te l’interdis.", "zh": "我禁止你这样做。", "t": [6250, 7350]}]}, {"id": "ch10p09", "audio": true, "sents": [{"fr": "— Je ne peux pas m’en empêcher, répondit le petit prince tout confus.", "zh": "小王子慌乱地回答：“我忍不住啊。”", "t": [100, 5538]}, {"fr": "J’ai fait un long voyage et je n’ai pas dormi…", "zh": "长途跋涉，我未曾入眠……", "t": [5538, 7575]}]}, {"id": "ch10p10", "audio": true, "sents": [{"fr": "— Alors, lui dit le roi, je t’ordonne de bâiller.", "zh": "陛下，我命令你打哈欠。", "t": [100, 4888]}, {"fr": "Je n’ai vu personne bâiller depuis des années.", "zh": "多年来，我未见有人打喷嚏。", "t": [4888, 7950]}, {"fr": "Les bâillements sont pour moi des curiosités.", "zh": "打哈欠对我来说是一种奇观。", "t": [7950, 11050]}, {"fr": "Allons !", "zh": "咱们走吧！", "t": [11050, 13125]}, {"fr": "bâille encore.", "zh": "再打一个哈欠。", "t": [13125, 14850]}, {"fr": "C’est un ordre.", "zh": "这是命令。", "t": [14850, 15737]}]}, {"id": "ch10p11", "audio": true, "sents": [{"fr": "— Ça m’intimide…", "zh": "这让我感到害怕…", "t": [100, 2300]}, {"fr": "je ne peux plus…", "zh": "我再也…", "t": [2300, 3162]}, {"fr": "fit le petit prince tout rougissant.", "zh": "小王子涨红了脸。", "t": [3162, 4713]}]}, {"id": "ch10p12", "audio": true, "sents": [{"fr": "— Hum !", "zh": "哼！", "t": [100, 2962]}, {"fr": "Hum !", "zh": "哼！", "t": [2962, 4350]}, {"fr": "répondit le roi.", "zh": "国王答道。", "t": [4350, 6125]}, {"fr": "Alors je…", "zh": "那么我就…", "t": [6125, 6950]}, {"fr": "je t’ordonne tantôt de bâiller et tantôt de…", "zh": "我命令你时而打哈欠，时而停止。", "t": [6950, 9087]}]}, {"id": "ch10p13", "audio": true, "sents": [{"fr": "Il bredouillait un peu et paraissait vexé.", "zh": "他略显尴尬，面露不悦。", "t": [100, 2225]}]}, {"id": "ch10p14", "audio": true, "sents": [{"fr": "Car le roi tenait essentiellement à ce que son autorité fût respectée.", "zh": "国王主要关心的是他的权威得到尊重。", "t": [100, 4500]}, {"fr": "Il ne tolérait pas la désobéissance.", "zh": "他不允许违抗。", "t": [4500, 7300]}, {"fr": "C’était un monarque absolu.", "zh": "这是一位绝对君主。", "t": [7300, 9638]}, {"fr": "Mais, comme il était très bon, il donnait des ordres raisonnables.", "zh": "然而，由于他非常善良，他总是发布合理的命令。", "t": [9638, 13012]}]}, {"id": "ch10p15", "audio": true, "sents": [{"fr": "\"Si j’ordonnais, disait-il couramment, si j’ordonnais à un général de se changer en oiseau de mer, et si le général n’obéissait pas, ce ne serait pas la faute du général.", "zh": "若我下令，他直言不讳，若我命令一位将军变成海鸟，而将军不服从，那错不在将军。", "t": [100, 10600]}, {"fr": "Ce serait ma faute.\"", "zh": "这错在我。", "t": [10600, 11738]}]}, {"id": "ch10p16", "audio": true, "sents": [{"fr": "— Puis-je m’asseoir ?", "zh": "我可以坐下吗？", "t": [100, 3450]}, {"fr": "s’enquit timidement le petit prince.", "zh": "小王子胆怯地问道。", "t": [3450, 5325]}]}, {"id": "ch10p17", "audio": true, "sents": [{"fr": "— Je t’ordonne de t’asseoir, lui répondit le roi, qui ramena majestueusement un pan de son manteau d’hermine.", "zh": "国王威严地挥动了一下貂皮大衣，说道：“我命令你坐下。”", "t": [100, 6837]}]}, {"id": "ch10p18", "audio": true, "sents": [{"fr": "Mais le petit prince s’étonnait.", "zh": "小王子感到惊讶。", "t": [100, 2500]}, {"fr": "La planète était minuscule.", "zh": "这颗星球小得可怜。", "t": [2500, 5000]}, {"fr": "Sur quoi le roi pouvait-il bien régner ?", "zh": "国王又能统治什么？", "t": [5000, 7650]}]}, {"id": "ch10p19", "audio": true, "sents": [{"fr": "— Sire, lui dit-il…", "zh": "陛下，他对国王说…", "t": [100, 2662]}, {"fr": "je vous demande pardon de vous interroger…", "zh": "请原谅我向您提问……", "t": [2662, 4587]}]}, {"id": "ch10p20", "audio": true, "sents": [{"fr": "— Je t’ordonne de m’interroger, se hâta de dire le roi.", "zh": "陛下，我命令你提问。", "t": [100, 4076]}]}, {"id": "ch10p21", "audio": true, "sents": [{"fr": "— Sire…", "zh": "陛下…", "t": [100, 1712]}, {"fr": "sur quoi régnez-vous ?", "zh": "您统治何方？", "t": [1712, 3374]}]}, {"id": "ch10p22", "audio": true, "sents": [{"fr": "— Sur tout, répondit le roi, avec une grande simplicité.", "zh": "统治一切，国王以极大的简单性回答。", "t": [100, 4587]}]}, {"id": "ch10p23", "audio": true, "sents": [{"fr": "— Sur tout ?", "zh": "统治一切？", "t": [100, 2350]}]}, {"id": "ch10p24", "audio": true, "sents": [{"fr": "Le roi d’un geste discret désigna sa planète, les autres planètes et les étoiles.", "zh": "国王轻轻一挥手，指点了他的星球、其他星球和星星。", "t": [100, 4750]}]}, {"id": "ch10p25", "audio": true, "sents": [{"fr": "— Sur tout ça ?", "zh": "统治这一切？", "t": [100, 2838]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [2838, 3826]}]}, {"id": "ch10p26", "audio": true, "sents": [{"fr": "— Sur tout ça…", "zh": "统治这一切……", "t": [100, 2112]}, {"fr": "répondit le roi.", "zh": "国王答道。", "t": [2112, 3013]}]}, {"id": "ch10p27", "audio": true, "sents": [{"fr": "Car non seulement c’était un monarque absolu mais c’était un monarque universel.", "zh": "不仅他是绝对的君主，而且是宇宙的君主。", "t": [100, 3950]}]}, {"id": "ch10p28", "audio": true, "sents": [{"fr": "— Et les étoiles vous obéissent ?", "zh": "星星都听命于您吗？", "t": [100, 3176]}]}, {"id": "ch10p29", "audio": true, "sents": [{"fr": "— Bien sûr, lui dit le roi.", "zh": "当然，国王说。", "t": [100, 3725]}, {"fr": "Elles obéissent aussitôt.", "zh": "它们立刻服从。", "t": [3725, 5838]}, {"fr": "Je ne tolère pas l’indiscipline.", "zh": "不容忍无纪律行为。", "t": [5838, 7513]}]}, {"id": "ch10p30", "audio": true, "sents": [{"fr": "Un tel pouvoir émerveilla le petit prince.", "zh": "如此权力令小王子惊叹。", "t": [100, 3175]}, {"fr": "S’il l’avait détenu lui-même, il aurait pu assister, non pas à quarante-quatre, mais à soixante-douze, ou même à cent, ou même à deux cents couchers de soleil dans la même journée, sans avoir jamais à tirer sa chaise !", "zh": "若是他亲自掌管，他便能观赏到，而非四十四次，而是七十二次，甚至一百次，或两百次日落，而无需挪动椅子！", "t": [3175, 15388]}, {"fr": "Et comme il se sentait un peu triste à cause du souvenir de sa petite planète abandonnée, il s’enhardit à solliciter une grâce du roi :", "zh": "因忆起那颗被遗弃的小行星而略感忧伤，他鼓起勇气，向国王恳求恩典：", "t": [15388, 22575]}]}, {"id": "ch10p31", "audio": true, "sents": [{"fr": "— Je voudrais voir un coucher de soleil…", "zh": "我想看看日落……", "t": [100, 3838]}, {"fr": "Faites-moi plaisir…", "zh": "请随意…", "t": [3838, 5825]}, {"fr": "Ordonnez au soleil de se coucher…", "zh": "命令太阳落山吧…", "t": [5825, 7600]}]}, {"id": "ch10p32", "audio": true, "sents": [{"fr": "— Si j’ordonnais à un général de voler d’une fleur à l’autre à la façon d’un papillon, ou d’écrire une tragédie, ou de se changer en oiseau de mer, et si le général n’exécutait pas l’ordre reçu, qui, de lui ou de moi, serait dans son tort ?", "zh": "若我命令一位将军像蝴蝶那样在花间飞舞，或撰写一部悲剧，或变成海鸟，而将军不遵从命令，那么，错的是他，还是我？", "t": [100, 14350]}]}, {"id": "ch10p33", "audio": true, "sents": [{"fr": "— Ce serait vous, dit fermement le petit prince.", "zh": "这一定是您，小王子坚定地说。", "t": [100, 3650]}]}, {"id": "ch10p34", "audio": true, "sents": [{"fr": "— Exact.", "zh": "精确无误。", "t": [100, 2738]}, {"fr": "Il faut exiger de chacun ce que chacun peut donner, reprit le roi.", "zh": "国王接着说：“必须要求每个人贡献出他所能给予的。”", "t": [2738, 7212]}, {"fr": "L’autorité repose d’abord sur la raison.", "zh": "权威首先建立在理性之上。", "t": [7212, 10338]}, {"fr": "Si tu ordonnes à ton peuple d’aller se jeter à la mer, il fera la révolution.", "zh": "若你命令你的子民跳海，他们便会起义。", "t": [10338, 15362]}, {"fr": "J’ai le droit d’exiger l’obéissance parce que mes ordres sont raisonnables.", "zh": "我有权要求服从，因为我的命令合乎情理。", "t": [15362, 18988]}]}, {"id": "ch10p35", "audio": true, "sents": [{"fr": "— Alors mon coucher de soleil ?", "zh": "那么，我的日落时分？", "t": [100, 4188]}, {"fr": "rappela le petit prince qui jamais n’oubliait une question une fois qu’il l’avait posée.", "zh": "小王子牢记提问，从不遗忘。", "t": [4188, 8012]}]}, {"id": "ch10p36", "audio": true, "sents": [{"fr": "— Ton coucher de soleil, tu l’auras.", "zh": "你的日落，你自会看到。", "t": [100, 4025]}, {"fr": "Je l’exigerai.", "zh": "我命令它。", "t": [4025, 5888]}, {"fr": "Mais j’attendrai, dans ma science du gouvernement, que les conditions soient favorables.", "zh": "但在我治理国家的智慧中，我会等待时机成熟。", "t": [5888, 10413]}]}, {"id": "ch10p37", "audio": true, "sents": [{"fr": "— Quand ça sera-t-il ?", "zh": "那会是什么时候呢？", "t": [100, 3638]}, {"fr": "s’informa le petit prince.", "zh": "小王子，你听说了吗？", "t": [3638, 5163]}]}, {"id": "ch10p38", "audio": true, "sents": [{"fr": "— Hem !", "zh": "啊！", "t": [100, 2975]}, {"fr": "Hem !", "zh": "啊！", "t": [2975, 4875]}, {"fr": "lui répondit le roi, qui consulta d’abord un gros calendrier, hem !", "zh": "国王回答道，他首先查阅了一本大日历，嗯！", "t": [4875, 10262]}, {"fr": "hem !", "zh": "哼！", "t": [10262, 12162]}, {"fr": "ce sera, vers…", "zh": "那将是，向着…", "t": [12162, 13588]}, {"fr": "vers…", "zh": "他曾在沙漠中寻找水源。", "t": [13588, 14138]}, {"fr": "ce sera ce soir vers sept heures quarante !", "zh": "今晚十时四十分左右。", "t": [14138, 17488]}, {"fr": "Et tu verras comme je suis bien obéi.", "zh": "你将看到我是多么守规矩。", "t": [17488, 19350]}]}, {"id": "ch10p39", "audio": true, "sents": [{"fr": "Le petit prince bâilla.", "zh": "小王子打了个哈欠。", "t": [100, 2175]}, {"fr": "Il regrettait son coucher de soleil manqué.", "zh": "他惋惜那错过的日落。", "t": [2175, 5225]}, {"fr": "Et puis il s’ennuyait déjà un peu :", "zh": "他已开始感到有些无聊了。", "t": [5225, 7550]}]}, {"id": "ch10p40", "audio": true, "sents": [{"fr": "— Je n’ai plus rien à faire ici, dit-il au roi.", "zh": "此处无事可做，他对国王说。", "t": [100, 4488]}, {"fr": "Je vais repartir !", "zh": "我将启程。", "t": [4488, 6138]}]}, {"id": "ch10p41", "audio": true, "sents": [{"fr": "— Ne pars pas, répondit le roi qui était si fier d’avoir un sujet.", "zh": "国王答道：“别走，我这么自豪有你这个臣民。”", "t": [100, 5350]}, {"fr": "Ne pars pas, je te fais ministre !", "zh": "别走，我封你为部长！", "t": [5350, 7850]}]}, {"id": "ch10p42", "audio": true, "sents": [{"fr": "— Ministre de quoi ?", "zh": "司法部长。", "t": [100, 2925]}]}, {"id": "ch10p43", "audio": true, "sents": [{"fr": "— De…", "zh": "自…", "t": [100, 1588]}, {"fr": "de la justice !", "zh": "司法部", "t": [1588, 3025]}]}, {"id": "ch10p44", "audio": true, "sents": [{"fr": "— Mais il n’y a personne à juger !", "zh": "然而，这里无人可审。", "t": [100, 3412]}]}, {"id": "ch10p45", "audio": true, "sents": [{"fr": "— On ne sait pas, lui dit le roi.", "zh": "陛下，国王说，我们无从得知。", "t": [100, 3662]}, {"fr": "Je n’ai pas fait encore le tour de mon royaume.", "zh": "我尚未巡游过我的王国。", "t": [3662, 6738]}, {"fr": "Je suis très vieux, je n’ai pas de place pour un carrosse, et ça me fatigue de marcher.", "zh": "我年事已高，没有地方停放马车，走路也让我疲惫不堪。", "t": [6738, 11238]}]}, {"id": "ch10p46", "audio": true, "sents": [{"fr": "— Oh !", "zh": "啊！", "t": [100, 3038]}, {"fr": "Mais j’ai déjà vu, dit le petit prince qui se pencha pour jeter encore un coup d’œil sur l’autre côté de la planète.", "zh": "但小王子俯身，又朝星球的另一端瞥了一眼。", "t": [3038, 9675]}, {"fr": "Il n’y a personne là-bas non plus…", "zh": "那里同样空无一人…", "t": [9675, 11212]}]}, {"id": "ch10p47", "audio": true, "sents": [{"fr": "— Tu te jugeras donc toi-même, lui répondit le roi.", "zh": "你将自我审判，国王答道。", "t": [100, 4962]}, {"fr": "C’est le plus difficile.", "zh": "这最为艰难。", "t": [4962, 7112]}, {"fr": "Il est bien plus difficile de se juger soi-même que de juger autrui.", "zh": "评判自己远比评判他人困难。", "t": [7112, 11400]}, {"fr": "Si tu réussis à bien te juger, c’est que tu es un véritable sage.", "zh": "若你能公正地评判自己，那你便是一位真正的智者。", "t": [11400, 15050]}]}, {"id": "ch10p48", "audio": true, "sents": [{"fr": "— Moi, dit le petit prince, je puis me juger moi-même n’importe où.", "zh": "小王子说：“我嘛，无论在何处，都能自我审判。”", "t": [100, 5512]}, {"fr": "Je n’ai pas besoin d’habiter ici.", "zh": "我不需要住在这里。", "t": [5512, 7337]}]}, {"id": "ch10p49", "audio": true, "sents": [{"fr": "— Hem !", "zh": "哼！", "t": [100, 2975]}, {"fr": "Hem !", "zh": "哼！", "t": [2975, 4250]}, {"fr": "dit le roi, je crois bien que sur ma planète il y a quelque part un vieux rat.", "zh": "陛下，我想这颗星球上某个角落住着一只老耗子。", "t": [4250, 8700]}, {"fr": "Je l’entends la nuit.", "zh": "我夜间听到的。", "t": [8700, 10712]}, {"fr": "Tu pourras juger ce vieux rat.", "zh": "你将审判这只老耗子。", "t": [10712, 13100]}, {"fr": "Tu le condamneras à mort de temps en temps.", "zh": "你将不时地判处它死刑。", "t": [13100, 16038]}, {"fr": "Ainsi sa vie dépendra de ta justice.", "zh": "他的生活将取决于你的公正。", "t": [16038, 18912]}, {"fr": "Mais tu le gracieras chaque fois pour l’économiser.", "zh": "但你每次都要赦免它，以保全它的生命。", "t": [18912, 22250]}, {"fr": "Il n’y en a qu’un.", "zh": "仅此一朵。", "t": [22250, 23124]}]}, {"id": "ch10p50", "audio": true, "sents": [{"fr": "— Moi, répondit le petit prince, je n’aime pas condamner à mort, et je crois bien que je m’en vais.", "zh": "我只喜欢宽恕，我相信我这就走了。", "t": [100, 6275]}]}, {"id": "ch10p51", "audio": true, "sents": [{"fr": "— Non, dit le roi.", "zh": "陛下说，不。", "t": [100, 2325]}]}, {"id": "ch10p52", "audio": true, "sents": [{"fr": "Mais le petit prince, ayant achevé ses préparatifs, ne voulut point peiner le vieux monarque :", "zh": "小王子完成准备后，不愿让老国王感到不便：", "t": [100, 5688]}]}, {"id": "ch10p53", "audio": true, "sents": [{"fr": "— Si Votre Majesté désirait être obéie ponctuellement, elle pourrait me donner un ordre raisonnable.", "zh": "若陛下希望得到准时服从，可下达一个合理的命令。", "t": [100, 6962]}, {"fr": "Elle pourrait m’ordonner, par exemple, de partir avant une minute.", "zh": "她可以命令我，比如，在一分钟之内离开。", "t": [6962, 11588]}, {"fr": "Il me semble que les conditions sont favorables…", "zh": "似乎条件很适宜…", "t": [11588, 13876]}]}, {"id": "ch10p54", "audio": true, "sents": [{"fr": "Le roi n’ayant rien répondu, le petit prince hésita d’abord, puis, avec un soupir, prit le départ.", "zh": "国王未作回应，小王子犹豫片刻，然后叹了口气，迈步离去。", "t": [100, 6338]}]}, {"id": "ch10p55", "audio": true, "sents": [{"fr": "— Je te fais mon ambassadeur, se hâta alors de crier le roi.", "zh": "陛下急忙宣布：“我封你为大使。”", "t": [100, 4513]}]}, {"id": "ch10p56", "audio": true, "sents": [{"fr": "Il avait un grand air d’autorité.", "zh": "他颇有威严之态。", "t": [100, 1850]}]}, {"id": "ch10p57", "audio": true, "sents": [{"fr": "Les grandes personnes sont bien étranges, se dit le petit prince, en lui-même, durant son voyage.", "zh": "大人们真是奇怪，小王子在旅途中自言自语。", "t": [100, 5663]}]}, {"id": "ch10p58", "audio": true, "sents": []}]}, {"id": "ch11", "title_fr": "Chapitre XI", "title_zh": "第 11 章", "paras": [{"id": "ch11p00", "audio": true, "sents": [{"fr": "La seconde planète était habitée par un vaniteux :", "zh": "第二颗星球住着一个爱虚荣的人。", "t": [100, 3287]}]}, {"id": "ch11p01", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "Ah !", "zh": "啊！", "t": [3038, 4950]}, {"fr": "Voilà la visite d’un admirateur !", "zh": "这是崇拜者的拜访！", "t": [4950, 7938]}, {"fr": "s’écria de loin le vaniteux dès qu’il aperçut le petit prince.", "zh": "那爱虚荣的人远远地就喊了起来。", "t": [7938, 10974]}]}, {"id": "ch11p02", "audio": true, "sents": [{"fr": "Car, pour les vaniteux, les autres hommes sont des admirateurs.", "zh": "然而，对于虚荣者来说，其他人都是崇拜者。", "t": [100, 3888]}]}, {"id": "ch11p03", "audio": true, "sents": [{"fr": "— Bonjour, dit le petit prince.", "zh": "你好，小王子说。", "t": [100, 3938]}, {"fr": "Vous avez un drôle de chapeau.", "zh": "您这顶帽子真古怪。", "t": [3938, 5337]}]}, {"id": "ch11p04", "audio": true, "sents": [{"fr": "— C’est pour saluer, lui répondit le vaniteux.", "zh": "这是为了敬礼，虚荣者答道。", "t": [100, 4400]}, {"fr": "C’est pour saluer quand on m’acclame.", "zh": "这是为了向欢呼我的人致敬。", "t": [4400, 6962]}, {"fr": "Malheureusement il ne passe jamais personne par ici.", "zh": "遗憾的是，这里从来没有人经过。", "t": [6962, 9588]}]}, {"id": "ch11p05", "audio": true, "sents": [{"fr": "— Ah oui ?", "zh": "啊，是的？", "t": [100, 2562]}, {"fr": "dit le petit prince qui ne comprit pas.", "zh": "小王子说，他不明白。", "t": [2562, 4187]}]}, {"id": "ch11p06", "audio": true, "sents": [{"fr": "— Frappe tes mains l’une contre l’autre, conseilla donc le vaniteux.", "zh": "请鼓掌吧，虚荣者建议道。", "t": [100, 4400]}]}, {"id": "ch11p07", "audio": true, "sents": [{"fr": "Le petit prince frappa ses mains l’une contre l’autre.", "zh": "小王子拍拍手。", "t": [100, 3412]}, {"fr": "Le vaniteux salua modestement en soulevant son chapeau.", "zh": "他谦恭地举帽致意。", "t": [3412, 6338]}]}, {"id": "ch11p08", "audio": true, "sents": [{"fr": "— Ça c’est plus amusant que la visite au roi, se dit en lui-même le petit prince.", "zh": "这比拜访国王有趣多了，小王子心想。", "t": [100, 5988]}, {"fr": "Et il recommença de frapper ses mains l’une contre l’autre.", "zh": "他又开始拍起手来。", "t": [5988, 9488]}, {"fr": "Le vaniteux recommença de saluer en soulevant son chapeau.", "zh": "虚荣者重新举起帽子，开始行礼。", "t": [9488, 12400]}]}, {"id": "ch11p09", "audio": true, "sents": [{"fr": "Après cinq minutes d’exercice le petit prince se fatigua de la monotonie du jeu :", "zh": "五分钟后，小王子对这单调的游戏感到厌倦。", "t": [100, 5037]}]}, {"id": "ch11p10", "audio": true, "sents": [{"fr": "— Et, pour que le chapeau tombe, demanda-t-il, que faut-il faire ?", "zh": "他问道：“要怎样做帽子才会掉下来？”", "t": [100, 5450]}]}, {"id": "ch11p11", "audio": true, "sents": [{"fr": "Mais le vaniteux ne l’entendit pas.", "zh": "但虚荣者并未听见。", "t": [100, 2562]}, {"fr": "Les vaniteux n’entendent jamais que les louanges.", "zh": "虚荣者只听见赞美之词。", "t": [2562, 4637]}]}, {"id": "ch11p12", "audio": true, "sents": [{"fr": "— Est-ce que tu m’admires vraiment beaucoup ?", "zh": "你真的非常崇拜我吗？", "t": [100, 3850]}, {"fr": "demanda-t-il au petit prince.", "zh": "他问小王子。", "t": [3850, 5325]}]}, {"id": "ch11p13", "audio": true, "sents": [{"fr": "— Qu’est-ce que signifie admirer ?", "zh": "什么是“崇拜”的意思？", "t": [100, 3376]}]}, {"id": "ch11p14", "audio": true, "sents": [{"fr": "— Admirer signifie reconnaître que je suis l’homme le plus beau, le mieux habillé, le plus riche et le plus intelligent de la planète.", "zh": "“崇拜的意思就是承认我是这个星球上最英俊、最会穿衣打扮、最富有、最聪明的人。”", "t": [100, 7738]}]}, {"id": "ch11p15", "audio": true, "sents": [{"fr": "— Mais tu es seul sur ta planète !", "zh": "但你的星球上只有你一个人！", "t": [100, 3262]}]}, {"id": "ch11p16", "audio": true, "sents": [{"fr": "— Fais-moi ce plaisir.", "zh": "让我也享受这份快乐吧。", "t": [100, 3175]}, {"fr": "Admire-moi quand même !", "zh": "仍旧崇拜我吧！", "t": [3175, 4900]}]}, {"id": "ch11p17", "audio": true, "sents": [{"fr": "— Je t’admire, dit le petit prince, en haussant un peu les épaules, mais en quoi cela peut-il bien t’intéresser ?", "zh": "我崇拜你，小王子耸耸肩，但这又怎能让你感到快乐呢？", "t": [100, 7638]}]}, {"id": "ch11p18", "audio": true, "sents": [{"fr": "Et le petit prince s’en fut.", "zh": "小王子便离开了。", "t": [100, 1550]}]}, {"id": "ch11p19", "audio": true, "sents": [{"fr": "Les grandes personnes sont décidément bien bizarres, se dit-il simplement en lui-même durant son voyage.", "zh": "大人们确实古怪得可以，他一边旅行一边自言自语。", "t": [100, 5487]}]}, {"id": "ch11p20", "audio": true, "sents": []}]}, {"id": "ch12", "title_fr": "Chapitre XII", "title_zh": "第 12 章", "paras": [{"id": "ch12p00", "audio": true, "sents": []}, {"id": "ch12p01", "audio": true, "sents": [{"fr": "La planète suivante était habitée par un buveur.", "zh": "下一颗星球住着个酒徒。", "t": [100, 3650]}, {"fr": "Cette visite fut très courte, mais elle plongea le petit prince dans une grande mélancolie :", "zh": "这次拜访虽短，却让小王子陷入深深的忧郁。", "t": [3650, 8862]}]}, {"id": "ch12p02", "audio": true, "sents": [{"fr": "— Que fais-tu là ?", "zh": "你在做什么？", "t": [100, 2988]}, {"fr": "dit-il au buveur, qu’il trouva installé en silence devant une collection de bouteilles vides et une collection de bouteilles pleines.", "zh": "他问那酒徒，只见他静静地坐在一堆空瓶子和满瓶之间。", "t": [2988, 8963]}]}, {"id": "ch12p03", "audio": true, "sents": [{"fr": "— Je bois, répondit le buveur, d’un air lugubre.", "zh": "他答道，带着忧郁的神情：“我喝酒。”", "t": [100, 4237]}]}, {"id": "ch12p04", "audio": true, "sents": [{"fr": "— Pourquoi bois-tu ?", "zh": "你为何而饮？", "t": [100, 3588]}, {"fr": "lui demanda le petit prince.", "zh": "小王子问他。", "t": [3588, 5150]}]}, {"id": "ch12p05", "audio": true, "sents": [{"fr": "— Pour oublier, répondit le buveur.", "zh": "为了忘却，酒徒答道。", "t": [100, 3338]}]}, {"id": "ch12p06", "audio": true, "sents": [{"fr": "— Pour oublier quoi ?", "zh": "为了忘却何事？", "t": [100, 3762]}, {"fr": "s’enquit le petit prince qui déjà le plaignait.", "zh": "小王子怜悯地问他，已为他感到难过。", "t": [3762, 5900]}]}, {"id": "ch12p07", "audio": true, "sents": [{"fr": "— Pour oublier que j’ai honte, avoua le buveur en baissant la tête.", "zh": "为了忘却羞愧，酒徒低头承认。", "t": [100, 4625]}]}, {"id": "ch12p08", "audio": true, "sents": [{"fr": "— Honte de quoi ?", "zh": "羞愧于何事？", "t": [100, 3638]}, {"fr": "s’informa le petit prince qui désirait le secourir.", "zh": "小王子询问，想要帮助他。", "t": [3638, 6387]}]}, {"id": "ch12p09", "audio": true, "sents": [{"fr": "— Honte de boire !", "zh": "羞于饮酒。", "t": [100, 3488]}, {"fr": "acheva le buveur qui s’enferma définitivement dans le silence.", "zh": "酒徒终陷沉默之中。", "t": [3488, 6750]}]}, {"id": "ch12p10", "audio": true, "sents": [{"fr": "Et le petit prince s’en fut, perplexe.", "zh": "小王子困惑地走了。", "t": [100, 2450]}]}, {"id": "ch12p11", "audio": true, "sents": [{"fr": "Les grandes personnes sont décidément très très bizarres, se disait-il en lui-même durant le voyage.", "zh": "大人确实非常非常古怪，他在旅途中自言自语道。", "t": [100, 5175]}]}, {"id": "ch12p12", "audio": true, "sents": []}]}, {"id": "ch13", "title_fr": "Chapitre XIII", "title_zh": "第 13 章", "paras": [{"id": "ch13p00", "audio": true, "sents": [{"fr": "La quatrième planète était celle du businessman.", "zh": "第四颗星球是商人之星。", "t": [100, 3575]}, {"fr": "Cet homme était si occupé qu’il ne leva même pas la tête à l’arrivée du petit prince.", "zh": "这位商人如此忙碌，以至于小王子到来时，他连头都没抬一下。", "t": [3575, 7562]}]}, {"id": "ch13p01", "audio": true, "sents": [{"fr": "— Bonjour, lui dit celui-ci.", "zh": "你好，他对他说。", "t": [100, 3912]}, {"fr": "Votre cigarette est éteinte.", "zh": "您的烟已熄灭。", "t": [3912, 5537]}]}, {"id": "ch13p02", "audio": true, "sents": [{"fr": "— Trois et deux font cinq.", "zh": "三加二等于五。", "t": [100, 3362]}, {"fr": "Cinq et sept douze.", "zh": "五加七等于十二。", "t": [3362, 5425]}, {"fr": "Douze et trois quinze.", "zh": "十二加三十五。", "t": [5425, 7475]}, {"fr": "Bonjour.", "zh": "你好。", "t": [7475, 9050]}, {"fr": "Quinze et sept vingt-deux.", "zh": "十五加七等于二十二。", "t": [9050, 11050]}, {"fr": "Vingt-deux et six vingt-huit.", "zh": "二十二加六等于二十八。", "t": [11050, 13538]}, {"fr": "Pas le temps de la rallumer.", "zh": "没空再点烟了。", "t": [13538, 15688]}, {"fr": "Vingt-six et cinq trente et un.", "zh": "二十六加五等于三十一。", "t": [15688, 18200]}, {"fr": "Ouf !", "zh": "唉！", "t": [18200, 20125]}, {"fr": "Ça fait donc cinq cent un millions six cent vingt-deux mille sept cent trente et un.", "zh": "五亿零一百六十二万二千七百三十一。", "t": [20125, 23513]}]}, {"id": "ch13p03", "audio": true, "sents": [{"fr": "— Cinq cents millions de quoi ?", "zh": "五亿零一百六十二万二千七百三十一是什么？", "t": [100, 3162]}]}, {"id": "ch13p04", "audio": true, "sents": [{"fr": "— Hein ?", "zh": "什么？", "t": [100, 3038]}, {"fr": "Tu es toujours là ?", "zh": "你还在这里吗？", "t": [3038, 5512]}, {"fr": "Cinq cent un millions de…", "zh": "五亿零一百一十…", "t": [5512, 6875]}, {"fr": "je ne sais plus…", "zh": "我已不知所措…", "t": [6875, 8400]}, {"fr": "J’ai tellement de travail !", "zh": "如此忙碌，我！", "t": [8400, 11138]}, {"fr": "Je suis sérieux, moi, je ne m’amuse pas à des balivernes !", "zh": "我是个正经人，不玩这种无聊的把戏！", "t": [11138, 15862]}, {"fr": "Deux et cinq sept…", "zh": "二加五七…", "t": [15862, 17062]}]}, {"id": "ch13p05", "audio": true, "sents": [{"fr": "— Cinq cent un millions de quoi, répéta le petit prince qui jamais de sa vie, n’avait renoncé à une question, une fois qu’il l’avait posée.", "zh": "五亿零一百一十万什么，小王子重复道，他一生从不懈怠追问。", "t": [100, 8188]}]}, {"id": "ch13p06", "audio": true, "sents": [{"fr": "Le businessman leva la tête :", "zh": "商人抬起头：", "t": [100, 2362]}]}, {"id": "ch13p07", "audio": true, "sents": [{"fr": "— Depuis cinquante-quatre ans que j’habite cette planète-ci, je n’ai été dérangé que trois fois.", "zh": "在这颗星球上住了五十四年，我只被打扰过三次。", "t": [100, 6388]}, {"fr": "La première fois ç’a été, il y a vingt-deux ans, par un hanneton qui était tombé Dieu sait d’où.", "zh": "二十二年前，一只甲虫从天而降，不知从何而来。", "t": [6388, 11950]}, {"fr": "Il répandait un bruit épouvantable, et j’ai fait quatre erreurs dans une addition.", "zh": "那声音震耳欲聋，我算加法时出了四个错。", "t": [11950, 16900]}, {"fr": "La seconde fois ç’a été, il y a onze ans, par une crise de rhumatisme.", "zh": "那次是十一年前，一场关节炎发作。", "t": [16900, 21788]}, {"fr": "Je manque d’exercice.", "zh": "我缺乏锻炼。", "t": [21788, 23988]}, {"fr": "Je n’ai pas le temps de flâner.", "zh": "我没时间闲逛。", "t": [23988, 26238]}, {"fr": "Je suis sérieux, moi.", "zh": "我是个正经人。", "t": [26238, 28688]}, {"fr": "La troisième fois…", "zh": "第三次…", "t": [28688, 29912]}, {"fr": "la voici !", "zh": "这就是了！", "t": [29912, 32125]}, {"fr": "Je disais donc cinq cent un millions…", "zh": "我说了，五亿零一百万…", "t": [32125, 33862]}]}, {"id": "ch13p08", "audio": true, "sents": [{"fr": "— Millions de quoi ?", "zh": "什么五亿？", "t": [100, 2788]}]}, {"id": "ch13p09", "audio": true, "sents": [{"fr": "Le businessman comprit qu’il n’était point d’espoir de paix :", "zh": "商人意识到和平已无望。", "t": [100, 3600]}]}, {"id": "ch13p10", "audio": true, "sents": [{"fr": "— Millions de ces petites choses que l’on voit quelquefois dans le ciel.", "zh": "满天繁星点点。", "t": [100, 4126]}]}, {"id": "ch13p11", "audio": true, "sents": [{"fr": "— Des mouches ?", "zh": "苍蝇吗？", "t": [100, 2400]}]}, {"id": "ch13p12", "audio": true, "sents": [{"fr": "— Mais non, des petites choses qui brillent.", "zh": "但不是，是一些发光的小东西。", "t": [100, 3162]}]}, {"id": "ch13p13", "audio": true, "sents": [{"fr": "— Des abeilles ?", "zh": "蜜蜂吗？", "t": [100, 2537]}]}, {"id": "ch13p14", "audio": true, "sents": [{"fr": "— Mais non.", "zh": "但不是。", "t": [100, 2462]}, {"fr": "Des petites choses dorées qui font rêvasser les fainéants.", "zh": "金黄的小东西，让闲散者沉醉于梦乡。", "t": [2462, 5812]}, {"fr": "Mais je suis sérieux, moi !", "zh": "但我是个正经人！", "t": [5812, 8862]}, {"fr": "Je n’ai pas le temps de rêvasser.", "zh": "我没空做白日梦。", "t": [8862, 10362]}]}, {"id": "ch13p15", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "des étoiles ?", "zh": "星星吗？", "t": [3038, 4426]}]}, {"id": "ch13p16", "audio": true, "sents": [{"fr": "— C’est bien ça.", "zh": "这倒是。", "t": [100, 2800]}, {"fr": "Des étoiles.", "zh": "星星。", "t": [2800, 3663]}]}, {"id": "ch13p17", "audio": true, "sents": [{"fr": "— Et que fais-tu de cinq cents millions d’étoiles ?", "zh": "你管理五千万颗星星做什么？", "t": [100, 3650]}]}, {"id": "ch13p18", "audio": true, "sents": [{"fr": "— Cinq cent un millions six cent vingt-deux mille sept cent trente et un.", "zh": "五亿零一百六十二万二千七百三十一。", "t": [100, 4862]}, {"fr": "Je suis sérieux, moi, je suis précis.", "zh": "我是个一丝不苟，力求精确的人。", "t": [4862, 7450]}]}, {"id": "ch13p19", "audio": true, "sents": [{"fr": "— Et que fais-tu de ces étoiles ?", "zh": "你把这些星星拿去干什么？", "t": [100, 3150]}]}, {"id": "ch13p20", "audio": true, "sents": [{"fr": "— Ce que j’en fais ?", "zh": "这有何用？", "t": [100, 2650]}]}, {"id": "ch13p21", "audio": true, "sents": [{"fr": "— Oui.", "zh": "是的。", "t": [100, 1525]}]}, {"id": "ch13p22", "audio": true, "sents": [{"fr": "— Rien.", "zh": "什么也没有。", "t": [100, 2512]}, {"fr": "Je les possède.", "zh": "我拥有它们。", "t": [2512, 3538]}]}, {"id": "ch13p23", "audio": true, "sents": [{"fr": "— Tu possèdes les étoiles ?", "zh": "你拥有星星吗？", "t": [100, 3013]}]}, {"id": "ch13p24", "audio": true, "sents": [{"fr": "— Oui.", "zh": "是的。", "t": [100, 1525]}]}, {"id": "ch13p25", "audio": true, "sents": [{"fr": "— Mais j’ai déjà vu un roi qui…", "zh": "但我也曾见过一个国王……", "t": [100, 2676]}]}, {"id": "ch13p26", "audio": true, "sents": [{"fr": "— Les rois ne possèdent pas.", "zh": "国王并不拥有。", "t": [100, 3188]}, {"fr": "Ils \"règnent\" sur.", "zh": "他们“统治”着。", "t": [3188, 5238]}, {"fr": "C’est très différent.", "zh": "这大不相同。", "t": [5238, 6200]}]}, {"id": "ch13p27", "audio": true, "sents": [{"fr": "— Et à quoi cela te sert-il de posséder les étoiles ?", "zh": "这对你拥有星星又有什么用呢？", "t": [100, 4275]}]}, {"id": "ch13p28", "audio": true, "sents": [{"fr": "— Ça me sert à être riche.", "zh": "这使我变得富有。", "t": [100, 2475]}]}, {"id": "ch13p29", "audio": true, "sents": [{"fr": "— Et à quoi cela te sert-il d’être riche ?", "zh": "这财富对你又有什么用呢？", "t": [100, 3737]}]}, {"id": "ch13p30", "audio": true, "sents": [{"fr": "— A acheter d’autres étoiles, si quelqu’un en trouve.", "zh": "若有人发现新的星星，我就去买下。", "t": [100, 3976]}]}, {"id": "ch13p31", "audio": true, "sents": [{"fr": "Celui-là, se dit en lui-même le petit prince, il raisonne un peu comme mon ivrogne.", "zh": "那位，小王子自言自语，他的思维有点像我见过的那个酒鬼。", "t": [100, 4675]}]}, {"id": "ch13p32", "audio": true, "sents": [{"fr": "Cependant il posa encore des questions :", "zh": "然而，他仍继续提问：", "t": [100, 2900]}]}, {"id": "ch13p33", "audio": true, "sents": [{"fr": "— Comment peut-on posséder les étoiles ?", "zh": "如何拥有星星？", "t": [100, 3513]}]}, {"id": "ch13p34", "audio": true, "sents": [{"fr": "— A qui sont-elles ?", "zh": "它们属于谁？", "t": [100, 3488]}, {"fr": "riposta, grincheux, le businessman.", "zh": "商人回答，带着不满。", "t": [3488, 6188]}]}, {"id": "ch13p35", "audio": true, "sents": [{"fr": "— Je ne sais pas.", "zh": "我不知道。", "t": [100, 2725]}, {"fr": "A personne.", "zh": "无人。", "t": [2725, 3500]}]}, {"id": "ch13p36", "audio": true, "sents": [{"fr": "— Alors elles sont à moi, car j’y ai pensé le premier.", "zh": "那么，它们就归我了，因为我首先想到了这一点。", "t": [100, 3937]}]}, {"id": "ch13p37", "audio": true, "sents": [{"fr": "— Ça suffit ?", "zh": "这还不够吗？", "t": [100, 2613]}]}, {"id": "ch13p38", "audio": true, "sents": [{"fr": "— Bien sûr.", "zh": "当然。", "t": [100, 2750]}, {"fr": "Quand tu trouves un diamant qui n’est à personne, il est à toi.", "zh": "你发现一颗无人所有的钻石，它就属于你了。", "t": [2750, 6675]}, {"fr": "Quand tu trouves une île qui n’est à personne, elle est à toi.", "zh": "你若发现一座无人之岛，那岛便属于你。", "t": [6675, 10350]}, {"fr": "Quand tu as une idée le premier, tu la fais breveter : elle est à toi.", "zh": "一旦你第一个想到一个主意，你就可以申请专利，这个主意就归你了。", "t": [10350, 15512]}, {"fr": "Et moi je possède les étoiles, puisque jamais personne avant moi n’a songé à les posséder.", "zh": "我拥有星星，因为在此之前，无人曾想过要拥有它们。", "t": [15512, 20138]}]}, {"id": "ch13p39", "audio": true, "sents": [{"fr": "— Ça c’est vrai, dit le petit prince.", "zh": "这倒是真的，小王子说。", "t": [100, 4000]}, {"fr": "Et qu’en fais-tu ?", "zh": "你打算怎么用它呢？", "t": [4000, 5537]}]}, {"id": "ch13p40", "audio": true, "sents": [{"fr": "— Je les gère.", "zh": "我管理着它们。", "t": [100, 2812]}, {"fr": "Je les compte et je les recompte, dit le businessman.", "zh": "我数了又数，商人说。", "t": [2812, 6575]}, {"fr": "C’est difficile.", "zh": "这很棘手。", "t": [6575, 8450]}, {"fr": "Mais je suis un homme sérieux !", "zh": "但我是个严肃的人！", "t": [8450, 10475]}]}, {"id": "ch13p41", "audio": true, "sents": [{"fr": "Le petit prince n’était pas satisfait encore.", "zh": "小王子仍不满足。", "t": [100, 2413]}]}, {"id": "ch13p42", "audio": true, "sents": [{"fr": "— Moi, si je possède un foulard, je puis le mettre autour de mon cou et l’emporter.", "zh": "若我拥有一条围巾，便可围在脖子上带走。", "t": [100, 6225]}, {"fr": "Moi, si je possède une fleur, je puis cueillir ma fleur et l’emporter.", "zh": "若我拥有这朵花，便可摘下它带走。", "t": [6225, 11038]}, {"fr": "Mais tu ne peux pas cueillir les étoiles !", "zh": "但你摘不下星星。", "t": [11038, 13374]}]}, {"id": "ch13p43", "audio": true, "sents": [{"fr": "— Non, mais je puis les placer en banque.", "zh": "不过，我可以把它们存进银行。", "t": [100, 3162]}]}, {"id": "ch13p44", "audio": true, "sents": [{"fr": "— Qu’est-ce que ça veut dire ?", "zh": "这究竟是什么意思？", "t": [100, 2876]}]}, {"id": "ch13p45", "audio": true, "sents": [{"fr": "— Ça veut dire que j’écris sur un petit papier le nombre de mes étoiles.", "zh": "这便意味着我在一张小纸条上写下我的星星数目。", "t": [100, 5275]}, {"fr": "Et puis j’enferme à clef ce papier-là dans un tiroir.", "zh": "然后我把这张纸条锁进抽屉里。", "t": [5275, 7850]}]}, {"id": "ch13p46", "audio": true, "sents": [{"fr": "— Et c’est tout ?", "zh": "这便是全部了吗？", "t": [100, 2413]}]}, {"id": "ch13p47", "audio": true, "sents": [{"fr": "— Ça suffit !", "zh": "这就足够了。", "t": [100, 2600]}]}, {"id": "ch13p48", "audio": true, "sents": [{"fr": "C’est amusant, pensa le petit prince.", "zh": "这挺有趣的，小王子心想。", "t": [100, 3250]}, {"fr": "C’est assez poétique.", "zh": "这颇为诗意。", "t": [3250, 5312]}, {"fr": "Mais ce n’est pas très sérieux.", "zh": "但这并非严肃正经之事。", "t": [5312, 6537]}]}, {"id": "ch13p49", "audio": true, "sents": [{"fr": "Le petit prince avait sur les choses sérieuses des idées très différentes des idées des grandes personnes.", "zh": "小王子对严肃事物的看法与大人截然不同。", "t": [100, 4900]}]}, {"id": "ch13p50", "audio": true, "sents": [{"fr": "— Moi, dit-il encore, je possède une fleur que j’arrose tous les jours.", "zh": "我，他接着说，拥有一朵我每天都浇水的花。", "t": [100, 5712]}, {"fr": "Je possède trois volcans que je ramone toutes les semaines.", "zh": "我每周都清理三座火山。", "t": [5712, 9338]}, {"fr": "Car je ramone aussi celui qui est éteint.", "zh": "只因我也抽熄灭的烟。", "t": [9338, 12238]}, {"fr": "On ne sait jamais.", "zh": "无人能预知。", "t": [12238, 13900]}, {"fr": "C’est utile à mes volcans, et c’est utile à ma fleur, que je les possède.", "zh": "这对我拥有的火山和我的花都有益。", "t": [13900, 18925]}, {"fr": "Mais tu n’es pas utile aux étoiles…", "zh": "但你对于星星并无用处……", "t": [18925, 20650]}]}, {"id": "ch13p51", "audio": true, "sents": [{"fr": "Le businessman ouvrit la bouche mais ne trouva rien à répondre, et le petit prince s’en fut.", "zh": "商人张口结舌，无言以对，小王子便离开了。", "t": [100, 4888]}]}, {"id": "ch13p52", "audio": true, "sents": [{"fr": "Les grandes personnes sont décidément tout à fait extraordinaires, se disait-il simplement en lui-même durant le voyage.", "zh": "大人真是古怪得不可思议，他一边旅行一边自言自语。", "t": [100, 6262]}]}, {"id": "ch13p53", "audio": true, "sents": []}]}, {"id": "ch14", "title_fr": "Chapitre XIV", "title_zh": "第 14 章", "paras": [{"id": "ch14p00", "audio": true, "sents": [{"fr": "La cinquième planète était très curieuse.", "zh": "第五颗星球颇为奇特。", "t": [100, 3075]}, {"fr": "C’était la plus petite de toutes.", "zh": "那是所有星球中最小的一颗。", "t": [3075, 5612]}, {"fr": "Il y avait là juste assez de place pour loger un réverbère et un allumeur de réverbères.", "zh": "那里仅能容纳一盏路灯和一个点灯人。", "t": [5612, 10875]}, {"fr": "Le petit prince ne parvenait pas à s’expliquer à quoi pouvaient servir, quelque part dans le ciel, sur une planète sans maison, ni population, un réverbère et un allumeur de réverbères.", "zh": "小王子无法理解，在这片没有房屋、无人烟的星球上，天空中某个角落的一盏路灯和点灯人究竟有何用处。", "t": [10875, 21712]}, {"fr": "Cependant il se dit en lui-même :", "zh": "然而他在心里自言自语：", "t": [21712, 23938]}]}, {"id": "ch14p01", "audio": true, "sents": [{"fr": "— Peut-être bien que cet homme est absurde.", "zh": "或许这个人很荒谬。", "t": [100, 4050]}, {"fr": "Cependant il est moins absurde que le roi, que le vaniteux, que le businessman et que le buveur.", "zh": "然而，他并不比国王、虚荣的人、商人、酒鬼更荒谬。", "t": [4050, 9962]}, {"fr": "Au moins son travail a-t-il un sens.", "zh": "至少他的工作还有意义。", "t": [9962, 12675]}, {"fr": "Quand il allume son réverbère, c’est comme s’il faisait naître une étoile de plus, ou une fleur.", "zh": "他点亮路灯，仿佛催生了一颗新的星星，或一朵盛开的鲜花。", "t": [12675, 18525]}, {"fr": "Quand il éteint son réverbère ça endort la fleur ou l’étoile.", "zh": "当它熄灭路灯，便让花朵或星星沉入梦乡。", "t": [18525, 22775]}, {"fr": "C’est une occupation très jolie.", "zh": "这是一份极美的差事。", "t": [22775, 25138]}, {"fr": "C’est véritablement utile puisque c’est joli.", "zh": "这实在有用，因为实在美。", "t": [25138, 27475]}]}, {"id": "ch14p02", "audio": true, "sents": [{"fr": "Lorsqu’il aborda la planète il salua respectueusement l’allumeur :", "zh": "他抵达星球时，恭敬地向点灯人行礼：", "t": [100, 4138]}]}, {"id": "ch14p03", "audio": true, "sents": [{"fr": "— Bonjour.", "zh": "你好。", "t": [100, 2712]}, {"fr": "Pourquoi viens-tu d’éteindre ton réverbère ?", "zh": "你为何熄灭了你的路灯？", "t": [2712, 5388]}]}, {"id": "ch14p04", "audio": true, "sents": [{"fr": "— C’est la consigne, répondit l’allumeur.", "zh": "这是规定，点灯人答道。", "t": [100, 4375]}, {"fr": "Bonjour.", "zh": "你好。", "t": [4375, 5087]}]}, {"id": "ch14p05", "audio": true, "sents": [{"fr": "— Qu’est-ce que la consigne ?", "zh": "这是规定吗？", "t": [100, 2900]}]}, {"id": "ch14p06", "audio": true, "sents": [{"fr": "— C’est d’éteindre mon réverbère.", "zh": "这是熄灭我的路灯。", "t": [100, 3675]}, {"fr": "Bonsoir.", "zh": "晚安。", "t": [3675, 4500]}]}, {"id": "ch14p07", "audio": true, "sents": [{"fr": "Et il le ralluma.", "zh": "他又点亮了路灯。", "t": [100, 1012]}]}, {"id": "ch14p08", "audio": true, "sents": [{"fr": "— Mais pourquoi viens-tu de le rallumer ?", "zh": "可你为何又把它点亮了？", "t": [100, 3675]}]}, {"id": "ch14p09", "audio": true, "sents": [{"fr": "— C’est la consigne, répondit l’allumeur.", "zh": "这是规定，点灯人答道。", "t": [100, 3512]}]}, {"id": "ch14p10", "audio": true, "sents": [{"fr": "— Je ne comprends pas, dit le petit prince.", "zh": "我不明白，小王子说。", "t": [100, 3424]}]}, {"id": "ch14p11", "audio": true, "sents": [{"fr": "— Il n’y a rien à comprendre, dit l’allumeur.", "zh": "这无需理解，点灯人说道。", "t": [100, 4375]}, {"fr": "La consigne c’est la consigne.", "zh": "这是规定，就是规定。", "t": [4375, 6912]}, {"fr": "Bonjour.", "zh": "你好。", "t": [6912, 7624]}]}, {"id": "ch14p12", "audio": true, "sents": [{"fr": "Et il éteignit son réverbère.", "zh": "他熄灭了路灯。", "t": [100, 1674]}]}, {"id": "ch14p13", "audio": true, "sents": [{"fr": "Puis il s’épongea le front avec un mouchoir à carreaux rouges.", "zh": "然后用红方格手帕抹抹额头。", "t": [100, 2938]}]}, {"id": "ch14p14", "audio": true, "sents": [{"fr": "— Je fais là un métier terrible.", "zh": "这是一份可怕的工作。", "t": [100, 3525]}, {"fr": "C’était raisonnable autrefois.", "zh": "往日倒也合乎情理。", "t": [3525, 5962]}, {"fr": "J’éteignais le matin et j’allumais le soir.", "zh": "晨熄夜点。", "t": [5962, 9062]}, {"fr": "J’avais le reste du jour pour me reposer, et le reste de la nuit pour dormir…", "zh": "我有余下的白天来休息，余下的夜晚来睡眠。", "t": [9062, 13287]}]}, {"id": "ch14p15", "audio": true, "sents": [{"fr": "— Et, depuis cette époque, la consigne a changé ?", "zh": "自那以后，规定改了？", "t": [100, 4550]}]}, {"id": "ch14p16", "audio": true, "sents": [{"fr": "— La consigne n’a pas changé, dit l’allumeur.", "zh": "规定并未更改，点灯人说道。", "t": [100, 4675]}, {"fr": "C’est bien là le drame !", "zh": "这正是悲剧所在。", "t": [4675, 7000]}, {"fr": "La planète d’année en année a tourné de plus en plus vite, et la consigne n’a pas changé !", "zh": "这颗星球年复一年地转得越来越快，而规定却依旧未变！", "t": [7000, 12188]}]}, {"id": "ch14p17", "audio": true, "sents": [{"fr": "— Alors ?", "zh": "那么？", "t": [100, 2575]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [2575, 3576]}]}, {"id": "ch14p18", "audio": true, "sents": [{"fr": "— Alors maintenant qu’elle fait un tour par minute, je n’ai plus une seconde de repos.", "zh": "现在它转一圈只需一分钟，我连一秒钟的休息时间都没有。", "t": [100, 5938]}, {"fr": "J’allume et j’éteins une fois par minute !", "zh": "每分钟点亮又熄灭一次！", "t": [5938, 8388]}]}, {"id": "ch14p19", "audio": true, "sents": [{"fr": "— Ça c’est drôle !", "zh": "这真是有趣！", "t": [100, 3362]}, {"fr": "Les jours chez toi durent une minute !", "zh": "你们那里的白天只持续一分钟！", "t": [3362, 5563]}]}, {"id": "ch14p20", "audio": true, "sents": [{"fr": "— Ce n’est pas drôle du tout, dit l’allumeur.", "zh": "这真是不有趣，点灯人说。", "t": [100, 4388]}, {"fr": "Ça fait déjà un mois que nous parlons ensemble.", "zh": "我们已交谈了一个月。", "t": [4388, 6500]}]}, {"id": "ch14p21", "audio": true, "sents": [{"fr": "— Un mois ?", "zh": "一个月？", "t": [100, 2350]}]}, {"id": "ch14p22", "audio": true, "sents": [{"fr": "— Oui.", "zh": "是的。", "t": [100, 2400]}, {"fr": "Trente minutes.", "zh": "三十分钟。", "t": [2400, 4262]}, {"fr": "Trente jours !", "zh": "三十天。", "t": [4262, 6438]}, {"fr": "Bonsoir.", "zh": "晚安。", "t": [6438, 7263]}]}, {"id": "ch14p23", "audio": true, "sents": [{"fr": "Et il ralluma son réverbère.", "zh": "他重新点亮了路灯。", "t": [100, 1700]}]}, {"id": "ch14p24", "audio": true, "sents": [{"fr": "Le petit prince le regarda et il aima cet allumeur qui était tellement fidèle à la consigne.", "zh": "小王子注视着他，喜欢这个对规定忠贞不渝的点灯人。", "t": [100, 5662]}, {"fr": "Il se souvint des couchers de soleil que lui-même allait autrefois chercher, en tirant sa chaise.", "zh": "他回想起自己过去曾搬动椅子去寻找的日落。", "t": [5662, 11238]}, {"fr": "Il voulut aider son ami :", "zh": "他想帮助他的朋友：", "t": [11238, 13325]}]}, {"id": "ch14p25", "audio": true, "sents": [{"fr": "— Tu sais…", "zh": "你知道……", "t": [100, 1975]}, {"fr": "je connais un moyen de te reposer quand tu voudras…", "zh": "我知道一个你想要休息时的办法……", "t": [1975, 4238]}]}, {"id": "ch14p26", "audio": true, "sents": [{"fr": "— Je veux toujours, dit l’allumeur.", "zh": "我总是想要，点灯人说。", "t": [100, 3113]}]}, {"id": "ch14p27", "audio": true, "sents": [{"fr": "Car on peut être, à la fois, fidèle et paresseux.", "zh": "既可忠诚，亦能懒惰。", "t": [100, 3074]}]}, {"id": "ch14p28", "audio": true, "sents": [{"fr": "Le petit prince poursuivit :", "zh": "小王子继续说道：", "t": [100, 2287]}]}, {"id": "ch14p29", "audio": true, "sents": [{"fr": "— Ta planète est tellement petite que tu en fais le tour en trois enjambées.", "zh": "他的星球如此之小，只需三步就能走完一圈。", "t": [100, 5262]}, {"fr": "Tu n’as qu’à marcher assez lentement pour rester toujours au soleil.", "zh": "只需慢慢走，就能永远沐浴在阳光下。", "t": [5262, 9150]}, {"fr": "Quand tu voudras te reposer tu marcheras…", "zh": "你想休息时，就散步吧……", "t": [9150, 11488]}, {"fr": "et le jour durera aussi longtemps que tu voudras.", "zh": "你愿它持续多久，白天就有多久。", "t": [11488, 13662]}]}, {"id": "ch14p30", "audio": true, "sents": [{"fr": "— Ça ne m’avance pas à grand’chose, dit l’allumeur.", "zh": "这对我并无多大帮助，点灯人说。", "t": [100, 4600]}, {"fr": "Ce que j’aime dans la vie, c’est dormir.", "zh": "我对生活的热爱，就是睡眠。", "t": [4600, 6776]}]}, {"id": "ch14p31", "audio": true, "sents": [{"fr": "— Ce n’est pas de chance, dit le petit prince.", "zh": "这不是运气，小王子说。", "t": [100, 3475]}]}, {"id": "ch14p32", "audio": true, "sents": [{"fr": "— Ce n’est pas de chance, dit l’allumeur.", "zh": "这不是运气，点灯人说。", "t": [100, 4025]}, {"fr": "Bonjour.", "zh": "你好。", "t": [4025, 4737]}]}, {"id": "ch14p33", "audio": true, "sents": [{"fr": "Et il éteignit son réverbère.", "zh": "他熄灭了路灯。", "t": [100, 1674]}]}, {"id": "ch14p34", "audio": true, "sents": [{"fr": "Celui-là, se dit le petit prince, tandis qu’il poursuivait plus loin son voyage, celui-là serait méprisé par tous les autres, par le roi, par le vaniteux, par le buveur, par le businessman.", "zh": "小王子心想，当他继续前行，那些人——国王、虚荣的人、酒鬼、商人——都会轻视他。", "t": [100, 12112]}, {"fr": "Cependant c’est le seul qui ne me paraisse pas ridicule.", "zh": "然而，他是唯一一个在我看来并不荒谬的人。", "t": [12112, 15725]}, {"fr": "C’est, peut-être, parce qu’il s’occupe d’autre chose que de soi-même.", "zh": "这或许是因为他关心的事情并非只关乎自己。", "t": [15725, 19300]}]}, {"id": "ch14p35", "audio": true, "sents": [{"fr": "Il eut un soupir de regret et se dit encore :", "zh": "他叹了口气，心中再次想道：", "t": [100, 2950]}]}, {"id": "ch14p36", "audio": true, "sents": [{"fr": "— Celui-là est le seul dont j’eusse pu faire mon ami.", "zh": "他是唯一一个我可以成为朋友的人。", "t": [100, 4312]}, {"fr": "Mais sa planète est vraiment trop petite.", "zh": "但他的星球实在太小了。", "t": [4312, 7125]}, {"fr": "Il n’y a pas de place pour deux…", "zh": "没有空间容纳两个人…", "t": [7125, 8475]}]}, {"id": "ch14p37", "audio": true, "sents": [{"fr": "Ce que le petit prince n’osait pas s’avouer, c’est qu’il regrettait cette planète bénie à cause, surtout, des mille quatre cent quarante couchers de soleil par vingt-quatre heures !", "zh": "他心中暗自惋惜，这颗被祝福的星球，尤其是因为它拥有每二十四小时一千四百四十次日落的奇迹。", "t": [100, 9063]}]}, {"id": "ch14p38", "audio": true, "sents": []}]}, {"id": "ch15", "title_fr": "Chapitre XV", "title_zh": "第 15 章", "paras": [{"id": "ch15p00", "audio": true, "sents": [{"fr": "La sixième planète était une planète dix fois plus vaste.", "zh": "第六颗星球是个十倍于前者的广阔星球。", "t": [100, 4000]}, {"fr": "Elle était habitée par un vieux Monsieur qui écrivait d’énormes livres.", "zh": "那颗星球上住着一位老先生，正撰写着巨著。", "t": [4000, 7125]}]}, {"id": "ch15p01", "audio": true, "sents": [{"fr": "— Tiens !", "zh": "嘿！", "t": [100, 3200]}, {"fr": "voilà un explorateur !", "zh": "来了一位探险家！", "t": [3200, 6112]}, {"fr": "s’écria-t-il, quand il aperçut le petit prince.", "zh": "他惊呼道，当他瞥见小王子。", "t": [6112, 9075]}]}, {"id": "ch15p02", "audio": true, "sents": [{"fr": "Le petit prince s’assit sur la table et souffla un peu.", "zh": "小王子坐在桌子上，轻轻叹了口气。", "t": [100, 3600]}, {"fr": "Il avait déjà tant voyagé !", "zh": "他已旅行得够多了！", "t": [3600, 5838]}]}, {"id": "ch15p03", "audio": true, "sents": [{"fr": "— D’où viens-tu ?", "zh": "你从哪里来？", "t": [100, 3462]}, {"fr": "lui dit le vieux Monsieur.", "zh": "老先生说道。", "t": [3462, 4562]}]}, {"id": "ch15p04", "audio": true, "sents": [{"fr": "— Quel est ce gros livre ?", "zh": "这是一本厚重的书吗？", "t": [100, 3188]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [3188, 5050]}, {"fr": "Que faites-vous ici ?", "zh": "您在此有何贵干？", "t": [5050, 6738]}]}, {"id": "ch15p05", "audio": true, "sents": [{"fr": "— Je suis géographe, dit le vieux Monsieur.", "zh": "我是地理学家，老先生说道。", "t": [100, 3200]}]}, {"id": "ch15p06", "audio": true, "sents": [{"fr": "— Qu’est-ce qu’un géographe ?", "zh": "地理学家是何许人也？", "t": [100, 2875]}]}, {"id": "ch15p07", "audio": true, "sents": [{"fr": "— C’est un savant qui connaît où se trouvent les mers, les fleuves, les villes, les montagnes et les déserts.", "zh": "这是一位通晓大海、江河、城市、山脉和沙漠所在地的学者。", "t": [100, 6450]}]}, {"id": "ch15p08", "audio": true, "sents": [{"fr": "— Ça c’est bien intéressant, dit le petit prince.", "zh": "这倒很有趣，小王子说。", "t": [100, 4612]}, {"fr": "Ça c’est enfin un véritable métier !", "zh": "这总算是一门真正的职业了！", "t": [4612, 8212]}, {"fr": "Et il jeta un coup d’œil autour de lui sur la planète du géographe.", "zh": "他环顾地理学家的星球。", "t": [8212, 12362]}, {"fr": "Il n’avait jamais vu encore une planète aussi majestueuse.", "zh": "这颗星球如此雄伟壮观。", "t": [12362, 15288]}]}, {"id": "ch15p09", "audio": true, "sents": [{"fr": "— Elle est bien belle, votre planète.", "zh": "您的星球真美。", "t": [100, 4112]}, {"fr": "Est-ce qu’il y a des océans ?", "zh": "这里有大洋吗？", "t": [4112, 6100]}]}, {"id": "ch15p10", "audio": true, "sents": [{"fr": "— Je ne puis pas le savoir, dit le géographe.", "zh": "地理学家说：“这我无法知晓。”", "t": [100, 3512]}]}, {"id": "ch15p11", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "(Le petit prince était déçu.) Et des montagnes ?", "zh": "小王子失望地问道：有山脉吗？", "t": [3038, 6962]}]}, {"id": "ch15p12", "audio": true, "sents": [{"fr": "— Je ne puis pas le savoir, dit le géographe.", "zh": "地理学家说：“这我无法知晓。”", "t": [100, 3512]}]}, {"id": "ch15p13", "audio": true, "sents": [{"fr": "— Et des villes et des fleuves et des déserts ?", "zh": "有城市、河流、沙漠吗？", "t": [100, 3463]}]}, {"id": "ch15p14", "audio": true, "sents": [{"fr": "— Je ne puis pas le savoir non plus, dit le géographe.", "zh": "地理学家说：“我也无法知晓。”", "t": [100, 3838]}]}, {"id": "ch15p15", "audio": true, "sents": [{"fr": "— Mais vous êtes géographe !", "zh": "可您是地理学家啊！", "t": [100, 2987]}]}, {"id": "ch15p16", "audio": true, "sents": [{"fr": "— C’est exact, dit le géographe, mais je ne suis pas explorateur.", "zh": "这话说得没错，地理学家答道，但我并非探险家。", "t": [100, 5912]}, {"fr": "Je manque absolument d’explorateurs.", "zh": "我急需探险家。", "t": [5912, 8875]}, {"fr": "Ce n’est pas le géographe qui va faire le compte des villes, des fleuves, des montagnes, des mers, des océans et des déserts.", "zh": "这不是地理学家去计算城市、江河、山脉、海洋、大洋和沙漠的数量。", "t": [8875, 16612]}, {"fr": "Le géographe est trop important pour flâner.", "zh": "地理学家太过重要，不容闲逛。", "t": [16612, 19650]}, {"fr": "Il ne quitte pas son bureau.", "zh": "他始终未曾离开过办公室。", "t": [19650, 21875]}, {"fr": "Mais il y reçoit les explorateurs.", "zh": "但他在此接待探险家。", "t": [21875, 24612]}, {"fr": "Il les interroge, et il prend en note leurs souvenirs.", "zh": "他询问他们，并记录下他们的回忆。", "t": [24612, 28388]}, {"fr": "Et si les souvenirs de l’un d’entre eux lui paraissent intéressants, le géographe fait faire une enquête sur la moralité de l’explorateur.", "zh": "若其中某位探险家的回忆引起了他的兴趣，地理学家便会对其品德进行调查。", "t": [28388, 34763]}]}, {"id": "ch15p17", "audio": true, "sents": [{"fr": "— Pourquoi ça ?", "zh": "为什么这样呢？", "t": [100, 2538]}]}, {"id": "ch15p18", "audio": true, "sents": [{"fr": "— Parce qu’un explorateur qui mentirait entraînerait des catastrophes dans les livres de géographie.", "zh": "因为一个说谎的探险家会把地理学书籍引向灾难。", "t": [100, 6775]}, {"fr": "Et aussi un explorateur qui boirait trop.", "zh": "还有一位过量饮酒的探险家。", "t": [6775, 9025]}]}, {"id": "ch15p19", "audio": true, "sents": [{"fr": "— Pourquoi ça ?", "zh": "这为什么呢？", "t": [100, 2850]}, {"fr": "fit le petit prince.", "zh": "小王子坐下。", "t": [2850, 3888]}]}, {"id": "ch15p20", "audio": true, "sents": [{"fr": "— Parce que les ivrognes voient double.", "zh": "酒鬼看东西总是重影。", "t": [100, 3612]}, {"fr": "Alors le géographe noterait deux montagnes, là où il n’y en a qu’une seule.", "zh": "于是地理学家会在只有一座山的地方记下两座山。", "t": [3612, 7438]}]}, {"id": "ch15p21", "audio": true, "sents": [{"fr": "— Je connais quelqu’un, dit le petit prince, qui serait mauvais explorateur.", "zh": "我认识一个人，小王子说，他若成为探险家，必定是个糟糕的。", "t": [100, 5237]}]}, {"id": "ch15p22", "audio": true, "sents": [{"fr": "— C’est possible.", "zh": "这也许可能。", "t": [100, 2850]}, {"fr": "Donc, quand la moralité de l’explorateur paraît bonne, on fait une enquête sur sa découverte.", "zh": "于是，当探险家的品德看来良好时，便对其发现进行调查。", "t": [2850, 8074]}]}, {"id": "ch15p23", "audio": true, "sents": [{"fr": "— On va voir ?", "zh": "咱们瞧瞧吧？", "t": [100, 2424]}]}, {"id": "ch15p24", "audio": true, "sents": [{"fr": "— Non.", "zh": "不。", "t": [100, 2350]}, {"fr": "C’est trop compliqué.", "zh": "这太复杂了。", "t": [2350, 4362]}, {"fr": "Mais on exige de l’explorateur qu’il fournisse des preuves.", "zh": "但要求探险家提供证据。", "t": [4362, 8175]}, {"fr": "S’il s’agit par exemple de la découverte d’une grosse montagne, on exige qu’il en rapporte de grosses pierres.", "zh": "若发现了一座大山，便要求他带来大石。", "t": [8175, 13787]}]}, {"id": "ch15p25", "audio": true, "sents": [{"fr": "Le géographe soudain s’émut.", "zh": "地理学家突然动容。", "t": [100, 1662]}]}, {"id": "ch15p26", "audio": true, "sents": [{"fr": "— Mais toi, tu viens de loin !", "zh": "你远道而来！", "t": [100, 4300]}, {"fr": "Tu es explorateur !", "zh": "你是探险家！", "t": [4300, 6975]}, {"fr": "Tu vas me décrire ta planète !", "zh": "请给我描述你的星球吧！", "t": [6975, 9125]}]}, {"id": "ch15p27", "audio": true, "sents": [{"fr": "Et le géographe, ayant ouvert son registre, tailla son crayon.", "zh": "地理学家打开了他的登记册，削尖了铅笔。", "t": [100, 4675]}, {"fr": "On note d’abord au crayon les récits des explorateurs.", "zh": "首先用铅笔记录探险家的叙述。", "t": [4675, 8388]}, {"fr": "On attend, pour noter à l’encre, que l’explorateur ait fourni des preuves.", "zh": "待用钢笔记录探险家提供的证据。", "t": [8388, 12513]}]}, {"id": "ch15p28", "audio": true, "sents": [{"fr": "— Alors ?", "zh": "那么？", "t": [100, 3162]}, {"fr": "interrogea le géographe.", "zh": "询问地理学家。", "t": [3162, 4512]}]}, {"id": "ch15p29", "audio": true, "sents": [{"fr": "— Oh !", "zh": "嘿！", "t": [100, 3038]}, {"fr": "chez moi, dit le petit prince, ce n’est pas très intéressant, c’est tout petit.", "zh": "在我这儿，小王子说，可没什么意思，它太小了。", "t": [3038, 8300]}, {"fr": "J’ai trois volcans.", "zh": "我有三座火山。", "t": [8300, 10162]}, {"fr": "Deux volcans en activité, et un volcan éteint.", "zh": "两座活火山，一座休眠火山。", "t": [10162, 13762]}, {"fr": "Mais on ne sait jamais.", "zh": "但谁又能预料呢？", "t": [13762, 14787]}]}, {"id": "ch15p30", "audio": true, "sents": [{"fr": "— On ne sait jamais, dit le géographe.", "zh": "谁又能预料呢，地理学家说。", "t": [100, 3162]}]}, {"id": "ch15p31", "audio": true, "sents": [{"fr": "— J’ai aussi une fleur.", "zh": "我也有朵花。", "t": [100, 2426]}]}, {"id": "ch15p32", "audio": true, "sents": [{"fr": "— Nous ne notons pas les fleurs, dit le géographe.", "zh": "我们不记录花朵，地理学家说。", "t": [100, 3625]}]}, {"id": "ch15p33", "audio": true, "sents": [{"fr": "— Pourquoi ça !", "zh": "这为什么呢？", "t": [100, 3388]}, {"fr": "c’est le plus joli !", "zh": "这是最美的！", "t": [3388, 5112]}]}, {"id": "ch15p34", "audio": true, "sents": [{"fr": "— Parce que les fleurs sont éphémères.", "zh": "因为花儿是短暂的。", "t": [100, 2824]}]}, {"id": "ch15p35", "audio": true, "sents": [{"fr": "— Qu’est ce que signifie : \"éphémère\" ?", "zh": "“‘昙花一现’是什么意思？”", "t": [100, 4550]}]}, {"id": "ch15p36", "audio": true, "sents": [{"fr": "— Les géographies, dit le géographe, sont les livres les plus précieux de tous les livres.", "zh": "地理书，地理学家说，是所有书籍中最珍贵的。", "t": [100, 6412]}, {"fr": "Elles ne se démodent jamais.", "zh": "它们永远不会过时。", "t": [6412, 8512]}, {"fr": "Il est très rare qu’une montagne change de place.", "zh": "山移位，极为罕见。", "t": [8512, 11700]}, {"fr": "Il est très rare qu’un océan se vide de son eau.", "zh": "海洋干涸极为罕见。", "t": [11700, 14750]}, {"fr": "Nous écrivons des choses éternelles.", "zh": "我们记录永恒的事物。", "t": [14750, 16663]}]}, {"id": "ch15p37", "audio": true, "sents": [{"fr": "— Mais les volcans éteints peuvent se réveiller, interrompit le petit prince.", "zh": "但休眠火山会苏醒，小王子打断道。", "t": [100, 5738]}, {"fr": "Qu’est-ce que signifie \"éphémère\" ?", "zh": "“‘昙花一现’是什么意思？”", "t": [5738, 8088]}]}, {"id": "ch15p38", "audio": true, "sents": [{"fr": "— Que les volcans soient éteints ou soient éveillés, ça revient au même pour nous autres, dit le géographe.", "zh": "火山熄灭与否，对我们来说并无二致，地理学家说。", "t": [100, 6988]}, {"fr": "Ce qui compte pour nous, c’est la montagne.", "zh": "对我们而言，重要的是山。", "t": [6988, 10125]}, {"fr": "Elle ne change pas.", "zh": "它始终如一。", "t": [10125, 10976]}]}, {"id": "ch15p39", "audio": true, "sents": [{"fr": "— Mais qu’est-ce que signifie \"éphémère\" ?", "zh": "但这“昙花一现”究竟是什么意思？", "t": [100, 4550]}, {"fr": "répéta le petit prince qui, de sa vie, n’avait renoncé à une question, une fois qu’il l’avait posée.", "zh": "小王子反复地说，他一生中从未放弃过一个问题，一旦提出，就绝不罢休。", "t": [4550, 10188]}]}, {"id": "ch15p40", "audio": true, "sents": [{"fr": "— Ça signifie \"qui est menacé de disparition prochaine\".", "zh": "这指的是“面临即将消失的危险”。", "t": [100, 4100]}]}, {"id": "ch15p41", "audio": true, "sents": [{"fr": "— Ma fleur est menacée de disparition prochaine ?", "zh": "我的玫瑰面临即将消失的威胁？", "t": [100, 4013]}]}, {"id": "ch15p42", "audio": true, "sents": [{"fr": "— Bien sûr.", "zh": "当然。", "t": [100, 1874]}]}, {"id": "ch15p43", "audio": true, "sents": [{"fr": "Ma fleur est éphémère, se dit le petit prince, et elle n’a que quatre épines pour se défendre contre le monde !", "zh": "我的玫瑰是短暂的，小王子说，而她只有四根刺来抵御这个世界！", "t": [100, 7125]}, {"fr": "Et je l’ai laissée toute seule chez moi !", "zh": "我让她孤零零地留在了家里！", "t": [7125, 9426]}]}, {"id": "ch15p44", "audio": true, "sents": [{"fr": "Ce fut là son premier mouvement de regret.", "zh": "那是他第一次感到悔恨。", "t": [100, 2900]}, {"fr": "Mais il reprit courage :", "zh": "但他重拾勇气：", "t": [2900, 4826]}]}, {"id": "ch15p45", "audio": true, "sents": [{"fr": "— Que me conseillez-vous d’aller visiter ?", "zh": "您能否指点我该去哪儿访问？", "t": [100, 3912]}, {"fr": "demanda-t-il.", "zh": "他问。", "t": [3912, 4762]}]}, {"id": "ch15p46", "audio": true, "sents": [{"fr": "— La planète Terre, lui répondit le géographe.", "zh": "地球，地理学家回答道。", "t": [100, 4762]}, {"fr": "Elle a une bonne réputation…", "zh": "她享有盛名……", "t": [4762, 6188]}]}, {"id": "ch15p47", "audio": true, "sents": [{"fr": "Et le petit prince s’en fut, songeant à sa fleur.", "zh": "小王子离去，心中想着他的玫瑰。", "t": [100, 2850]}]}, {"id": "ch15p48", "audio": true, "sents": []}]}, {"id": "ch16", "title_fr": "Chapitre XVI", "title_zh": "第 16 章", "paras": [{"id": "ch16p00", "audio": true, "sents": []}, {"id": "ch16p01", "audio": true, "sents": [{"fr": "La septième planète fut donc la Terre.", "zh": "于是，第七颗星球便是地球。", "t": [100, 2212]}]}, {"id": "ch16p02", "audio": true, "sents": [{"fr": "La Terre n’est pas une planète quelconque !", "zh": "地球并非普通行星！", "t": [100, 3525]}, {"fr": "On y compte cent onze rois (en n’oubliant pas, bien sûr, les rois nègres), sept mille géographes, neuf cent mille businessmen, sept millions et demi d’ivrognes, trois cent onze millions de vaniteux, c’est-à-dire environ deux milliards de grandes personnes.", "zh": "地球上有一百一十一位国王（别忘了，当然，还有黑人国王）、七千位地理学家、九十万位商人、七百五十万位酒徒、三亿一千一百万位虚荣者，也就是说，大约有二十亿个大人。", "t": [3525, 17075]}]}, {"id": "ch16p03", "audio": true, "sents": [{"fr": "Pour vous donner une idée des dimensions de la Terre je vous dirai qu’avant l’invention de l’électricité on y devait entretenir, sur l’ensemble des six continents, une véritable armée de quatre cent soixante-deux mille cinq cent onze allumeurs de réverbères.", "zh": "为了使你们对地球的规模有所概念，我得告诉你们，在电灯发明之前，六大洲上必须维持着一支由四十六万二千五百一十一个提灯人组成的庞大军队。", "t": [100, 11913]}]}, {"id": "ch16p04", "audio": true, "sents": [{"fr": "Vu d’un peu loin ça faisait un effet splendide.", "zh": "从远处望去，那景象颇为壮观。", "t": [100, 3375]}, {"fr": "Les mouvements de cette armée étaient réglés comme ceux d’un ballet d’opéra.", "zh": "这支军队的步伐如同歌剧芭蕾般整齐。", "t": [3375, 7925]}, {"fr": "D’abord venait le tour des allumeurs de réverbères de Nouvelle-Zélande et d’Australie.", "zh": "首先轮到新西兰和澳大利亚的路灯点亮者。", "t": [7925, 12500]}, {"fr": "Puis ceux-ci, ayant allumé leurs lampions, s’en allaient dormir.", "zh": "然后，他们点亮了灯笼，便去睡觉了。", "t": [12500, 16788]}, {"fr": "Alors entraient à leur tour dans la danse les allumeurs de réverbères de Chine et de Sibérie.", "zh": "接着，中国和西伯利亚的路灯点亮者也加入了舞蹈的行列。", "t": [16788, 21875]}, {"fr": "Puis eux aussi s’escamotaient dans les coulisses.", "zh": "他们也在幕后悄然退场。", "t": [21875, 24862]}, {"fr": "Alors venait le tour des allumeurs de réverbères de Russie et des Indes.", "zh": "接着轮到俄罗斯和印度的路灯点亮者。", "t": [24862, 29375]}, {"fr": "Puis de ceux d’Afrique et d’Europe.", "zh": "接着是非洲和欧洲的。", "t": [29375, 31750]}, {"fr": "Puis de ceux d’Amérique du Sud.", "zh": "接着是南美洲的。", "t": [31750, 34212]}, {"fr": "Puis de ceux d’Amérique du Nord.", "zh": "接着是北美洲的。", "t": [34212, 36612]}, {"fr": "Et jamais ils ne se trompaient dans leur ordre d’entrée en scène.", "zh": "他们从未在进场顺序上出错。", "t": [36612, 40138]}, {"fr": "C’était grandiose.", "zh": "宏伟壮观。", "t": [40138, 41200]}]}, {"id": "ch16p05", "audio": true, "sents": [{"fr": "Seuls, l’allumeur de l’unique réverbère du pôle Nord, et son confrère de l’unique réverbère du pôle Sud, menaient des vies d’oisiveté et de nonchalance : ils travaillaient deux fois par an.", "zh": "北极那盏路灯的守护者和南极的同仁，过着闲适而懒散的生活：他们一年只工作两次。", "t": [100, 10625]}]}, {"id": "ch16p06", "audio": true, "sents": []}, {"id": "ch16p07", "audio": true, "sents": []}]}, {"id": "ch17", "title_fr": "Chapitre XVII", "title_zh": "第 17 章", "paras": [{"id": "ch17p00", "audio": true, "sents": [{"fr": "Quand on veut faire de l’esprit, il arrive que l’on mente un peu.", "zh": "想卖弄聪明时，难免会撒个小谎。", "t": [100, 4012]}, {"fr": "Je n’ai pas été très honnête en vous parlant des allumeurs de réverbères.", "zh": "在介绍点灯人时，我并未完全坦诚。", "t": [4012, 8375]}, {"fr": "Je risque de donner une fausse idée de notre planète à ceux qui ne la connaissent pas.", "zh": "我可能给不熟悉我们星球的人留下了错误的印象。", "t": [8375, 13000]}, {"fr": "Les hommes occupent très peu de place sur la terre.", "zh": "人在地球上所占之地甚微。", "t": [13000, 16312]}, {"fr": "Si les deux milliards d’habitants qui peuplent la terre se tenaient debout et un peu serrés, comme pour un meeting, ils logeraient aisément sur une place publique de vingt milles de long sur vingt milles de large.", "zh": "若地球上的二十亿居民站立并稍微挤在一起，就像参加集会一样，他们可以轻松地占据一个长二十英里、宽二十英里的公共广场。", "t": [16312, 26325]}, {"fr": "On pourrait entasser l’humanité sur le moindre petit îlot du Pacifique.", "zh": "可以把人类堆在太平洋最小的岛屿上。", "t": [26325, 29912]}]}, {"id": "ch17p01", "audio": true, "sents": [{"fr": "Les grandes personnes, bien sûr, ne vous croiront pas.", "zh": "当然，大人们是不会相信你们的。", "t": [100, 4038]}, {"fr": "Elles s’imaginent tenir beaucoup de place.", "zh": "它们自以为占据了很大空间。", "t": [4038, 7025]}, {"fr": "Elles se voient importantes comme des baobabs.", "zh": "她们自以为像猴面包树一般重要。", "t": [7025, 10050]}, {"fr": "Vous leur conseillerez donc de faire le calcul.", "zh": "你们就建议他们算一算。", "t": [10050, 13312]}, {"fr": "Elles adorent les chiffres : ça leur plaira.", "zh": "她们喜欢数字：这会让他们高兴。", "t": [13312, 16950]}, {"fr": "Mais ne perdez pas votre temps à ce pensum.", "zh": "但别浪费时间在这种空想上。", "t": [16950, 19962]}, {"fr": "C’est inutile.", "zh": "这毫无意义。", "t": [19962, 21825]}, {"fr": "Vous avez confiance en moi.", "zh": "你们对我有信心。", "t": [21825, 23200]}]}, {"id": "ch17p02", "audio": true, "sents": [{"fr": "Le petit prince, une fois sur terre, fut donc bien surpris de ne voir personne.", "zh": "小王子一踏上地球，便惊讶地发现无人踪影。", "t": [100, 5662]}, {"fr": "Il avait déjà peur de s’être trompé de planète, quand un anneau couleur de lune remua dans le sable.", "zh": "他已担心自己误闯了星球，忽见沙地上月色般的圆环在扭动。", "t": [5662, 10800]}]}, {"id": "ch17p03", "audio": true, "sents": [{"fr": "— Bonne nuit, fit le petit prince à tout hasard.", "zh": "随口道声晚安，小王子随口说。", "t": [100, 3637]}]}, {"id": "ch17p04", "audio": true, "sents": [{"fr": "— Bonne nuit, fit le serpent.", "zh": "晚安，蛇说。", "t": [100, 2650]}]}, {"id": "ch17p05", "audio": true, "sents": [{"fr": "— Sur quelle planète suis-je tombé ?", "zh": "我降落在了哪个星球上？", "t": [100, 3688]}, {"fr": "demanda le petit prince.", "zh": "小王子问道。", "t": [3688, 4963]}]}, {"id": "ch17p06", "audio": true, "sents": [{"fr": "— Sur la Terre, en Afrique, répondit le serpent.", "zh": "蛇回答说：“在非洲，地球。”", "t": [100, 4025]}]}, {"id": "ch17p07", "audio": true, "sents": [{"fr": "— Ah !…", "zh": "哦！", "t": [100, 3038]}, {"fr": "Il n’y a donc personne sur la Terre ?", "zh": "所以地球上没有人吗？", "t": [3038, 5425]}]}, {"id": "ch17p08", "audio": true, "sents": [{"fr": "— Ici c’est le désert.", "zh": "这里是一片沙漠。", "t": [100, 3162]}, {"fr": "Il n’y a personne dans les déserts.", "zh": "沙漠中无人迹。", "t": [3162, 5700]}, {"fr": "La Terre est grande, dit le serpent.", "zh": "大地辽阔，蛇说。", "t": [5700, 7563]}]}, {"id": "ch17p09", "audio": true, "sents": [{"fr": "Le petit prince s’assit sur une pierre et leva les yeux vers le ciel :", "zh": "小王子坐在一块石头上，抬头仰望天空：", "t": [100, 3750]}]}, {"id": "ch17p10", "audio": true, "sents": [{"fr": "— Je me demande, dit-il, si les étoiles sont éclairées afin que chacun puisse un jour retrouver la sienne.", "zh": "我暗自思忖，他说，星星之所以发光，是否为了让每个人终有一天能找到属于自己的那颗。", "t": [100, 7638]}, {"fr": "Regarde ma planète.", "zh": "看我的星球。", "t": [7638, 9938]}, {"fr": "Elle est juste au-dessus de nous…", "zh": "它就在我们头顶上方……", "t": [9938, 12125]}, {"fr": "Mais comme elle est loin !", "zh": "然而，它多么遥远啊！", "t": [12125, 13813]}]}, {"id": "ch17p11", "audio": true, "sents": [{"fr": "— Elle est belle, dit le serpent.", "zh": "它真美，蛇说。", "t": [100, 3538]}, {"fr": "Que viens-tu faire ici ?", "zh": "你为何来到这里？", "t": [3538, 5375]}]}, {"id": "ch17p12", "audio": true, "sents": [{"fr": "— J’ai des difficultés avec une fleur, dit le petit prince.", "zh": "我与一朵花闹了别扭。", "t": [100, 4362]}]}, {"id": "ch17p13", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 2488]}, {"fr": "fit le serpent.", "zh": "蛇蜷缩着。", "t": [2488, 3224]}]}, {"id": "ch17p14", "audio": true, "sents": [{"fr": "Et ils se turent.", "zh": "他们沉默了。", "t": [100, 925]}]}, {"id": "ch17p15", "audio": true, "sents": [{"fr": "— Où sont les hommes ?", "zh": "这里何来人影？", "t": [100, 2862]}, {"fr": "reprit enfin le petit prince.", "zh": "终于又见到了小王子。", "t": [2862, 5175]}, {"fr": "On est un peu seul dans le désert…", "zh": "在这沙漠中，我们略显孤单。", "t": [5175, 6876]}]}, {"id": "ch17p16", "audio": true, "sents": [{"fr": "— On est seul aussi chez les hommes, dit le serpent.", "zh": "人世间，我们同样孤独。", "t": [100, 3500]}]}, {"id": "ch17p17", "audio": true, "sents": [{"fr": "Le petit prince le regarda longtemps :", "zh": "小王子久久地凝视着他。", "t": [100, 2812]}]}, {"id": "ch17p18", "audio": true, "sents": [{"fr": "— Tu es une drôle de bête, lui dit-il enfin, mince comme un doigt…", "zh": "你真是个奇怪的动物，他终于说道，细得像一根手指。", "t": [100, 4662]}]}, {"id": "ch17p19", "audio": true, "sents": [{"fr": "— Mais je suis plus puissant que le doigt d’un roi, dit le serpent.", "zh": "蛇说：“我比国王的手指还要强大。”", "t": [100, 4087]}]}, {"id": "ch17p20", "audio": true, "sents": [{"fr": "Le petit prince eut un sourire :", "zh": "小王子微微一笑。", "t": [100, 2288]}]}, {"id": "ch17p21", "audio": true, "sents": [{"fr": "— Tu n’es pas bien puissant…", "zh": "你并不怎么强大…", "t": [100, 2462]}, {"fr": "tu n’as même pas de pattes…", "zh": "你连脚都没有…", "t": [2462, 3750]}, {"fr": "tu ne peux même pas voyager…", "zh": "你甚至无法旅行…", "t": [3750, 5063]}]}, {"id": "ch17p22", "audio": true, "sents": [{"fr": "— Je puis t’emporter plus loin qu’un navire, dit le serpent.", "zh": "我能带你走得更远，蛇说。", "t": [100, 4025]}]}, {"id": "ch17p23", "audio": true, "sents": [{"fr": "Il s’enroula autour de la cheville du petit prince, comme un bracelet d’or :", "zh": "它绕着小王子的脚踝盘旋，宛如一枚金镯。", "t": [100, 4587]}]}, {"id": "ch17p24", "audio": true, "sents": [{"fr": "— Celui que je touche, je le rends à la terre dont il est sorti, dit-il encore.", "zh": "它触碰到的，便将它送回它所来的土地。", "t": [100, 6125]}, {"fr": "Mais tu es pur et tu viens d’une étoile…", "zh": "但你纯洁，你是从星星上来的……", "t": [6125, 8038]}]}, {"id": "ch17p25", "audio": true, "sents": [{"fr": "Le petit prince ne répondit rien.", "zh": "小王子沉默不语。", "t": [100, 1937]}]}, {"id": "ch17p26", "audio": true, "sents": [{"fr": "— Tu me fais pitié, toi si faible, sur cette Terre de granit.", "zh": "你如此弱小，在这片花岗岩构成的土地上，真让人怜悯。", "t": [100, 5588]}, {"fr": "Je puis t’aider un jour si tu regrettes trop ta planète.", "zh": "若你过于思念你的星球，我或许能助你一臂之力。", "t": [5588, 9262]}, {"fr": "Je puis…", "zh": "我能…", "t": [9262, 9950]}]}, {"id": "ch17p27", "audio": true, "sents": [{"fr": "— Oh !", "zh": "哦！", "t": [100, 3038]}, {"fr": "J’ai très bien compris, fit le petit prince, mais pourquoi parles-tu toujours par énigmes ?", "zh": "小王子说：“我完全明白了，可你为何总是用谜语来说话？”", "t": [3038, 8362]}]}, {"id": "ch17p28", "audio": true, "sents": [{"fr": "— Je les résous toutes, dit le serpent.", "zh": "蛇说：“我都能解开。”", "t": [100, 3037]}]}, {"id": "ch17p29", "audio": true, "sents": [{"fr": "Et ils se turent.", "zh": "他们沉默了。", "t": [100, 925]}]}, {"id": "ch17p30", "audio": true, "sents": []}]}, {"id": "ch18", "title_fr": "Chapitre XVIII", "title_zh": "第 18 章", "paras": [{"id": "ch18p00", "audio": true, "sents": [{"fr": "Le petit prince traversa le désert et ne rencontra qu'une fleur.", "zh": "小王子穿越沙漠，只邂逅了一朵花。", "t": [100, 4300]}, {"fr": "Une fleur à trois pétales, une fleur de rien du tout...", "zh": "一朵三瓣的花，平淡无奇的花儿……", "t": [4300, 7150]}]}, {"id": "ch18p01", "audio": true, "sents": [{"fr": "— Bonjour, dit le petit prince.", "zh": "你好，小王子说。", "t": [100, 2063]}]}, {"id": "ch18p02", "audio": true, "sents": [{"fr": "— Bonjour, dit la fleur.", "zh": "你好，花儿说。", "t": [100, 1787]}]}, {"id": "ch18p03", "audio": true, "sents": [{"fr": "— Où sont les hommes ? demanda poliment le petit prince.", "zh": "小王子彬彬有礼地问道：“人们在哪里？”", "t": [100, 2837]}]}, {"id": "ch18p04", "audio": true, "sents": [{"fr": "La fleur, un jour, avait vu passer une caravane :", "zh": "那朵花儿，有一天，曾见过一队商队经过。", "t": [100, 3275]}]}, {"id": "ch18p05", "audio": true, "sents": [{"fr": "— Les hommes ? Il en existe, je crois, six ou sept.", "zh": "人们？我想大概有六七个吧。", "t": [100, 5150]}, {"fr": "Je les ai aperçus il y a des années.", "zh": "几年前，我曾见过他们。", "t": [5150, 7862]}, {"fr": "Mais on ne sait jamais où les trouver.", "zh": "但谁又能知晓他们在何方。", "t": [7862, 10400]}, {"fr": "Le vent les promène.", "zh": "风儿将他们吹散了。", "t": [10400, 12325]}, {"fr": "Ils manquent de racines, ça les gêne beaucoup.", "zh": "他们无根之苦，颇感困扰。", "t": [12325, 14800]}]}, {"id": "ch18p06", "audio": true, "sents": [{"fr": "— Adieu, fit le petit prince.", "zh": "再会了，小王子说。", "t": [100, 1825]}]}, {"id": "ch18p07", "audio": true, "sents": [{"fr": "— Adieu, dit la fleur.", "zh": "再会了，花儿说。", "t": [100, 1550]}]}]}, {"id": "ch19", "title_fr": "Chapitre XIX", "title_zh": "第 19 章", "paras": [{"id": "ch19p00", "audio": true, "sents": []}, {"id": "ch19p01", "audio": true, "sents": [{"fr": "Le petit prince fit l’ascension d’une haute montagne.", "zh": "小王子攀登上一座高山。", "t": [100, 3425]}, {"fr": "Les seules montagnes qu’il eût jamais connues étaient les trois volcans qui lui arrivaient au genou.", "zh": "他仅知的山只有那三座火山，它们高不过他的膝盖。", "t": [3425, 8325]}, {"fr": "Et il se servait du volcan éteint comme d’un tabouret.", "zh": "他以那座死火山当凳子用。", "t": [8325, 11650]}, {"fr": "\"D’une montagne haute comme celle-ci, se dit-il donc, j’apercevrai d’un coup toute la planète et tous les hommes…\" Mais il n’aperçut rien que des aiguilles de roc bien aiguisées.", "zh": "自言自语道：“在这座高山之巅，我本该一望无际地看到整个星球和所有人……”然而，他只见到了锋利的岩石尖刺。", "t": [11650, 21150]}]}, {"id": "ch19p02", "audio": true, "sents": [{"fr": "— Bonjour, dit-il à tout hasard.", "zh": "他随口说道：“你好。”", "t": [100, 3150]}]}, {"id": "ch19p03", "audio": true, "sents": [{"fr": "— Bonjour…", "zh": "你好…", "t": [100, 2700]}, {"fr": "Bonjour…", "zh": "你好…", "t": [2700, 4312]}, {"fr": "Bonjour…", "zh": "你好…", "t": [4312, 5238]}, {"fr": "répondit l’écho.", "zh": "回声答道。", "t": [5238, 6200]}]}, {"id": "ch19p04", "audio": true, "sents": [{"fr": "— Qui êtes-vous ?", "zh": "你是谁？", "t": [100, 2812]}, {"fr": "dit le petit prince.", "zh": "小王子说道。", "t": [2812, 3800]}]}, {"id": "ch19p05", "audio": true, "sents": [{"fr": "— Qui êtes-vous…", "zh": "你是谁？", "t": [100, 2088]}, {"fr": "qui êtes-vous…", "zh": "您是何人？", "t": [2088, 2888]}, {"fr": "qui êtes-vous…", "zh": "您是何人？", "t": [2888, 3762]}, {"fr": "répondit l’écho.", "zh": "回声应道。", "t": [3762, 4687]}]}, {"id": "ch19p06", "audio": true, "sents": [{"fr": "— Soyez mes amis, je suis seul, dit-il.", "zh": "“成为我的朋友吧，我很孤独。”", "t": [100, 3650]}]}, {"id": "ch19p07", "audio": true, "sents": [{"fr": "— Je suis seul…", "zh": "我独自行走。", "t": [100, 2125]}, {"fr": "je suis seul…", "zh": "我独自行走。", "t": [2125, 2988]}, {"fr": "je suis seul…", "zh": "我独自行走。", "t": [2988, 3912]}, {"fr": "répondit l’écho.", "zh": "回声答道。", "t": [3912, 4800]}]}, {"id": "ch19p08", "audio": true, "sents": [{"fr": "\"Quelle drôle de planète !", "zh": "多么奇特的星球！", "t": [100, 2175]}, {"fr": "pensa-t-il alors.", "zh": "他暗自思忖。", "t": [2175, 4075]}, {"fr": "Elle est toute sèche, et toute pointue et toute salée.", "zh": "她干巴巴的，尖尖的，咸咸的。", "t": [4075, 7538]}, {"fr": "Et les hommes manquent d’imagination.", "zh": "人们缺乏想象力。", "t": [7538, 10100]}, {"fr": "Ils répètent ce qu’on leur dit…", "zh": "他们重复着别人告诉他们的话。", "t": [10100, 12450]}, {"fr": "Chez moi j’avais une fleur : elle parlait toujours la première…\"", "zh": "在我那颗星球上，我有一朵花，她总是抢先开口……", "t": [12450, 16062]}]}, {"id": "ch19p09", "audio": true, "sents": []}, {"id": "ch19p10", "audio": true, "sents": []}]}, {"id": "ch20", "title_fr": "Chapitre XX", "title_zh": "第 20 章", "paras": [{"id": "ch20p00", "audio": true, "sents": [{"fr": "Mais il arriva que le petit prince, ayant longtemps marché à travers les sables, les rocs et les neiges, découvrit enfin une route.", "zh": "小王子跋涉于沙砾、岩石与冰雪之间，终于发现了一条道路。", "t": [100, 7800]}, {"fr": "Et les routes vont toutes chez les hommes.", "zh": "每条路都通往人间。", "t": [7800, 9400]}]}, {"id": "ch20p01", "audio": true, "sents": [{"fr": "— Bonjour, dit-il.", "zh": "你好，他道。", "t": [100, 2562]}]}, {"id": "ch20p02", "audio": true, "sents": [{"fr": "C’était un jardin fleuri de roses.", "zh": "这是一座玫瑰盛开的花园。", "t": [100, 1887]}]}, {"id": "ch20p03", "audio": true, "sents": [{"fr": "— Bonjour, dirent les roses.", "zh": "玫瑰们说：“你好。”", "t": [100, 2763]}]}, {"id": "ch20p04", "audio": true, "sents": [{"fr": "Le petit prince les regarda.", "zh": "小王子凝视着她们。", "t": [100, 2562]}, {"fr": "Elles ressemblaient toutes à sa fleur.", "zh": "她们都像他的那朵花。", "t": [2562, 4250]}]}, {"id": "ch20p05", "audio": true, "sents": [{"fr": "— Qui êtes-vous ?", "zh": "你是谁？", "t": [100, 3388]}, {"fr": "leur demanda-t-il, stupéfait.", "zh": "他惊讶地问道：“你们是谁？”", "t": [3388, 5488]}]}, {"id": "ch20p06", "audio": true, "sents": [{"fr": "— Nous sommes des roses, dirent les roses.", "zh": "我们是玫瑰。", "t": [100, 3075]}]}, {"id": "ch20p07", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 2462]}, {"fr": "fit le petit prince…", "zh": "小王子愣住了。", "t": [2462, 3475]}]}, {"id": "ch20p08", "audio": true, "sents": [{"fr": "Et il se sentit très malheureux.", "zh": "他感到非常难过。", "t": [100, 2375]}, {"fr": "Sa fleur lui avait raconté qu’elle était seule de son espèce dans l’univers.", "zh": "她的花儿曾告诉他，她是宇宙间独一无二的存在。", "t": [2375, 6875]}, {"fr": "Et voici qu’il en était cinq mille, toutes semblables, dans un seul jardin !", "zh": "在这座花园里，竟有五千朵，个个都长得一模一样！", "t": [6875, 11274]}]}, {"id": "ch20p09", "audio": true, "sents": [{"fr": "\"Elle serait bien vexée, se dit-il, si elle voyait ça…", "zh": "她要是看到这个，准会生气，他想。", "t": [100, 3612]}, {"fr": "elle tousserait énormément et ferait semblant de mourir pour échapper au ridicule.", "zh": "她将剧烈咳嗽，装作要死去，以逃避羞辱。", "t": [3612, 8275]}, {"fr": "Et je serais bien obligé de faire semblant de la soigner, car, sinon, pour m’humilier moi aussi, elle se laisserait vraiment mourir…\"", "zh": "我只好装作悉心照料她，否则，她为了羞辱我，真的会让自己死去……", "t": [8275, 15462]}]}, {"id": "ch20p10", "audio": true, "sents": [{"fr": "Puis il se dit encore : \"Je me croyais riche d’une fleur unique, et je ne possède qu’une rose ordinaire.", "zh": "我原以为拥有独一无二的花朵，却不过是一朵平凡的玫瑰。", "t": [100, 6912]}, {"fr": "Ça et mes trois volcans qui m’arrivent au genou, et dont l’un, peut-être, est éteint pour toujours, ça ne fait pas de moi un bien grand prince…\" Et, couché dans l’herbe, il pleura.", "zh": "那又如何，加上我的三座火山，它们只到我的膝盖，其中一座也许永远熄灭了，这并不能使我成为一位伟大的王子……于是，他躺在草地上哭泣。", "t": [6912, 16963]}]}, {"id": "ch20p11", "audio": true, "sents": []}]}, {"id": "ch21", "title_fr": "Chapitre XXI", "title_zh": "第 21 章", "paras": [{"id": "ch21p00", "audio": true, "sents": []}, {"id": "ch21p01", "audio": true, "sents": [{"fr": "C’est alors qu’apparut le renard :", "zh": "那时，狐狸出现了。", "t": [100, 2338]}]}, {"id": "ch21p02", "audio": true, "sents": [{"fr": "— Bonjour, dit le renard.", "zh": "你好，狐狸说。", "t": [100, 2837]}]}, {"id": "ch21p03", "audio": true, "sents": [{"fr": "— Bonjour, répondit poliment le petit prince, qui se retourna mais ne vit rien.", "zh": "小王子彬彬有礼地回答，他转过身，却什么也没看见。", "t": [100, 5600]}]}, {"id": "ch21p04", "audio": true, "sents": [{"fr": "— Je suis là, dit la voix, sous le pommier.", "zh": "我在苹果树下。", "t": [100, 3450]}]}, {"id": "ch21p05", "audio": true, "sents": [{"fr": "— Qui es-tu ?", "zh": "你是谁？", "t": [100, 2762]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [2762, 4612]}, {"fr": "Tu es bien joli…", "zh": "你真可爱……", "t": [4612, 5587]}]}, {"id": "ch21p06", "audio": true, "sents": [{"fr": "— Je suis un renard, dit le renard.", "zh": "我是狐狸，狐狸说。", "t": [100, 3112]}]}, {"id": "ch21p07", "audio": true, "sents": [{"fr": "— Viens jouer avec moi, lui proposa le petit prince.", "zh": "小王子邀请道：“来和我一起玩吧。”", "t": [100, 5025]}, {"fr": "Je suis tellement triste…", "zh": "我非常伤心……", "t": [5025, 6313]}]}, {"id": "ch21p08", "audio": true, "sents": [{"fr": "— Je ne puis pas jouer avec toi, dit le renard.", "zh": "我不能和你一起玩，狐狸说。", "t": [100, 4475]}, {"fr": "Je ne suis pas apprivoisé.", "zh": "我尚未被驯养。", "t": [4475, 5875]}]}, {"id": "ch21p09", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "pardon, fit le petit prince.", "zh": "哦，对不起，小王子站直了。", "t": [3038, 4863]}]}, {"id": "ch21p10", "audio": true, "sents": [{"fr": "Mais, après réflexion, il ajouta :", "zh": "然而，经过一番思考，他又补充道：", "t": [100, 3263]}]}, {"id": "ch21p11", "audio": true, "sents": [{"fr": "— Qu’est-ce que signifie \"apprivoiser\" ?", "zh": "“驯养究竟意味着什么？”", "t": [100, 3588]}]}, {"id": "ch21p12", "audio": true, "sents": [{"fr": "— Tu n’es pas d’ici, dit le renard, que cherches-tu ?", "zh": "你不是本地人，狐狸说，你在寻找什么？", "t": [100, 4575]}]}, {"id": "ch21p13", "audio": true, "sents": [{"fr": "— Je cherche les hommes, dit le petit prince.", "zh": "小王子说：“我在寻找人类。”", "t": [100, 4362]}, {"fr": "Qu’est-ce que signifie \"apprivoiser\" ?", "zh": "驯养究竟是什么意思？", "t": [4362, 6762]}]}, {"id": "ch21p14", "audio": true, "sents": [{"fr": "— Les hommes, dit le renard, ils ont des fusils et ils chassent.", "zh": "人类啊，狐狸说，他们有枪，他们打猎。", "t": [100, 5225]}, {"fr": "C’est bien gênant !", "zh": "这真尴尬！", "t": [5225, 7688]}, {"fr": "Ils élèvent aussi des poules.", "zh": "他们也养鸡。", "t": [7688, 10012]}, {"fr": "C’est leur seul intérêt.", "zh": "这是他们唯一的乐趣。", "t": [10012, 12000]}, {"fr": "Tu cherches des poules ?", "zh": "你在找母鸡吗？", "t": [12000, 13612]}]}, {"id": "ch21p15", "audio": true, "sents": [{"fr": "— Non, dit le petit prince.", "zh": "小王子说：“不。”", "t": [100, 3662]}, {"fr": "Je cherche des amis.", "zh": "我在寻找朋友。", "t": [3662, 5700]}, {"fr": "Qu’est-ce que signifie \"apprivoiser\" ?", "zh": "驯养究竟是什么意思？", "t": [5700, 8100]}]}, {"id": "ch21p16", "audio": true, "sents": [{"fr": "— C’est une chose trop oubliée, dit le renard.", "zh": "这是一件被人遗忘干净了的事情，狐狸说。", "t": [100, 4412]}, {"fr": "Ça signifie \"créer des liens…\"", "zh": "这意味着“建立联系……”", "t": [4412, 6150]}]}, {"id": "ch21p17", "audio": true, "sents": [{"fr": "— Créer des liens ?", "zh": "建立联系？", "t": [100, 2750]}]}, {"id": "ch21p18", "audio": true, "sents": [{"fr": "— Bien sûr, dit le renard.", "zh": "当然，狐狸说。", "t": [100, 3762]}, {"fr": "Tu n’es encore pour moi qu’un petit garçon tout semblable à cent mille petits garçons.", "zh": "你对我来说，不过是一个和成千上万个孩子一样的小男孩。", "t": [3762, 8425]}, {"fr": "Et je n’ai pas besoin de toi.", "zh": "我并不需要你。", "t": [8425, 10675]}, {"fr": "Et tu n’as pas besoin de moi non plus.", "zh": "你也不需要我。", "t": [10675, 13212]}, {"fr": "Je ne suis pour toi qu’un renard semblable à cent mille renards.", "zh": "你对我来说，不过是一只与众不同的狐狸。", "t": [13212, 17100]}, {"fr": "Mais, si tu m’apprivoises, nous aurons besoin l’un de l’autre.", "zh": "但如果你驯养了我，我们就会互相需要。", "t": [17100, 21388]}, {"fr": "Tu seras pour moi unique au monde.", "zh": "你将是我世间唯一的存在。", "t": [21388, 23975]}, {"fr": "Je serai pour toi unique au monde…", "zh": "你将是我世间独一无二的存在。", "t": [23975, 25763]}]}, {"id": "ch21p19", "audio": true, "sents": [{"fr": "— Je commence à comprendre, dit le petit prince.", "zh": "我开始明白了，小王子说。", "t": [100, 4688]}, {"fr": "Il y a une fleur…", "zh": "这里有一朵花……", "t": [4688, 5838]}, {"fr": "je crois qu’elle m’a apprivoisé…", "zh": "我觉得她驯养了我……", "t": [5838, 7237]}]}, {"id": "ch21p20", "audio": true, "sents": [{"fr": "— C’est possible, dit le renard.", "zh": "这或许可能，狐狸说。", "t": [100, 3750]}, {"fr": "On voit sur la Terre toutes sortes de choses…", "zh": "地球上有着各式各样的东西……", "t": [3750, 5738]}]}, {"id": "ch21p21", "audio": true, "sents": [{"fr": "— Oh !", "zh": "哦！", "t": [100, 3038]}, {"fr": "ce n’est pas sur la Terre, dit le petit prince.", "zh": "这不在地球上，小王子说。", "t": [3038, 5525]}]}, {"id": "ch21p22", "audio": true, "sents": [{"fr": "Le renard parut très intrigué :", "zh": "狐狸显得非常好奇。", "t": [100, 2575]}]}, {"id": "ch21p23", "audio": true, "sents": [{"fr": "— Sur une autre planète ?", "zh": "在另一个星球上？", "t": [100, 2900]}]}, {"id": "ch21p24", "audio": true, "sents": [{"fr": "— Oui.", "zh": "是的。", "t": [100, 1525]}]}, {"id": "ch21p25", "audio": true, "sents": [{"fr": "— Il y a des chasseurs, sur cette planète-là ?", "zh": "那颗星球上有猎人吗？", "t": [100, 4163]}]}, {"id": "ch21p26", "audio": true, "sents": [{"fr": "— Non.", "zh": "不。", "t": [100, 1474]}]}, {"id": "ch21p27", "audio": true, "sents": [{"fr": "— Ça, c’est intéressant !", "zh": "这很有意思！", "t": [100, 4188]}, {"fr": "Et des poules ?", "zh": "也养鸡吗？", "t": [4188, 5474]}]}, {"id": "ch21p28", "audio": true, "sents": [{"fr": "— Non.", "zh": "不。", "t": [100, 1474]}]}, {"id": "ch21p29", "audio": true, "sents": [{"fr": "— Rien n’est parfait, soupira le renard.", "zh": "狐狸叹了口气：“世上没有完美的事。”", "t": [100, 3500]}]}, {"id": "ch21p30", "audio": true, "sents": [{"fr": "Mais le renard revint à son idée :", "zh": "但狐狸又回到了他的想法。", "t": [100, 2588]}]}, {"id": "ch21p31", "audio": true, "sents": [{"fr": "— Ma vie est monotone.", "zh": "我的生活单调乏味。", "t": [100, 3212]}, {"fr": "Je chasse les poules, les hommes me chassent.", "zh": "我捕猎鸡，人追逐我。", "t": [3212, 6350]}, {"fr": "Toutes les poules se ressemblent, et tous les hommes se ressemblent.", "zh": "所有的鸡都长得一样，所有的人也都长得一样。", "t": [6350, 10150]}, {"fr": "Je m’ennuie donc un peu.", "zh": "我有些无聊。", "t": [10150, 12375]}, {"fr": "Mais, si tu m’apprivoises, ma vie sera comme ensoleillée.", "zh": "但若你驯养了我，我的生命将如阳光般灿烂。", "t": [12375, 16600]}, {"fr": "Je connaîtrai un bruit de pas qui sera différent de tous les autres.", "zh": "我将能辨识出与众不同的脚步声。", "t": [16600, 20550]}, {"fr": "Les autres pas me font rentrer sous terre.", "zh": "别人的脚步声让我躲回地洞。", "t": [20550, 23438]}, {"fr": "Le tien m’appellera hors du terrier, comme une musique.", "zh": "你的脚步声会把我从地洞里唤出，像一首乐曲。", "t": [23438, 27150]}, {"fr": "Et puis regarde !", "zh": "然后，瞧！", "t": [27150, 29550]}, {"fr": "Tu vois, là-bas, les champs de blé ?", "zh": "你瞧，那边的麦田？", "t": [29550, 33338]}, {"fr": "Je ne mange pas de pain.", "zh": "我不吃面包。", "t": [33338, 35438]}, {"fr": "Le blé pour moi est inutile.", "zh": "麦子对我毫无意义。", "t": [35438, 37988]}, {"fr": "Les champs de blé ne me rappellent rien.", "zh": "麦田唤不起我的任何联想。", "t": [37988, 40600]}, {"fr": "Et ça, c’est triste !", "zh": "这真令人悲伤。", "t": [40600, 43325]}, {"fr": "Mais tu as des cheveux couleur d’or.", "zh": "你的头发是金色的。", "t": [43325, 45862]}, {"fr": "Alors ce sera merveilleux quand tu m’auras apprivoisé !", "zh": "那时，你驯养了我，一切都将变得美妙无比。", "t": [45862, 49950]}, {"fr": "Le blé, qui est doré, me fera souvenir de toi.", "zh": "金黄的麦子会让我想起你。", "t": [49950, 53900]}, {"fr": "Et j’aimerai le bruit du vent dans le blé…", "zh": "我愿听那麦田里风声。", "t": [53900, 55688]}]}, {"id": "ch21p32", "audio": true, "sents": [{"fr": "Le renard se tut et regarda longtemps le petit prince :", "zh": "狐狸静默下来，久久地凝视着小王子。", "t": [100, 3375]}]}, {"id": "ch21p33", "audio": true, "sents": [{"fr": "— S’il te plaît…", "zh": "请。", "t": [100, 2038]}, {"fr": "apprivoise-moi !", "zh": "驯养我吧！", "t": [2038, 3725]}, {"fr": "dit-il.", "zh": "狐狸说。", "t": [3725, 4250]}]}, {"id": "ch21p34", "audio": true, "sents": [{"fr": "— Je veux bien, répondit le petit prince, mais je n’ai pas beaucoup de temps.", "zh": "我愿意，小王子回答道，但我没有太多时间。", "t": [100, 5900]}, {"fr": "J’ai des amis à découvrir et beaucoup de choses à connaître.", "zh": "我有朋友要结识，有许多事要了解。", "t": [5900, 8775]}]}, {"id": "ch21p35", "audio": true, "sents": [{"fr": "— On ne connaît que les choses que l’on apprivoise, dit le renard.", "zh": "人只能认识自己驯养的东西，狐狸说。", "t": [100, 5088]}, {"fr": "Les hommes n’ont plus le temps de rien connaître.", "zh": "人们不再有时间去了解任何事物。", "t": [5088, 8112]}, {"fr": "Ils achètent des choses toutes faites chez les marchands.", "zh": "他们在商人那里购买现成的东西。", "t": [8112, 11225]}, {"fr": "Mais comme il n’existe point de marchands d’amis, les hommes n’ont plus d’amis.", "zh": "然而，既然没有商人出售朋友，人们便不再有朋友。", "t": [11225, 15775]}, {"fr": "Si tu veux un ami, apprivoise-moi !", "zh": "若你愿有朋友，就驯养我吧！", "t": [15775, 18437]}]}, {"id": "ch21p36", "audio": true, "sents": [{"fr": "— Que faut-il faire ?", "zh": "你需要做什么呢？", "t": [100, 2988]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [2988, 3988]}]}, {"id": "ch21p37", "audio": true, "sents": [{"fr": "— Il faut être très patient, répondit le renard.", "zh": "需极有耐心，狐狸答道。", "t": [100, 4712]}, {"fr": "Tu t’assoiras d’abord un peu loin de moi, comme ça, dans l’herbe.", "zh": "你先在我稍远的地方，这样坐在草地上。", "t": [4712, 8975]}, {"fr": "Je te regarderai du coin de l’œil et tu ne diras rien.", "zh": "我斜眼凝视着你，你却一言不发。", "t": [8975, 12512]}, {"fr": "Le langage est source de malentendus.", "zh": "语言是误会的根源。", "t": [12512, 15362]}, {"fr": "Mais, chaque jour, tu pourras t’asseoir un peu plus près…", "zh": "但每天，你可以坐得离我更近些……", "t": [15362, 18450]}]}, {"id": "ch21p38", "audio": true, "sents": [{"fr": "Le lendemain revint le petit prince.", "zh": "次日，小王子又来了。", "t": [100, 1925]}]}, {"id": "ch21p39", "audio": true, "sents": [{"fr": "— Il eût mieux valu revenir à la même heure, dit le renard.", "zh": "最好按时来。", "t": [100, 4988]}, {"fr": "Si tu viens, par exemple, à quatre heures de l’après-midi, dès trois heures je commencerai d’être heureux.", "zh": "若你下午四点钟来，从三点钟起，我便开始感到幸福了。", "t": [4988, 11162]}, {"fr": "Plus l’heure avancera, plus je me sentirai heureux.", "zh": "随着时刻的推移，我愈发感到幸福。", "t": [11162, 14625]}, {"fr": "A quatre heures, déjà, je m’agiterai et m’inquiéterai ; je découvrirai le prix du bonheur !", "zh": "四点钟，我早已坐立不安，开始体会幸福的真谛！", "t": [14625, 21925]}, {"fr": "Mais si tu viens n’importe quand, je ne saurai jamais à quelle heure m’habiller le cœur…", "zh": "但如果你随时来，我就不知道何时该装扮我的心了。", "t": [21925, 26762]}, {"fr": "Il faut des rites.", "zh": "仪式是必要的。", "t": [26762, 27688]}]}, {"id": "ch21p40", "audio": true, "sents": [{"fr": "— Qu’est-ce qu’un rite ?", "zh": "何谓仪式？", "t": [100, 2862]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [2862, 3850]}]}, {"id": "ch21p41", "audio": true, "sents": [{"fr": "— C’est aussi quelque chose de trop oublié, dit le renard.", "zh": "这也是一件被人遗忘干净了的事情，狐狸说。", "t": [100, 5075]}, {"fr": "C’est ce qui fait qu’un jour est différent des autres jours, une heure, des autres heures.", "zh": "这就是使某一日不同于其他日子的原因，某一小时不同于其他小时。", "t": [5075, 10188]}, {"fr": "Il y a un rite, par exemple, chez mes chasseurs.", "zh": "例如，在我那些猎人的家中，有一个仪式。", "t": [10188, 14025]}, {"fr": "Ils dansent le jeudi avec les filles du village.", "zh": "他们每周四与村里的姑娘们跳舞。", "t": [14025, 17212]}, {"fr": "Alors le jeudi est jour merveilleux !", "zh": "于是星期四是个美好的日子！", "t": [17212, 20450]}, {"fr": "Je vais me promener jusqu’à la vigne.", "zh": "我将去葡萄园散步。", "t": [20450, 23138]}, {"fr": "Si les chasseurs dansaient n’importe quand, les jours se ressembleraient tous, et je n’aurais point de vacances.", "zh": "如果猎人随时跳舞，每一天都一样，我就没有假期了。", "t": [23138, 28463]}]}, {"id": "ch21p42", "audio": true, "sents": [{"fr": "Ainsi le petit prince apprivoisa le renard.", "zh": "小王子驯服了狐狸。", "t": [100, 3150]}, {"fr": "Et quand l’heure du départ fut proche :", "zh": "当离别时刻临近：", "t": [3150, 5338]}]}, {"id": "ch21p43", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 2400]}, {"fr": "dit le renard…", "zh": "狐狸说。", "t": [2400, 4050]}, {"fr": "Je pleurerai.", "zh": "我将哭泣。", "t": [4050, 4900]}]}, {"id": "ch21p44", "audio": true, "sents": [{"fr": "— C’est ta faute, dit le petit prince, je ne te souhaitais point de mal, mais tu as voulu que je t’apprivoise…", "zh": "这是你的错，小王子说，我本不想给你带来伤害，但你却要我做你的朋友……", "t": [100, 6812]}]}, {"id": "ch21p45", "audio": true, "sents": [{"fr": "— Bien sûr, dit le renard.", "zh": "当然，狐狸说。", "t": [100, 2900]}]}, {"id": "ch21p46", "audio": true, "sents": [{"fr": "— Mais tu vas pleurer !", "zh": "你将会哭泣！", "t": [100, 3212]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [3212, 4213]}]}, {"id": "ch21p47", "audio": true, "sents": [{"fr": "— Bien sûr, dit le renard.", "zh": "当然，狐狸说。", "t": [100, 2900]}]}, {"id": "ch21p48", "audio": true, "sents": [{"fr": "— Alors tu n’y gagnes rien !", "zh": "那你就一无所获了！", "t": [100, 3213]}]}, {"id": "ch21p49", "audio": true, "sents": [{"fr": "— J’y gagne, dit le renard, à cause de la couleur du blé.", "zh": "我因麦子的颜色而受益。", "t": [100, 4437]}]}, {"id": "ch21p50", "audio": true, "sents": [{"fr": "Puis il ajouta :", "zh": "然后他又说：", "t": [100, 1812]}]}, {"id": "ch21p51", "audio": true, "sents": [{"fr": "— Va revoir les roses.", "zh": "去再见那朵玫瑰。", "t": [100, 3150]}, {"fr": "Tu comprendras que la tienne est unique au monde.", "zh": "你的玫瑰是世界上独一无二的。", "t": [3150, 6312]}, {"fr": "Tu reviendras me dire adieu, et je te ferai cadeau d’un secret.", "zh": "你将回来向我告别，我会送你一个秘密。", "t": [6312, 9576]}]}, {"id": "ch21p52", "audio": true, "sents": [{"fr": "Le petit prince s’en fut revoir les roses :", "zh": "小王子去再见他的玫瑰。", "t": [100, 2737]}]}, {"id": "ch21p53", "audio": true, "sents": [{"fr": "— Vous n’êtes pas du tout semblables à ma rose, vous n’êtes rien encore, leur dit-il.", "zh": "你们一点也不像我的玫瑰，你们还什么都不是。", "t": [100, 6350]}, {"fr": "Personne ne vous a apprivoisé et vous n’avez apprivoisé personne.", "zh": "没有人驯养过你，你也未曾驯养过任何人。", "t": [6350, 10350]}, {"fr": "Vous êtes comme était mon renard.", "zh": "你就像我的狐狸曾经那样。", "t": [10350, 12812]}, {"fr": "Ce n’était qu’un renard semblable à cent mille autres.", "zh": "这不过是一只与众不同的狐狸。", "t": [12812, 16100]}, {"fr": "Mais j’en ai fait mon ami, et il est maintenant unique au monde.", "zh": "但如今，他已成为我的朋友，世上独一无二。", "t": [16100, 19125]}]}, {"id": "ch21p54", "audio": true, "sents": [{"fr": "Et les roses étaient bien gênées.", "zh": "玫瑰们感到很不自在。", "t": [100, 1475]}]}, {"id": "ch21p55", "audio": true, "sents": [{"fr": "— Vous êtes belles, mais vous êtes vides, leur dit-il encore.", "zh": "你们很美，但你们空洞无物。", "t": [100, 5238]}, {"fr": "On ne peut pas mourir pour vous.", "zh": "人们不会为你们而死。", "t": [5238, 7475]}, {"fr": "Bien sûr, ma rose à moi, un passant ordinaire croirait qu’elle vous ressemble.", "zh": "当然，我的玫瑰，一个普通路人会认为她与你相似。", "t": [7475, 12600]}, {"fr": "Mais à elle seule elle est plus importante que vous toutes, puisque c’est elle que j’ai arrosée.", "zh": "然而，仅她一人，便比你们所有人都重要，因为是她，我为之浇灌。", "t": [12600, 17688]}, {"fr": "Puisque c’est elle que j’ai mise sous globe.", "zh": "既然是她，我给她罩上了花罩。", "t": [17688, 20625]}, {"fr": "Puisque c’est elle que j’ai abritée par le paravent.", "zh": "既然是她，我给她遮风挡雨。", "t": [20625, 23912]}, {"fr": "Puisque c’est elle dont j’ai tué les chenilles (sauf les deux ou trois pour les papillons).", "zh": "既然是我杀死了毛毛虫（除了两三条变成蝴蝶的）。", "t": [23912, 28838]}, {"fr": "Puisque c’est elle que j’ai écoutée se plaindre, ou se vanter, ou même quelquefois se taire.", "zh": "既然是她，我倾听她的抱怨，或她的吹嘘，有时也看着她默默无语的样子。", "t": [28838, 34288]}, {"fr": "Puisque c’est ma rose.", "zh": "既然这是我的玫瑰。", "t": [34288, 35450]}]}, {"id": "ch21p56", "audio": true, "sents": [{"fr": "Et il revint vers le renard :", "zh": "他又回到狐狸身边：", "t": [100, 2125]}]}, {"id": "ch21p57", "audio": true, "sents": [{"fr": "— Adieu, dit-il…", "zh": "再见，他说。", "t": [100, 2262]}]}, {"id": "ch21p58", "audio": true, "sents": [{"fr": "— Adieu, dit le renard.", "zh": "再见，狐狸说。", "t": [100, 3462]}, {"fr": "Voici mon secret.", "zh": "这是我的秘密。", "t": [3462, 5362]}, {"fr": "Il est très simple : on ne voit bien qu’avec le cœur.", "zh": "用心去看，才能看得清楚。", "t": [5362, 9575]}, {"fr": "L’essentiel est invisible pour les yeux.", "zh": "肉眼难见其本质。", "t": [9575, 11450]}]}, {"id": "ch21p59", "audio": true, "sents": [{"fr": "— L’essentiel est invisible pour les yeux, répéta le petit prince, afin de se souvenir.", "zh": "肉眼难见其本质，小王子反复说道，以便牢记。", "t": [100, 6075]}]}, {"id": "ch21p60", "audio": true, "sents": [{"fr": "— C’est le temps que tu as perdu pour ta rose qui fait ta rose si importante.", "zh": "你为你的玫瑰所浪费的时间，使你的玫瑰变得如此重要。", "t": [100, 4725]}]}, {"id": "ch21p61", "audio": true, "sents": [{"fr": "— C’est le temps que j’ai perdu pour ma rose…", "zh": "我已为我的玫瑰浪费了时光。", "t": [100, 3262]}, {"fr": "fit le petit prince, afin de se souvenir.", "zh": "小王子，为了记住。", "t": [3262, 5687]}]}, {"id": "ch21p62", "audio": true, "sents": [{"fr": "— Les hommes ont oublié cette vérité, dit le renard.", "zh": "人们忘记了这条真理，狐狸说。", "t": [100, 4775]}, {"fr": "Mais tu ne dois pas l’oublier.", "zh": "但你绝不能忘记。", "t": [4775, 7062]}, {"fr": "Tu deviens responsable pour toujours de ce que tu as apprivoisé.", "zh": "你将永远对你驯养之物负责。", "t": [7062, 11125]}, {"fr": "Tu es responsable de ta rose…", "zh": "你对你那朵玫瑰负有责任。", "t": [11125, 12900]}]}, {"id": "ch21p63", "audio": true, "sents": [{"fr": "— Je suis responsable de ma rose…", "zh": "我对我那朵玫瑰负责……", "t": [100, 3212]}, {"fr": "répéta le petit prince, afin de se souvenir.", "zh": "小王子反复念叨，以便牢记。", "t": [3212, 5925]}]}, {"id": "ch21p64", "audio": true, "sents": []}]}, {"id": "ch22", "title_fr": "Chapitre XXII", "title_zh": "第 22 章", "paras": [{"id": "ch22p00", "audio": true, "sents": []}, {"id": "ch22p01", "audio": true, "sents": [{"fr": "— Bonjour, dit le petit prince.", "zh": "你好，小王子说。", "t": [100, 3074]}]}, {"id": "ch22p02", "audio": true, "sents": [{"fr": "— Bonjour, dit l’aiguilleur.", "zh": "你好，扳道工说。", "t": [100, 2863]}]}, {"id": "ch22p03", "audio": true, "sents": [{"fr": "— Que fais-tu ici ?", "zh": "你在此做什么？", "t": [100, 3100]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [3100, 4088]}]}, {"id": "ch22p04", "audio": true, "sents": [{"fr": "— Je trie les voyageurs, par paquets de mille, dit l’aiguilleur.", "zh": "我按千人为一组整理旅客，扳道工说。", "t": [100, 6125]}, {"fr": "J’expédie les trains qui les emportent, tantôt vers la droite, tantôt vers la gauche.", "zh": "我调度那些载着他们去往左右两侧的列车。", "t": [6125, 10000]}]}, {"id": "ch22p05", "audio": true, "sents": [{"fr": "Et un rapide illuminé, grondant comme le tonnerre, fit trembler la cabine d’aiguillage.", "zh": "一列灯火通明的火车，如雷霆般轰鸣，震得扳道房摇曳不定。", "t": [100, 4675]}]}, {"id": "ch22p06", "audio": true, "sents": [{"fr": "— Ils sont bien pressés, dit le petit prince.", "zh": "他们匆匆忙忙，小王子说。", "t": [100, 4362]}, {"fr": "Que cherchent-ils ?", "zh": "他们在寻找什么？", "t": [4362, 5762]}]}, {"id": "ch22p07", "audio": true, "sents": [{"fr": "— L’homme de la locomotive l’ignore lui-même, dit l’aiguilleur.", "zh": "列车长自己也不知道。", "t": [100, 4300]}]}, {"id": "ch22p08", "audio": true, "sents": [{"fr": "Et gronda, en sens inverse, un second rapide illuminé.", "zh": "另一列灯火通明的快车，从相反方向轰鸣而来。", "t": [100, 3550]}]}, {"id": "ch22p09", "audio": true, "sents": [{"fr": "— Ils reviennent déjà ?", "zh": "他们已经回来了吗？", "t": [100, 3150]}, {"fr": "demanda le petit prince…", "zh": "小王子问道…", "t": [3150, 4413]}]}, {"id": "ch22p10", "audio": true, "sents": [{"fr": "— Ce ne sont pas les mêmes, dit l’aiguilleur.", "zh": "这不是同一批人，扳道工说。", "t": [100, 4300]}, {"fr": "C’est un échange.", "zh": "这是交流。", "t": [4300, 5112]}]}, {"id": "ch22p11", "audio": true, "sents": [{"fr": "— Ils n’étaient pas contents, là où ils étaient ?", "zh": "他们对自己的住处不满意吗？", "t": [100, 3813]}]}, {"id": "ch22p12", "audio": true, "sents": [{"fr": "— On n’est jamais content là où l’on est, dit l’aiguilleur.", "zh": "身在何处，心常不满，扳道工说。", "t": [100, 3813]}]}, {"id": "ch22p13", "audio": true, "sents": [{"fr": "Et gronda le tonnerre d’un troisième rapide illuminé.", "zh": "雷霆般轰鸣，第三列快车灯火通明。", "t": [100, 2712]}]}, {"id": "ch22p14", "audio": true, "sents": [{"fr": "— Ils poursuivent les premiers voyageurs ?", "zh": "他们在追赶第一批旅客吗？", "t": [100, 3850]}, {"fr": "demanda le petit prince.", "zh": "小王子问道。", "t": [3850, 5125]}]}, {"id": "ch22p15", "audio": true, "sents": [{"fr": "— Ils ne poursuivent rien du tout, dit l’aiguilleur.", "zh": "他们根本不追逐什么，扳道工说。", "t": [100, 4550]}, {"fr": "Ils dorment là-dedans, ou bien ils bâillent.", "zh": "他们在车厢里安睡，或是哈欠连连。", "t": [4550, 7575]}, {"fr": "Les enfants seuls écrasent leur nez contre les vitres.", "zh": "孩子们独自将鼻尖抵在窗玻璃上。", "t": [7575, 10037]}]}, {"id": "ch22p16", "audio": true, "sents": [{"fr": "— Les enfants seuls savent ce qu’ils cherchent, fit le petit prince.", "zh": "孩子们独自知晓他们所寻何物，小王子说。", "t": [100, 5275]}, {"fr": "Ils perdent du temps pour une poupée de chiffons, et elle devient très importante, et si on la leur enlève, ils pleurent…", "zh": "他们把时间花在布娃娃身上，而她变得极其重要，要是有人把它夺走，他们就哭鼻子……", "t": [5275, 11287]}]}, {"id": "ch22p17", "audio": true, "sents": [{"fr": "— Ils ont de la chance, dit l’aiguilleur.", "zh": "他们是有福气的人，扳道工说。", "t": [100, 3200]}]}, {"id": "ch22p18", "audio": true, "sents": []}]}, {"id": "ch23", "title_fr": "Chapitre XXIII", "title_zh": "第 23 章", "paras": [{"id": "ch23p00", "audio": true, "sents": [{"fr": "— Bonjour, dit le petit prince.", "zh": "你好，小王子说。", "t": [100, 3074]}]}, {"id": "ch23p01", "audio": true, "sents": [{"fr": "— Bonjour, dit le marchand.", "zh": "你好，商人说。", "t": [100, 2776]}]}, {"id": "ch23p02", "audio": true, "sents": [{"fr": "C’était un marchand de pilules perfectionnées qui apaisent la soif.", "zh": "这是一位售卖止渴灵药的商人。", "t": [100, 4162]}, {"fr": "On en avale une par semaine et l’on n’éprouve plus le besoin de boire.", "zh": "每周吞下一颗，便不再感到口渴之需。", "t": [4162, 7338]}]}, {"id": "ch23p03", "audio": true, "sents": [{"fr": "— Pourquoi vends-tu ça ?", "zh": "“你为何卖这东西？”", "t": [100, 3112]}, {"fr": "dit le petit prince.", "zh": "小王子说。", "t": [3112, 4125]}]}, {"id": "ch23p04", "audio": true, "sents": [{"fr": "— C’est une grosse économie de temps, dit le marchand.", "zh": "这是节省大量时间，商人说。", "t": [100, 4662]}, {"fr": "Les experts ont fait des calculs.", "zh": "专家们已算过。", "t": [4662, 7300]}, {"fr": "On épargne cinquante-trois minutes par semaine.", "zh": "每周节省五十三分钟。", "t": [7300, 9513]}]}, {"id": "ch23p05", "audio": true, "sents": [{"fr": "— Et que fait-on des cinquante-trois minutes ?", "zh": "这五十三分钟如何使用？", "t": [100, 3538]}]}, {"id": "ch23p06", "audio": true, "sents": [{"fr": "— On en fait ce que l’on veut…", "zh": "人们做愿意做的事…", "t": [100, 2500]}]}, {"id": "ch23p07", "audio": true, "sents": [{"fr": "\"Moi, se dit le petit prince, si j’avais cinquante-trois minutes à dépenser, je marcherais tout doucement vers une fontaine…\"", "zh": "若我有五十三分钟可挥霍，我会悠然漫步向泉边走去……", "t": [100, 6425]}]}, {"id": "ch23p08", "audio": true, "sents": []}]}, {"id": "ch24", "title_fr": "Chapitre XXIV", "title_zh": "第 24 章", "paras": [{"id": "ch24p00", "audio": true, "sents": []}, {"id": "ch24p01", "audio": true, "sents": [{"fr": "Nous en étions au huitième jour de ma panne dans le désert, et j’avais écouté l’histoire du marchand en buvant la dernière goutte de ma provision d’eau :", "zh": "在沙漠中飞机抛锚的第八天，我听着商人的故事，喝完了最后一滴水。", "t": [100, 7838]}]}, {"id": "ch24p02", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "dis-je au petit prince, ils sont bien jolis, tes souvenirs, mais je n’ai pas encore réparé mon avion, je n’ai plus rien à boire, et je serais heureux, moi aussi, si je pouvais marcher tout doucement vers une fontaine !", "zh": "我对小王子说：“你的这些回忆挺美好的，但我还没修好我的飞机，我的水也喝完了，如果我能悠闲自在地向一泓泉水走过去，我也会很幸福快活的！”", "t": [3038, 15250]}]}, {"id": "ch24p03", "audio": true, "sents": [{"fr": "— Mon ami le renard, me dit-il…", "zh": "我的朋友狐狸对我说……", "t": [100, 3100]}]}, {"id": "ch24p04", "audio": true, "sents": [{"fr": "— Mon petit bonhomme, il ne s’agit plus du renard !", "zh": "我的孩子，现在不再是狐狸的事了！", "t": [100, 4375]}]}, {"id": "ch24p05", "audio": true, "sents": [{"fr": "— Pourquoi ?", "zh": "为什么？", "t": [100, 2462]}]}, {"id": "ch24p06", "audio": true, "sents": [{"fr": "— Parce qu’on va mourir de soif…", "zh": "只因我们即将渴死……", "t": [100, 2712]}]}, {"id": "ch24p07", "audio": true, "sents": [{"fr": "Il ne comprit pas mon raisonnement, il me répondit :", "zh": "他不懂我的道理，便回答道：", "t": [100, 3388]}]}, {"id": "ch24p08", "audio": true, "sents": [{"fr": "— C’est bien d’avoir eu un ami, même si l’on va mourir.", "zh": "有朋友真好，哪怕命在旦夕。", "t": [100, 4900]}, {"fr": "Moi, je suis bien content d’avoir eu un ami renard…", "zh": "我很高兴自己有一位狐狸朋友……", "t": [4900, 7725]}]}, {"id": "ch24p09", "audio": true, "sents": [{"fr": "Il ne mesure pas le danger, me dis-je.", "zh": "他未曾衡量过危险。", "t": [100, 3188]}, {"fr": "Il n’a jamais ni faim ni soif.", "zh": "他从未饥饿过，也从未口渴过。", "t": [3188, 5625]}, {"fr": "Un peu de soleil lui suffit…", "zh": "一点阳光便足矣……", "t": [5625, 7138]}]}, {"id": "ch24p10", "audio": true, "sents": [{"fr": "Mais il me regarda et répondit à ma pensée :", "zh": "但它凝视着我，回应了我的思绪。", "t": [100, 3225]}]}, {"id": "ch24p11", "audio": true, "sents": [{"fr": "— J’ai soif aussi…", "zh": "我也渴……", "t": [100, 2262]}, {"fr": "cherchons un puits…", "zh": "寻找一口井…", "t": [2262, 3125]}]}, {"id": "ch24p12", "audio": true, "sents": [{"fr": "J’eus un geste de lassitude : il est absurde de chercher un puits, au hasard, dans l’immensité du désert.", "zh": "在沙漠的浩瀚中随意寻找一口井，岂非荒唐至极？", "t": [100, 7538]}, {"fr": "Cependant nous nous mîmes en marche.", "zh": "然而，我们还是出发了。", "t": [7538, 9112]}]}, {"id": "ch24p13", "audio": true, "sents": [{"fr": "Quand nous eûmes marché, des heures, en silence, la nuit tomba, et les étoiles commencèrent de s’éclairer.", "zh": "我们默默行走，夜幕降临，星辰渐次点亮。", "t": [100, 7000]}, {"fr": "Je les apercevais comme en rêve, ayant un peu de fièvre, à cause de ma soif.", "zh": "我因干渴发烧，视星星如梦中之物。", "t": [7000, 12175]}, {"fr": "Les mots du petit prince dansaient dans ma mémoire :", "zh": "小王子的言语在我记忆中翩翩起舞。", "t": [12175, 15000]}]}, {"id": "ch24p14", "audio": true, "sents": [{"fr": "— Tu as donc soif, toi aussi ?", "zh": "你也渴了，对吧？", "t": [100, 4650]}, {"fr": "lui demandai-je.", "zh": "我问他。", "t": [4650, 5612]}]}, {"id": "ch24p15", "audio": true, "sents": [{"fr": "Mais il ne répondit pas à ma question.", "zh": "他并未回答我的问题。", "t": [100, 2812]}, {"fr": "Il me dit simplement :", "zh": "他只是简单地告诉我：", "t": [2812, 4626]}]}, {"id": "ch24p16", "audio": true, "sents": [{"fr": "— L’eau peut aussi être bonne pour le cœur…", "zh": "水对心也有益……", "t": [100, 3087]}]}, {"id": "ch24p17", "audio": true, "sents": [{"fr": "Je ne compris pas sa réponse mais je me tus…", "zh": "我不懂他的回答，却默默承受……", "t": [100, 3125]}, {"fr": "Je savais bien qu’il ne fallait pas l’interroger.", "zh": "我深知不该问他。", "t": [3125, 5400]}]}, {"id": "ch24p18", "audio": true, "sents": [{"fr": "Il était fatigué.", "zh": "他疲惫不堪。", "t": [100, 2000]}, {"fr": "Il s’assit.", "zh": "他坐下了。", "t": [2000, 3625]}, {"fr": "Je m’assis auprès de lui.", "zh": "我坐在他身边。", "t": [3625, 5912]}, {"fr": "Et, après un silence, il dit encore :", "zh": "静默片刻，他又说：", "t": [5912, 8812]}]}, {"id": "ch24p19", "audio": true, "sents": [{"fr": "— Les étoiles sont belles, à cause d’une fleur que l’on ne voit pas…", "zh": "星星之所以美丽，是因为其中藏着一朵看不见的花。", "t": [100, 4187]}]}, {"id": "ch24p20", "audio": true, "sents": [{"fr": "Je répondis \"bien sûr\" et je regardai, sans parler, les plis du sable sous la lune.", "zh": "当然，我默默凝视着月光下沙丘的皱褶。", "t": [100, 4975]}]}, {"id": "ch24p21", "audio": true, "sents": [{"fr": "— Le désert est beau, ajouta-t-il…", "zh": "沙漠真美，他补充道。", "t": [100, 3024]}]}, {"id": "ch24p22", "audio": true, "sents": [{"fr": "Et c’était vrai.", "zh": "这确实如此。", "t": [100, 1688]}, {"fr": "J’ai toujours aimé le désert.", "zh": "我始终热爱沙漠。", "t": [1688, 4150]}, {"fr": "On s’assoit sur une dune de sable.", "zh": "我们坐在沙丘上。", "t": [4150, 6700]}, {"fr": "On ne voit rien.", "zh": "什么也看不见。", "t": [6700, 8438]}, {"fr": "On n’entend rien.", "zh": "一片寂静。", "t": [8438, 10162]}, {"fr": "Et cependant quelque chose rayonne en silence…", "zh": "然而，却有什么在默默发光……", "t": [10162, 12376]}]}, {"id": "ch24p23", "audio": true, "sents": [{"fr": "— Ce qui embellit le désert, dit le petit prince, c’est qu’il cache un puits quelque part…", "zh": "沙漠之所以美丽，是因为它某处隐藏着一口井。", "t": [100, 5850]}]}, {"id": "ch24p24", "audio": true, "sents": [{"fr": "Je fus surpris de comprendre soudain ce mystérieux rayonnement du sable.", "zh": "我忽然惊觉沙丘那神秘的闪烁。", "t": [100, 4612]}, {"fr": "Lorsque j’étais petit garçon j’habitais une maison ancienne, et la légende racontait qu’un trésor y était enfoui.", "zh": "我年幼时住在一座古老房屋里，传说那里埋藏着一笔宝藏。", "t": [4612, 11050]}, {"fr": "Bien sûr, jamais personne n’a su le découvrir, ni peut-être même ne l’a cherché.", "zh": "当然，没有人知道它的所在，也许甚至没有人去寻找过。", "t": [11050, 16425]}, {"fr": "Mais il enchantait toute cette maison.", "zh": "但这间屋子里充满了魔法。", "t": [16425, 19012]}, {"fr": "Ma maison cachait un secret au fond de son cœur…", "zh": "我的房子在心底深藏着一个秘密……", "t": [19012, 21387]}]}, {"id": "ch24p25", "audio": true, "sents": [{"fr": "— Oui, dis-je au petit prince, qu’il s’agisse de la maison, des étoiles ou du désert, ce qui fait leur beauté est invisible !", "zh": "是的，我对小王子说：“不管是房子、星星还是沙漠，赋予它们美丽的是那些肉眼看不见的东西。”", "t": [100, 8424]}]}, {"id": "ch24p26", "audio": true, "sents": [{"fr": "— Je suis content, dit-il, que tu sois d’accord avec mon renard.", "zh": "我很高兴，他说，你同意我的狐狸的看法。", "t": [100, 4800]}]}, {"id": "ch24p27", "audio": true, "sents": [{"fr": "Comme le petit prince s’endormait, je le pris dans mes bras, et me remis en route.", "zh": "小王子入睡了，我把他抱在怀里，继续前行。", "t": [100, 5175]}, {"fr": "J’étais ému.", "zh": "我深受感动。", "t": [5175, 6900]}, {"fr": "Il me semblait porter un trésor fragile.", "zh": "我怀抱着一件脆弱的宝藏。", "t": [6900, 9850]}, {"fr": "Il me semblait même qu’il n’y eût rien de plus fragile sur la Terre.", "zh": "似乎在这片土地上，再无什么比他更脆弱的了。", "t": [9850, 13838]}, {"fr": "Je regardais, à la lumière de la lune, ce front pâle, ces yeux clos, ces mèches de cheveux qui tremblaient au vent, et je me disais : ce que je vois là n’est qu’une écorce.", "zh": "我凝视着月光下他苍白的额头、紧闭的双眼、随风轻轻颤动的发丝，心中想道：我所看到的，不过是一层外壳。", "t": [13838, 24575]}, {"fr": "Le plus important est invisible…", "zh": "最重要的，是看不见的。", "t": [24575, 26388]}]}, {"id": "ch24p28", "audio": true, "sents": [{"fr": "Comme ses lèvres entr’ouvertes ébauchaient un demi-sourire je me dis encore : \"Ce qui m’émeut si fort de ce petit prince endormi, c’est sa fidélité pour une fleur, c’est l’image d’une rose qui rayonne en lui comme la flamme d’une lampe, même quand il dort…\" Et je le devinai plus fragile encore.", "zh": "那睡着的小王子，令我深深感动的，是他对于一朵花的忠诚，是那朵玫瑰在他心中如同灯焰般闪耀，即使在他沉睡之时……我愈发觉得他脆弱。", "t": [100, 20700]}, {"fr": "Il faut bien protéger les lampes : un coup de vent peut les éteindre…", "zh": "灯是需要我们小心保护的，一阵风就能吹灭它们。", "t": [20700, 21200]}]}, {"id": "ch24p29", "audio": true, "sents": [{"fr": "Et, marchant ainsi, je découvris le puits au lever du jour.", "zh": "在晨曦中，我发现了那口井。", "t": [100, 3474]}]}, {"id": "ch24p30", "audio": true, "sents": []}]}, {"id": "ch25", "title_fr": "Chapitre XXV", "title_zh": "第 25 章", "paras": [{"id": "ch25p00", "audio": true, "sents": []}, {"id": "ch25p01", "audio": true, "sents": [{"fr": "— Les hommes, dit le petit prince, ils s’enfournent dans les rapides, mais ils ne savent plus ce qu’ils cherchent.", "zh": "人们啊，小王子说，他们匆匆忙忙地钻进快车，却不再知道他们在寻找什么。", "t": [100, 7488]}, {"fr": "Alors ils s’agitent et tournent en rond…", "zh": "于是他们慌乱地团团转……", "t": [7488, 9162]}]}, {"id": "ch25p02", "audio": true, "sents": [{"fr": "Et il ajouta :", "zh": "他又补充道：", "t": [100, 1738]}]}, {"id": "ch25p03", "audio": true, "sents": [{"fr": "— Ce n’est pas la peine…", "zh": "这又何苦呢……", "t": [100, 2125]}]}, {"id": "ch25p04", "audio": true, "sents": [{"fr": "Le puits que nous avions atteint ne ressemblait pas aux puits sahariens.", "zh": "这井与撒哈拉沙漠的井大不相同。", "t": [100, 3888]}, {"fr": "Les puits sahariens sont de simples trous creusés dans le sable.", "zh": "撒哈拉沙漠的井只是沙中挖出的洞。", "t": [3888, 7662]}, {"fr": "Celui-là ressemblait à un puits de village.", "zh": "那口井宛如村中的井。", "t": [7662, 10775]}, {"fr": "Mais il n’y avait là aucun village, et je croyais rêver.", "zh": "但这里并无村落，我仿佛在做梦。", "t": [10775, 13788]}]}, {"id": "ch25p05", "audio": true, "sents": [{"fr": "— C’est étrange, dis-je au petit prince, tout est prêt : la poulie, le seau et la corde…", "zh": "这井一切齐备：辘轳、水桶、绳子……", "t": [100, 6788]}]}, {"id": "ch25p06", "audio": true, "sents": [{"fr": "Il rit, toucha la corde, fit jouer la poulie.", "zh": "他轻触绳索，让辘轳转动起来。", "t": [100, 3738]}, {"fr": "Et la poulie gémit comme gémit une vieille girouette quand le vent a longtemps dormi.", "zh": "辘轳哀鸣，宛如老风信鸡在长眠的风中低吟。", "t": [3738, 7424]}]}, {"id": "ch25p07", "audio": true, "sents": [{"fr": "— Tu entends, dit le petit prince, nous réveillons ce puits et il chante…", "zh": "你听，小王子说，我们唤醒了这口井，它在歌唱。", "t": [100, 5025]}]}, {"id": "ch25p08", "audio": true, "sents": [{"fr": "Je ne voulais pas qu’il fît un effort :", "zh": "我不愿他费劲。", "t": [100, 2450]}]}, {"id": "ch25p09", "audio": true, "sents": [{"fr": "— Laisse-moi faire, lui dis-je, c’est trop lourd pour toi.", "zh": "让我来干吧，这对你来说太沉重了。", "t": [100, 4213]}]}, {"id": "ch25p10", "audio": true, "sents": [{"fr": "Lentement je hissai le seau jusqu’à la margelle.", "zh": "缓缓提起水桶至井沿。", "t": [100, 3388]}, {"fr": "Je l’y installai bien d’aplomb.", "zh": "我把它稳稳地放正。", "t": [3388, 5850]}, {"fr": "Dans mes oreilles durait le chant de la poulie et, dans l’eau qui tremblait encore, je voyais trembler le soleil.", "zh": "耳畔仍回荡着辘轳的歌声，荡漾的井水中，太阳也在轻轻颤动。", "t": [5850, 11213]}]}, {"id": "ch25p11", "audio": true, "sents": [{"fr": "— J’ai soif de cette eau-là, dit le petit prince, donne-moi à boire…", "zh": "小王子说：“我渴望的就是这样的水，给我喝吧……”", "t": [100, 4838]}]}, {"id": "ch25p12", "audio": true, "sents": [{"fr": "Et je compris ce qu’il avait cherché !", "zh": "我明白了他在寻找什么。", "t": [100, 2538]}]}, {"id": "ch25p13", "audio": true, "sents": [{"fr": "Je soulevai le seau jusqu’à ses lèvres.", "zh": "我举起了水桶至他的唇边。", "t": [100, 2888]}, {"fr": "Il but, les yeux fermés.", "zh": "闭目畅饮。", "t": [2888, 5288]}, {"fr": "C’était doux comme une fête.", "zh": "水甜得有如佳节。", "t": [5288, 7512]}, {"fr": "Cette eau était bien autre chose qu’un aliment.", "zh": "这水远非单纯的饮品。", "t": [7512, 10488]}, {"fr": "Elle était née de la marche sous les étoiles, du chant de la poulie, de l’effort de mes bras.", "zh": "它诞生于星光下的跋涉，辘轳的歌声中，我双臂的努力之下。", "t": [10488, 15938]}, {"fr": "Elle était bonne pour le cœur, comme un cadeau.", "zh": "它如礼物般温暖心灵。", "t": [15938, 19112]}, {"fr": "Lorsque j’étais petit garçon, la lumière de l’arbre de Noël, la musique de la messe de minuit, la douceur des sourires faisaient ainsi tout le rayonnement du cadeau de Noël que je recevais.", "zh": "儿时，圣诞树的灯火、子夜弥撒的旋律、甜蜜的微笑，构成了我收到的圣诞礼物的全部光辉。", "t": [19112, 28500]}]}, {"id": "ch25p14", "audio": true, "sents": [{"fr": "— Les hommes de chez toi, dit le petit prince, cultivent cinq mille roses dans un même jardin…", "zh": "你们这儿的人，小王子说，在同一个花园里种植了五千朵玫瑰……", "t": [100, 6162]}, {"fr": "et ils n’y trouvent pas ce qu’ils cherchent.", "zh": "他们找不到他们所寻找的东西。", "t": [6162, 7600]}]}, {"id": "ch25p15", "audio": true, "sents": [{"fr": "— Ils ne le trouvent pas, répondis-je…", "zh": "他们找不到，我答道。", "t": [100, 2974]}]}, {"id": "ch25p16", "audio": true, "sents": [{"fr": "— Et cependant ce qu’ils cherchent pourrait être trouvé dans une seule rose ou un peu d’eau…", "zh": "然而他们所寻找的或许只在一朵玫瑰或一点水中。", "t": [100, 4825]}]}, {"id": "ch25p17", "audio": true, "sents": [{"fr": "— Bien sûr, répondis-je.", "zh": "当然，我答道。", "t": [100, 2850]}]}, {"id": "ch25p18", "audio": true, "sents": [{"fr": "Et le petit prince ajouta :", "zh": "小王子又补充道：", "t": [100, 2274]}]}, {"id": "ch25p19", "audio": true, "sents": [{"fr": "— Mais les yeux sont aveugles.", "zh": "但眼睛是盲的。", "t": [100, 3362]}, {"fr": "Il faut chercher avec le cœur.", "zh": "用心去寻找。", "t": [3362, 4900]}]}, {"id": "ch25p20", "audio": true, "sents": [{"fr": "J’avais bu.", "zh": "我已饮下。", "t": [100, 1688]}, {"fr": "Je respirais bien.", "zh": "呼吸顺畅了。", "t": [1688, 3688]}, {"fr": "Le sable, au lever du jour, est couleur de miel.", "zh": "晨曦中的沙土，色泽如蜜。", "t": [3688, 7562]}, {"fr": "J’étais heureux aussi de cette couleur de miel.", "zh": "我也为这蜜色般的沙土感到欢喜。", "t": [7562, 10725]}, {"fr": "Pourquoi fallait-il que j’eusse de la peine…", "zh": "为何我竟如此艰辛…", "t": [10725, 12712]}]}, {"id": "ch25p21", "audio": true, "sents": [{"fr": "— Il faut que tu tiennes ta promesse, me dit doucement le petit prince, qui, de nouveau, s’était assis auprès de moi.", "zh": "小王子轻声对我说：“你可要信守诺言啊。”他又重新坐在我身边。", "t": [100, 7450]}]}, {"id": "ch25p22", "audio": true, "sents": [{"fr": "— Quelle promesse ?", "zh": "你许下的什么诺言？", "t": [100, 2563]}]}, {"id": "ch25p23", "audio": true, "sents": [{"fr": "— Tu sais…", "zh": "你知道……", "t": [100, 1888]}, {"fr": "une muselière pour mon mouton…", "zh": "为我的绵羊画一个口罩…", "t": [1888, 3425]}, {"fr": "je suis responsable de cette fleur !", "zh": "我为这朵花负责。", "t": [3425, 5724]}]}, {"id": "ch25p24", "audio": true, "sents": [{"fr": "Je sortis de ma poche mes ébauches de dessin.", "zh": "我从口袋里掏出我的草图。", "t": [100, 3238]}, {"fr": "Le petit prince les aperçut et dit en riant :", "zh": "小王子瞥见他们，笑着说道：", "t": [3238, 6224]}]}, {"id": "ch25p25", "audio": true, "sents": [{"fr": "— Tes baobabs, ils ressemblent un peu à des choux…", "zh": "你的猴面包树，它们有点像卷心菜…", "t": [100, 3500]}]}, {"id": "ch25p26", "audio": true, "sents": [{"fr": "— Oh !", "zh": "哦！", "t": [100, 2176]}]}, {"id": "ch25p27", "audio": true, "sents": [{"fr": "Moi qui était si fier des baobabs !", "zh": "我那自鸣得意的猴面包树！", "t": [100, 2437]}]}, {"id": "ch25p28", "audio": true, "sents": [{"fr": "— Ton renard…", "zh": "你的狐狸…", "t": [100, 2050]}, {"fr": "ses oreilles…", "zh": "它的耳朵…", "t": [2050, 2925]}, {"fr": "elles ressemblent un peu à des cornes…", "zh": "它们的耳朵有点像角。", "t": [2925, 4550]}, {"fr": "et elles sont trop longues !", "zh": "它的耳朵太长了！", "t": [4550, 6188]}]}, {"id": "ch25p29", "audio": true, "sents": [{"fr": "Et il rit encore.", "zh": "他又笑了。", "t": [100, 1074]}]}, {"id": "ch25p30", "audio": true, "sents": [{"fr": "— Tu es injuste, petit bonhomme, je ne savais rien dessiner que les boas fermés et les boas ouverts.", "zh": "你这个小家伙，不公平，我只会画闭嘴的和开口的蟒蛇。", "t": [100, 6562]}]}, {"id": "ch25p31", "audio": true, "sents": [{"fr": "— Oh !", "zh": "哦！", "t": [100, 3038]}, {"fr": "ça ira, dit-il, les enfants savent.", "zh": "孩子们懂得，他说。", "t": [3038, 5675]}]}, {"id": "ch25p32", "audio": true, "sents": [{"fr": "Je crayonnai donc une muselière.", "zh": "我画了一个口罩。", "t": [100, 2888]}, {"fr": "Et j’eus le cœur serré en la lui donnant :", "zh": "我的心在交付给他时紧缩了。", "t": [2888, 5375]}]}, {"id": "ch25p33", "audio": true, "sents": [{"fr": "— Tu as des projets que j’ignore…", "zh": "你有着我不知道的计划……", "t": [100, 2725]}]}, {"id": "ch25p34", "audio": true, "sents": [{"fr": "Mais il ne me répondit pas.", "zh": "他并未回答。", "t": [100, 2200]}, {"fr": "Il me dit :", "zh": "他说：", "t": [2200, 3550]}]}, {"id": "ch25p35", "audio": true, "sents": [{"fr": "— Tu sais, ma chute sur la Terre…", "zh": "你知道，我的坠落在这片土地上……", "t": [100, 3325]}, {"fr": "c’en sera demain l’anniversaire…", "zh": "明天就是周年纪念日了。", "t": [3325, 4900]}]}, {"id": "ch25p36", "audio": true, "sents": [{"fr": "Puis, après un silence il dit encore :", "zh": "然后，沉默片刻，他又说：", "t": [100, 2813]}]}, {"id": "ch25p37", "audio": true, "sents": [{"fr": "— J’étais tombé tout près d’ici…", "zh": "我坠落得离此地很近…", "t": [100, 2663]}]}, {"id": "ch25p38", "audio": true, "sents": [{"fr": "Et il rougit.", "zh": "他脸红了。", "t": [100, 900]}]}, {"id": "ch25p39", "audio": true, "sents": [{"fr": "Et de nouveau, sans comprendre pourquoi, j’éprouvai un chagrin bizarre.", "zh": "又不知为何，我感到一种奇怪的忧伤。", "t": [100, 5038]}, {"fr": "Cependant une question me vint :", "zh": "然而，一个疑问涌上心头：", "t": [5038, 7263]}]}, {"id": "ch25p40", "audio": true, "sents": [{"fr": "— Alors ce n’est pas par hasard que, le matin où je t’ai connu, il y a huit jours, tu te promenais comme ça, tout seul, à mille milles de toutes les régions habitées !", "zh": "那么，八天前我认识你的那个早晨，你独自一人在远离所有有人居住的地区的地方散步，这并不是偶然的！", "t": [100, 10688]}, {"fr": "Tu retournais vers le point de ta chute ?", "zh": "你回到坠机地点了吗？", "t": [10688, 13138]}]}, {"id": "ch25p41", "audio": true, "sents": [{"fr": "Le petit prince rougit encore.", "zh": "小王子又红了脸。", "t": [100, 1788]}]}, {"id": "ch25p42", "audio": true, "sents": [{"fr": "Et j’ajoutai, en hésitant :", "zh": "我接着说，犹豫着：", "t": [100, 2538]}]}, {"id": "ch25p43", "audio": true, "sents": [{"fr": "— A cause, peut-être, de l’anniversaire ?…", "zh": "或许是为了纪念这个周年？", "t": [100, 3987]}]}, {"id": "ch25p44", "audio": true, "sents": [{"fr": "Le petit prince rougit de nouveau.", "zh": "小王子再次脸红。", "t": [100, 2675]}, {"fr": "Il ne répondait jamais aux questions, mais, quand on rougit, ça signifie \"oui\", n’est-ce pas ?", "zh": "他从不回答问题，但人脸一红，就意味着“是”，不是吗？", "t": [2675, 8400]}]}, {"id": "ch25p45", "audio": true, "sents": [{"fr": "— Ah !", "zh": "哦！", "t": [100, 3038]}, {"fr": "lui dis-je, j’ai peur…", "zh": "我说：“我害怕……”", "t": [3038, 4587]}]}, {"id": "ch25p46", "audio": true, "sents": [{"fr": "Mais il me répondit :", "zh": "但他回答我说：", "t": [100, 1988]}]}, {"id": "ch25p47", "audio": true, "sents": [{"fr": "— Tu dois maintenant travailler.", "zh": "你现在该工作了。", "t": [100, 3500]}, {"fr": "Tu dois repartir vers ta machine.", "zh": "你该回到你的机器旁去了。", "t": [3500, 6250]}, {"fr": "Je t’attends ici.", "zh": "我在这里等你。", "t": [6250, 8250]}, {"fr": "Reviens demain soir…", "zh": "明晚再来……", "t": [8250, 9463]}]}, {"id": "ch25p48", "audio": true, "sents": [{"fr": "Mais je n’étais pas rassuré.", "zh": "但我并不安心。", "t": [100, 2312]}, {"fr": "Je me souvenais du renard.", "zh": "我记得那狐狸。", "t": [2312, 4638]}, {"fr": "On risque de pleurer un peu si l’on s’est laissé apprivoiser…", "zh": "若曾让人驯养，难免会泪流满面。", "t": [4638, 7312]}]}, {"id": "ch25p49", "audio": true, "sents": []}, {"id": "ch25p50", "audio": true, "sents": []}]}, {"id": "ch26", "title_fr": "Chapitre XXVI", "title_zh": "第 26 章", "paras": [{"id": "ch26p00", "audio": true, "sents": [{"fr": "Il y avait, à côté du puits, une ruine de vieux mur de pierre.", "zh": "井边，有一段古老的石墙残垣。", "t": [100, 4588]}, {"fr": "Lorsque je revins de mon travail, le lendemain soir, j’aperçus de loin mon petit prince assis là-haut, les jambes pendantes.", "zh": "次日黄昏，我劳作归来，远远望见小王子坐在那上面，双腿悬空。", "t": [4588, 12175]}, {"fr": "Et je l’entendis qui parlait :", "zh": "我听见他在说话：", "t": [12175, 14312]}]}, {"id": "ch26p01", "audio": true, "sents": [{"fr": "— Tu ne t’en souviens donc pas ?", "zh": "你难道不记得了吗？", "t": [100, 3450]}, {"fr": "disait-il.", "zh": "他道。", "t": [3450, 5025]}, {"fr": "Ce n’est pas tout à fait ici !", "zh": "这并非全然在此！", "t": [5025, 7012]}]}, {"id": "ch26p02", "audio": true, "sents": [{"fr": "Une autre voix lui répondit sans doute, puisqu’il répliqua :", "zh": "另一个声音或许回应了他，因为他反驳道：", "t": [100, 3875]}]}, {"id": "ch26p03", "audio": true, "sents": [{"fr": "— Si !", "zh": "是的！", "t": [100, 3025]}, {"fr": "Si !", "zh": "是的！", "t": [3025, 4988]}, {"fr": "c’est bien le jour, mais ce n’est pas ici l’endroit…", "zh": "这正是那天，但不是这个地方…", "t": [4988, 7650]}]}, {"id": "ch26p04", "audio": true, "sents": [{"fr": "Je poursuivis ma marche vers le mur.", "zh": "我继续朝墙走去。", "t": [100, 2912]}, {"fr": "Je ne voyais ni n’entendais toujours personne.", "zh": "我始终未见亦未闻有人。", "t": [2912, 6062]}, {"fr": "Pourtant le petit prince répliqua de nouveau :", "zh": "小王子又反驳道：", "t": [6062, 8924]}]}, {"id": "ch26p05", "audio": true, "sents": [{"fr": "— …", "zh": "你难道不记得了吗？", "t": [100, 1850]}, {"fr": "Bien sûr.", "zh": "当然。", "t": [1850, 3438]}, {"fr": "Tu verras où commence ma trace dans le sable.", "zh": "你将看到我的足迹在沙地上起始之处。", "t": [3438, 6550]}, {"fr": "Tu n’as qu’a m’y attendre.", "zh": "你只需在此等候我。", "t": [6550, 9937]}, {"fr": "J’y serai cette nuit.", "zh": "今夜我会在此等候。", "t": [9937, 10437]}]}, {"id": "ch26p06", "audio": true, "sents": [{"fr": "J’étais à vingt mètres du mur et je ne voyais toujours rien.", "zh": "我离墙只有二十米，却依旧一无所见。", "t": [100, 2824]}]}, {"id": "ch26p07", "audio": true, "sents": [{"fr": "Le petit prince dit encore, après un silence :", "zh": "小王子沉默片刻后又说：", "t": [100, 3325]}]}, {"id": "ch26p08", "audio": true, "sents": [{"fr": "— Tu as du bon venin ?", "zh": "你有毒液吗？", "t": [100, 3825]}, {"fr": "Tu es sûr de ne pas me faire souffrir longtemps ?", "zh": "你能否肯定不会让我痛苦很久？", "t": [3825, 6687]}]}, {"id": "ch26p09", "audio": true, "sents": [{"fr": "Je fis halte, le cœur serré, mais je ne comprenais toujours pas.", "zh": "我停下脚步，心揪成一团，却依旧不解其意。", "t": [100, 3663]}]}, {"id": "ch26p10", "audio": true, "sents": [{"fr": "— Maintenant va-t’en, dit-il…", "zh": "现在你走吧，他说。", "t": [100, 2838]}, {"fr": "je veux redescendre !", "zh": "我想要下去！", "t": [2838, 4400]}]}, {"id": "ch26p11", "audio": true, "sents": [{"fr": "Alors j’abaissai moi-même les yeux vers le pied du mur, et je fis un bond !", "zh": "于是，我低头看向墙脚，纵身一跃！", "t": [100, 5075]}, {"fr": "Il était là, dressé vers le petit prince, un de ces serpents jaunes qui vous exécutent en trente secondes.", "zh": "一条黄蛇正昂首对着小王子，那是种能让你三十秒内丧命的毒蛇。", "t": [5075, 11362]}, {"fr": "Tout en fouillant ma poche pour en tirer mon revolver, je pris le pas de course, mais, au bruit que je fis, le serpent se laissa doucement couler dans le sable, comme un jet d’eau qui meurt, et, sans trop se presser, se faufila entre les pierres avec un léger bruit de métal.", "zh": "我一边在口袋里掏手枪，一边快步冲过去，但那蛇听到我的脚步声，便像一柱断水般缓缓地钻进沙里，不慌不忙地穿梭于石缝之间，发出轻微的金属声响。", "t": [11362, 25713]}]}, {"id": "ch26p12", "audio": true, "sents": [{"fr": "Je parvins au mur juste à temps pour y recevoir dans les bras mon petit bonhomme de prince, pâle comme la neige.", "zh": "我及时赶到墙边，将我的小王子抱在怀里，他的脸色苍白如雪。", "t": [100, 5550]}]}, {"id": "ch26p13", "audio": true, "sents": [{"fr": "— Quelle est cette histoire-là !", "zh": "这究竟是怎么回事？", "t": [100, 3875]}, {"fr": "Tu parles maintenant avec les serpents !", "zh": "你如今能与蛇交谈了！", "t": [3875, 6363]}]}, {"id": "ch26p14", "audio": true, "sents": [{"fr": "J’avais défait son éternel cache-nez d’or.", "zh": "我揭开了他永恒的金色口罩。", "t": [100, 3138]}, {"fr": "Je lui avais mouillé les tempes et l’avais fait boire.", "zh": "我湿润了他的太阳穴，并让他饮水。", "t": [3138, 6300]}, {"fr": "Et maintenant je n’osais plus rien lui demander.", "zh": "现在我再也不敢问他什么了。", "t": [6300, 9412]}, {"fr": "Il me regarda gravement et m’entoura le cou de ses bras.", "zh": "他严肃地望着我，用双臂搂住我的脖子。", "t": [9412, 13000]}, {"fr": "Je sentais battre son cœur comme celui d’un oiseau qui meurt, quand on l’a tiré à la carabine.", "zh": "我感觉到他的心在狂跳，如同被枪击中濒临死亡的小鸟。", "t": [13000, 18700]}, {"fr": "Il me dit :", "zh": "他说：", "t": [18700, 20050]}]}, {"id": "ch26p15", "audio": true, "sents": [{"fr": "— Je suis content que tu aies trouvé ce qui manquait à ta machine.", "zh": "我为你能找到飞机的毛病而高兴。", "t": [100, 4925]}, {"fr": "Tu vas pouvoir rentrer chez toi…", "zh": "你将能回家。", "t": [4925, 6474]}]}, {"id": "ch26p16", "audio": true, "sents": [{"fr": "— Comment sais-tu !", "zh": "你怎会知道！", "t": [100, 2613]}]}, {"id": "ch26p17", "audio": true, "sents": [{"fr": "Je venais justement lui annoncer que, contre toute espérance, j’avais réussi mon travail !", "zh": "我正要告诉他，出乎意料地，我竟然修好了我的飞机！", "t": [100, 5550]}]}, {"id": "ch26p18", "audio": true, "sents": [{"fr": "Il ne répondit rien à ma question, mais il ajouta :", "zh": "他未对我的问题作答，却补充道：", "t": [100, 3687]}]}, {"id": "ch26p19", "audio": true, "sents": [{"fr": "— Moi aussi, aujourd’hui, je rentre chez moi…", "zh": "今天，我也将回家…", "t": [100, 3763]}]}, {"id": "ch26p20", "audio": true, "sents": [{"fr": "Puis, mélancolique :", "zh": "然后，带着一丝忧郁：", "t": [100, 2150]}]}, {"id": "ch26p21", "audio": true, "sents": [{"fr": "— C’est bien plus loin…", "zh": "这还远不止这些……", "t": [100, 2312]}, {"fr": "c’est bien plus difficile…", "zh": "这远比想象中要难…", "t": [2312, 3600]}]}, {"id": "ch26p22", "audio": true, "sents": [{"fr": "Je sentais bien qu’il se passait quelque chose d’extraordinaire.", "zh": "我深知，必有非凡之事发生。", "t": [100, 4138]}, {"fr": "Je le serrais dans les bras comme un petit enfant, et cependant il me semblait qu’il coulait verticalement dans un abîme sans que je pusse rien pour le retenir…", "zh": "我把他紧紧抱在怀里，就像抱一个小孩，然而他却似乎垂直地坠入一个深渊，而我却无法拉住他……", "t": [4138, 11413]}]}, {"id": "ch26p23", "audio": true, "sents": [{"fr": "Il avait le regard sérieux, perdu très loin :", "zh": "他目光严肃，迷失在遥远之地：", "t": [100, 3263]}]}, {"id": "ch26p24", "audio": true, "sents": [{"fr": "— J’ai ton mouton.", "zh": "我有一只绵羊。", "t": [100, 2925]}, {"fr": "Et j’ai la caisse pour le mouton.", "zh": "我还有装绵羊的箱子。", "t": [2925, 5225]}, {"fr": "Et j’ai la muselière…", "zh": "我戴着口罩……", "t": [5225, 6412]}]}, {"id": "ch26p25", "audio": true, "sents": [{"fr": "Et il sourit avec mélancolie.", "zh": "带着一丝忧郁地微笑。", "t": [100, 1725]}]}, {"id": "ch26p26", "audio": true, "sents": [{"fr": "J’attendis longtemps.", "zh": "我等待了许久。", "t": [100, 2025]}, {"fr": "Je sentais qu’il se réchauffait peu à peu :", "zh": "我感觉到他身体逐渐回暖。", "t": [2025, 4763]}]}, {"id": "ch26p27", "audio": true, "sents": [{"fr": "— Petit bonhomme, tu as eu peur…", "zh": "小朋友，你害怕了……", "t": [100, 2987]}]}, {"id": "ch26p28", "audio": true, "sents": [{"fr": "Il avait eu peur, bien sûr !", "zh": "他当然害怕了！", "t": [100, 3300]}, {"fr": "Mais il rit doucement :", "zh": "他轻轻地笑了。", "t": [3300, 5100]}]}, {"id": "ch26p29", "audio": true, "sents": [{"fr": "— J’aurai bien plus peur ce soir…", "zh": "今晚我会更害怕……", "t": [100, 2763]}]}, {"id": "ch26p30", "audio": true, "sents": [{"fr": "De nouveau je me sentis glacé par le sentiment de l’irréparable.", "zh": "我又一次被无法挽回的悲伤感所笼罩。", "t": [100, 4212]}, {"fr": "Et je compris que je ne supportais pas l’idée de ne plus jamais entendre ce rire.", "zh": "我明白我无法忍受永远听不到这笑声的想法。", "t": [4212, 8788]}, {"fr": "C’était pour moi comme une fontaine dans le désert.", "zh": "如同沙漠中的一口井。", "t": [8788, 11187]}]}, {"id": "ch26p31", "audio": true, "sents": [{"fr": "— Petit bonhomme, je veux encore t’entendre rire…", "zh": "小朋友，我还想再听到你的笑声……", "t": [100, 3713]}]}, {"id": "ch26p32", "audio": true, "sents": [{"fr": "Mais il me dit :", "zh": "但他对我说：", "t": [100, 1650]}]}, {"id": "ch26p33", "audio": true, "sents": [{"fr": "— Cette nuit, ça fera un an.", "zh": "今夜，我将满周年。", "t": [100, 3775]}, {"fr": "Mon étoile se trouvera juste au-dessus de l’endroit où je suis tombé l’année dernière…", "zh": "我的星星将正上方于我去年坠落之处。", "t": [3775, 7800]}]}, {"id": "ch26p34", "audio": true, "sents": [{"fr": "— Petit bonhomme, n’est-ce pas que c’est un mauvais rêve cette histoire de serpent et de rendez-vous et d’étoile…", "zh": "这蛇呀、约会呀、星星的故事，莫非都是一场噩梦？", "t": [100, 6100]}]}, {"id": "ch26p35", "audio": true, "sents": [{"fr": "Mais il ne répondit pas à ma question.", "zh": "但他没有回答我的问题。", "t": [100, 2812]}, {"fr": "Il me dit :", "zh": "他说：", "t": [2812, 4162]}]}, {"id": "ch26p36", "audio": true, "sents": [{"fr": "— Ce qui est important, ça ne se voit pas…", "zh": "那重要的东西，肉眼是看不见的。", "t": [100, 3213]}]}, {"id": "ch26p37", "audio": true, "sents": [{"fr": "— Bien sûr…", "zh": "当然。", "t": [100, 1825]}]}, {"id": "ch26p38", "audio": true, "sents": [{"fr": "— C’est comme pour la fleur.", "zh": "这就像是为那朵花。", "t": [100, 3275]}, {"fr": "Si tu aimes une fleur qui se trouve dans une étoile, c’est doux, la nuit, de regarder le ciel.", "zh": "夜幕降临，凝望星空，若你爱上一朵在星辰中的花，便觉甜蜜。", "t": [3275, 9112]}, {"fr": "Toutes les étoiles sont fleuries.", "zh": "所有的星星都开满了花。", "t": [9112, 10576]}]}, {"id": "ch26p39", "audio": true, "sents": [{"fr": "— Bien sûr…", "zh": "当然。", "t": [100, 1825]}]}, {"id": "ch26p40", "audio": true, "sents": [{"fr": "— C’est comme pour l’eau.", "zh": "这就像水一样。", "t": [100, 2888]}, {"fr": "Celle que tu m’as donnée à boire était comme une musique, à cause de la poulie et de la corde…", "zh": "那水，因了辘轳与绳索，便如音乐般流淌。", "t": [2888, 7425]}, {"fr": "tu te rappelles…", "zh": "你记得吗？", "t": [7425, 8425]}, {"fr": "elle était bonne.", "zh": "她很善良。", "t": [8425, 9112]}]}, {"id": "ch26p41", "audio": true, "sents": [{"fr": "— Bien sûr…", "zh": "当然…", "t": [100, 1825]}]}, {"id": "ch26p42", "audio": true, "sents": [{"fr": "— Tu regarderas, la nuit, les étoiles.", "zh": "你将在夜晚仰望星空。", "t": [100, 4500]}, {"fr": "C’est trop petit chez moi pour que je te montre où se trouve la mienne.", "zh": "这里太小了，无法向你展示我的那朵花在哪里。", "t": [4500, 8412]}, {"fr": "C’est mieux comme ça.", "zh": "这样更好。", "t": [8412, 10300]}, {"fr": "Mon étoile, ça sera pour toi une des étoiles.", "zh": "我的星星，对你而言，将是一颗星星。", "t": [10300, 14050]}, {"fr": "Alors, toutes les étoiles, tu aimeras les regarder…", "zh": "那么，所有的星星，你都会爱看它们……", "t": [14050, 18000]}, {"fr": "Elles seront toutes tes amies.", "zh": "它们都将成为你的朋友。", "t": [18000, 20175]}, {"fr": "Et puis je vais te faire un cadeau…", "zh": "然后，我将送你一份礼物……", "t": [20175, 21562]}]}, {"id": "ch26p43", "audio": true, "sents": [{"fr": "Il rit encore.", "zh": "他又笑了。", "t": [100, 1013]}]}, {"id": "ch26p44", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "petit bonhomme, petit bonhomme j’aime entendre ce rire !", "zh": "小朋友，小朋友，我喜欢听你的笑声！", "t": [3038, 6374]}]}, {"id": "ch26p45", "audio": true, "sents": [{"fr": "— Justement ce sera mon cadeau…", "zh": "这正是我给你的礼物…", "t": [100, 2812]}, {"fr": "ce sera comme pour l’eau…", "zh": "这就像水一样……", "t": [2812, 3874]}]}, {"id": "ch26p46", "audio": true, "sents": [{"fr": "— Que veux-tu dire ?", "zh": "你想说什么？", "t": [100, 2587]}]}, {"id": "ch26p47", "audio": true, "sents": [{"fr": "— Les gens ont des étoiles qui ne sont pas les mêmes.", "zh": "人们各有各的星星。", "t": [100, 4188]}, {"fr": "Pour les uns, qui voyagent, les étoiles sont des guides.", "zh": "对旅行者而言，星星是向导。", "t": [4188, 8112]}, {"fr": "Pour d’autres elles ne sont rien que de petites lumières.", "zh": "对她们来说，那只是小小的灯火。", "t": [8112, 11288]}, {"fr": "Pour d’autres qui sont savants elles sont des problèmes.", "zh": "对学者而言，它们是问题。", "t": [11288, 14325]}, {"fr": "Pour mon businessman elles étaient de l’or.", "zh": "对那位商人来说，它们是金子。", "t": [14325, 17150]}, {"fr": "Mais toutes ces étoiles-là se taisent.", "zh": "然而，所有的星星都沉默着。", "t": [17150, 19712]}, {"fr": "Toi, tu auras des étoiles comme personne n’en a…", "zh": "你将拥有别人无法拥有的星星。", "t": [19712, 22338]}]}, {"id": "ch26p48", "audio": true, "sents": [{"fr": "— Que veux-tu dire ?", "zh": "你想说什么？", "t": [100, 2587]}]}, {"id": "ch26p49", "audio": true, "sents": [{"fr": "— Quand tu regarderas le ciel, la nuit, puisque j’habiterai dans l’une d’elles, puisque je rirai dans l’une d’elles, alors ce sera pour toi comme si riaient toutes les étoiles.", "zh": "当你在夜晚仰望星空，既然我将居住在其中的一颗，既然我在其中一颗上欢笑，那么对你而言，就如同所有的星星都在欢笑。", "t": [100, 10462]}, {"fr": "Tu auras, toi, des étoiles qui savent rire !", "zh": "你将拥有懂得笑的星星。", "t": [10462, 13787]}]}, {"id": "ch26p50", "audio": true, "sents": [{"fr": "Et il rit encore.", "zh": "他又笑了。", "t": [100, 1074]}]}, {"id": "ch26p51", "audio": true, "sents": [{"fr": "— Et quand tu seras consolé (on se console toujours) tu seras content de m’avoir connu.", "zh": "且待你心有所慰，自会庆幸曾识我。", "t": [100, 6750]}, {"fr": "Tu seras toujours mon ami.", "zh": "你将永远是我的朋友。", "t": [6750, 9062]}, {"fr": "Tu auras envie de rire avec moi.", "zh": "你愿意与我同笑。", "t": [9062, 11688]}, {"fr": "Et tu ouvriras parfois ta fenêtre, comme ça, pour le plaisir…", "zh": "你也可能会打开窗户，只是为了快乐……", "t": [11688, 16162]}, {"fr": "Et tes amis seront bien étonnés de te voir rire en regardant le ciel.", "zh": "你的朋友们会惊讶地看到你在仰望星空时笑出声来。", "t": [16162, 20388]}, {"fr": "Alors tu leur diras : \"Oui, les étoiles, ça me fait toujours rire !\" Et ils te croiront fou.", "zh": "是的，星星总是让我发笑！他们会以为你疯了。", "t": [20388, 28450]}, {"fr": "Je t’aurai joué un bien vilain tour…", "zh": "我给你开了一个大大的玩笑……", "t": [28450, 30350]}]}, {"id": "ch26p52", "audio": true, "sents": [{"fr": "Et il rit encore.", "zh": "他又笑了。", "t": [100, 1074]}]}, {"id": "ch26p53", "audio": true, "sents": [{"fr": "— Ce sera comme si je t’avais donné, au lieu d’étoiles, des tas de petits grelots qui savent rire…", "zh": "这就像是我给了你，而不是星星，一串串会笑的小铃铛……", "t": [100, 6050]}]}, {"id": "ch26p54", "audio": true, "sents": [{"fr": "Et il rit encore.", "zh": "他又笑了。", "t": [100, 1950]}, {"fr": "Puis il redevint sérieux :", "zh": "然后他又变得严肃起来：", "t": [1950, 3912]}]}, {"id": "ch26p55", "audio": true, "sents": [{"fr": "— Cette nuit…", "zh": "今夜…", "t": [100, 2000]}, {"fr": "tu sais…", "zh": "你知道……", "t": [2000, 2650]}, {"fr": "ne viens pas.", "zh": "别来了。", "t": [2650, 3174]}]}, {"id": "ch26p56", "audio": true, "sents": [{"fr": "— Je ne te quitterai pas.", "zh": "我不会离开你。", "t": [100, 2150]}]}, {"id": "ch26p57", "audio": true, "sents": [{"fr": "— J’aurai l’air d’avoir mal…", "zh": "我看起来像是生病了……", "t": [100, 9000]}, {"fr": "j’aurai un peu l’air de mourir.", "zh": "我看起来会有些像要死去。", "t": [9000, 9500]}, {"fr": "C’est comme ça.", "zh": "如此而已。", "t": [9500, 10000]}, {"fr": "Ne viens pas voir ça, ce n’est pas la peine…", "zh": "你不必来看这个，无此必要……", "t": [10000, 10500]}]}, {"id": "ch26p58", "audio": true, "sents": [{"fr": "— Je ne te quitterai pas.", "zh": "我永远不会离开你。", "t": [100, 2150]}]}, {"id": "ch26p59", "audio": true, "sents": [{"fr": "Mais il était soucieux.", "zh": "但他忧心忡忡。", "t": [100, 1225]}]}, {"id": "ch26p60", "audio": true, "sents": [{"fr": "— Je te dis ça…", "zh": "我这就告诉你……", "t": [100, 2100]}, {"fr": "c’est à cause aussi du serpent.", "zh": "这也是因为那条蛇。", "t": [2100, 4375]}, {"fr": "Il ne faut pas qu’il te morde…", "zh": "它不会咬你的。", "t": [4375, 6638]}, {"fr": "Les serpents, c’est méchant.", "zh": "蛇，是恶毒的。", "t": [6638, 9038]}, {"fr": "Ça peut mordre pour le plaisir…", "zh": "它也许会为了乐趣而咬人。", "t": [9038, 10700]}]}, {"id": "ch26p61", "audio": true, "sents": [{"fr": "— Je ne te quitterai pas.", "zh": "我永远不会离开你。", "t": [100, 2150]}]}, {"id": "ch26p62", "audio": true, "sents": [{"fr": "Mais quelque chose le rassura :", "zh": "但有什么东西让他安心了：", "t": [100, 2475]}]}, {"id": "ch26p63", "audio": true, "sents": [{"fr": "— C’est vrai qu’ils n’ont plus de venin pour la seconde morsure…", "zh": "这话说得没错，它们第二次咬人时已无毒性。", "t": [100, 3800]}]}, {"id": "ch26p64", "audio": true, "sents": [{"fr": "Cette nuit-là je ne le vis pas se mettre en route.", "zh": "那晚我没有看到他动身。", "t": [100, 3238]}, {"fr": "Il s’était évadé sans bruit.", "zh": "悄无声息地逃走了。", "t": [3238, 5675]}, {"fr": "Quand je réussis à le rejoindre il marchait décidé, d’un pas rapide.", "zh": "他成功追上时，他正坚定地、快速地走着。", "t": [5675, 10100]}, {"fr": "Il me dit seulement :", "zh": "他只对我说：", "t": [10100, 11787]}]}, {"id": "ch26p65", "audio": true, "sents": [{"fr": "— Ah !", "zh": "啊！", "t": [100, 3038]}, {"fr": "tu es là…", "zh": "你在这里……", "t": [3038, 3588]}]}, {"id": "ch26p66", "audio": true, "sents": [{"fr": "Et il me prit par la main.", "zh": "他握住了我的手。", "t": [100, 2125]}, {"fr": "Mais il se tourmenta encore :", "zh": "但他仍感忧虑：", "t": [2125, 4326]}]}, {"id": "ch26p67", "audio": true, "sents": [{"fr": "— Tu as eu tort.", "zh": "你错了。", "t": [100, 2975]}, {"fr": "Tu auras de la peine.", "zh": "你将感到痛苦。", "t": [2975, 4975]}, {"fr": "J’aurai l’air d’être mort et ce ne sera pas vrai…", "zh": "我看起来像是死了，其实并非如此……", "t": [4975, 7263]}]}, {"id": "ch26p68", "audio": true, "sents": [{"fr": "Moi je me taisais.", "zh": "我静默着。", "t": [100, 1112]}]}, {"id": "ch26p69", "audio": true, "sents": [{"fr": "— Tu comprends.", "zh": "你明白了。", "t": [100, 2738]}, {"fr": "C’est trop loin.", "zh": "这太远了。", "t": [2738, 4425]}, {"fr": "Je ne peux pas emporter ce corps-là.", "zh": "我无法带走这具躯体。", "t": [4425, 6938]}, {"fr": "C’est trop lourd.", "zh": "这太沉重了。", "t": [6938, 7825]}]}, {"id": "ch26p70", "audio": true, "sents": [{"fr": "Moi je me taisais.", "zh": "我静默着。", "t": [100, 1112]}]}, {"id": "ch26p71", "audio": true, "sents": [{"fr": "— Mais ce sera comme une vieille écorce abandonnée.", "zh": "这就像是一层被遗弃的旧壳。", "t": [100, 4275]}, {"fr": "Ce n’est pas triste les vieilles écorces…", "zh": "那旧皮壳并无悲凉。", "t": [4275, 6088]}]}, {"id": "ch26p72", "audio": true, "sents": [{"fr": "Moi je me taisais.", "zh": "我静默着。", "t": [100, 1112]}]}, {"id": "ch26p73", "audio": true, "sents": [{"fr": "Il se découragea un peu.", "zh": "他有些泄气了。", "t": [100, 2362]}, {"fr": "Mais il fit encore un effort :", "zh": "但他又竭尽全力：", "t": [2362, 4463]}]}, {"id": "ch26p74", "audio": true, "sents": [{"fr": "— Ce sera gentil, tu sais.", "zh": "你知道，这会很美好。", "t": [100, 3625]}, {"fr": "Moi aussi je regarderai les étoiles.", "zh": "我也将仰望星空。", "t": [3625, 6475]}, {"fr": "Toutes les étoiles seront des puits avec une poulie rouillée.", "zh": "所有的星星都将是带锈辘轳的井。", "t": [6475, 10012]}, {"fr": "Toutes les étoiles me verseront à boire…", "zh": "所有的星星都会为我倒水喝…", "t": [10012, 11987]}]}, {"id": "ch26p75", "audio": true, "sents": [{"fr": "Moi je me taisais.", "zh": "我静默着。", "t": [100, 1112]}]}, {"id": "ch26p76", "audio": true, "sents": [{"fr": "— Ce sera tellement amusant !", "zh": "这会非常有趣！", "t": [100, 4062]}, {"fr": "Tu auras cinq cents millions de grelots, j’aurai cinq cents millions de fontaines…", "zh": "你将拥有五千万个小铃铛，我将拥有五千万口井……", "t": [4062, 7650]}]}, {"id": "ch26p77", "audio": true, "sents": [{"fr": "Et il se tut aussi, parce qu’il pleurait…", "zh": "他也如此，因为他也在哭泣……", "t": [100, 2213]}]}, {"id": "ch26p78", "audio": true, "sents": [{"fr": "— C’est là.", "zh": "这就是这里。", "t": [100, 2462]}, {"fr": "Laisse-moi faire un pas tout seul.", "zh": "让我独自迈一步。", "t": [2462, 4025]}]}, {"id": "ch26p79", "audio": true, "sents": [{"fr": "Et il s’assit parce qu’il avait peur.", "zh": "他坐下来，因为他害怕了。", "t": [100, 1750]}]}, {"id": "ch26p80", "audio": true, "sents": [{"fr": "Il dit encore :", "zh": "他又说道：", "t": [100, 1600]}]}, {"id": "ch26p81", "audio": true, "sents": [{"fr": "— Tu sais…", "zh": "你知道……", "t": [100, 1900]}, {"fr": "ma fleur…", "zh": "我的玫瑰…", "t": [1900, 2638]}, {"fr": "j’en suis responsable !", "zh": "我对此负有责任！", "t": [2638, 5200]}, {"fr": "Et elle est tellement faible !", "zh": "她如此脆弱！", "t": [5200, 7838]}, {"fr": "Et elle est tellement naïve.", "zh": "她如此天真。", "t": [7838, 9888]}, {"fr": "Elle a quatre épines de rien du tout pour la protéger contre le monde…", "zh": "她仅凭四根刺来抵御世间的侵害。", "t": [9888, 13063]}]}, {"id": "ch26p82", "audio": true, "sents": [{"fr": "Moi je m’assis parce que je ne pouvais plus me tenir debout.", "zh": "我坐下来，因为我站不住了。", "t": [100, 3712]}, {"fr": "Il dit :", "zh": "他说：", "t": [3712, 4962]}]}, {"id": "ch26p83", "audio": true, "sents": [{"fr": "— Voilà…", "zh": "看哪…", "t": [100, 2450]}, {"fr": "C’est tout…", "zh": "这就是全部……", "t": [2450, 2963]}]}, {"id": "ch26p84", "audio": true, "sents": [{"fr": "Il hésita encore un peu, puis il se releva.", "zh": "他犹豫片刻，然后站起身。", "t": [100, 3462]}, {"fr": "Il fit un pas.", "zh": "他迈出一步。", "t": [3462, 5038]}, {"fr": "Moi je ne pouvais pas bouger.", "zh": "我无法动弹。", "t": [5038, 6487]}]}, {"id": "ch26p85", "audio": true, "sents": [{"fr": "Il n’y eut rien qu’un éclair jaune près de sa cheville.", "zh": "脚踝旁掠过一道黄色闪电。", "t": [100, 3375]}, {"fr": "Il demeura un instant immobile.", "zh": "他片刻间僵立不动。", "t": [3375, 6100]}, {"fr": "Il ne cria pas.", "zh": "它没有叫喊。", "t": [6100, 7812]}, {"fr": "Il tomba doucement comme tombe un arbre.", "zh": "他缓缓落下，如同树倒。", "t": [7812, 10688]}, {"fr": "Ça ne fit même pas de bruit, à cause du sable.", "zh": "那连沙沙声都没有。", "t": [10688, 13288]}]}, {"id": "ch26p86", "audio": true, "sents": []}, {"id": "ch26p87", "audio": true, "sents": []}]}, {"id": "ch27", "title_fr": "Chapitre XXVII", "title_zh": "第 27 章", "paras": [{"id": "ch27p00", "audio": true, "sents": [{"fr": "Et maintenant, bien sûr, ça fait six ans déjà…", "zh": "如今，当然，已经六年过去了…", "t": [100, 3800]}, {"fr": "Je n’ai jamais encore raconté cette histoire.", "zh": "我从未讲述过这个故事。", "t": [3800, 7025]}, {"fr": "Les camarades qui m’ont revu ont été bien contents de me revoir vivant.", "zh": "重逢时，同伴们见到我安然无恙，都为我感到高兴。", "t": [7025, 11412]}, {"fr": "J’étais triste mais je leur disais : C’est la fatigue…", "zh": "我心中忧伤，却对他们说：“这是累的缘故……”", "t": [11412, 14850]}]}, {"id": "ch27p01", "audio": true, "sents": [{"fr": "Maintenant je me suis un peu consolé.", "zh": "如今我已渐渐宽慰。", "t": [100, 2825]}, {"fr": "C’est à dire…", "zh": "也就是说…", "t": [2825, 3800]}, {"fr": "pas tout à fait.", "zh": "尚不完全。", "t": [3800, 5412]}, {"fr": "Mais je sais bien qu’il est revenu à sa planète, car, au lever du jour, je n’ai pas retrouvé son corps.", "zh": "但我深知，他已返回了自己的星球，因为破晓时分，我没有找到他的遗体。", "t": [5412, 11825]}, {"fr": "Ce n’était pas un corps tellement lourd…", "zh": "那并非是一具过分沉重的身躯…", "t": [11825, 14400]}, {"fr": "Et j’aime la nuit écouter les étoiles.", "zh": "我喜爱在夜色中聆听星星的细语。", "t": [14400, 17062]}, {"fr": "C’est comme cinq cent millions de grelots…", "zh": "就像五亿个小铃铛……", "t": [17062, 18738]}]}, {"id": "ch27p02", "audio": true, "sents": [{"fr": "Mais voilà qu’il se passe quelque chose d’extraordinaire.", "zh": "然而，却发生了件不同寻常的事。", "t": [100, 3788]}, {"fr": "La muselière que j’ai dessinée pour le petit prince, j’ai oublié d’y ajouter la courroie de cuir !", "zh": "我为小王子画的口罩，却忘了加上皮带头带！", "t": [3788, 10112]}, {"fr": "Il n’aura jamais pu l’attacher au mouton.", "zh": "他无法将它系在绵羊的脖子上。", "t": [10112, 13012]}, {"fr": "Alors je me demande : \"Que s’est-il passé sur sa planète ?", "zh": "那么我想：“在他的星球上，究竟发生了什么？”", "t": [13012, 18138]}, {"fr": "Peut-être bien que le mouton a mangé la fleur…\"", "zh": "或许绵羊已经吃掉了那朵花……", "t": [18138, 20537]}]}, {"id": "ch27p03", "audio": true, "sents": [{"fr": "Tantôt je me dis : \"Sûrement non !", "zh": "或许并非如此！", "t": [100, 4162]}, {"fr": "Le petit prince enferme sa fleur toutes les nuits sous son globe de verre, et il surveille bien son mouton…\" Alors je suis heureux.", "zh": "小王子每晚都将他的花儿藏进玻璃球里，他严加看管着他的绵羊……于是我感到欣慰。", "t": [4162, 12050]}, {"fr": "Et toutes les étoiles rient doucement.", "zh": "所有的星星都在轻轻微笑。", "t": [12050, 13575]}]}, {"id": "ch27p04", "audio": true, "sents": [{"fr": "Tantôt je me dis : \"On est distrait une fois ou l’autre, et ça suffit !", "zh": "有时我想：“偶尔疏忽一下，也就足够了！”", "t": [100, 5938]}, {"fr": "Il a oublié, un soir, le globe de verre, ou bien le mouton est sorti sans bruit pendant la nuit…\" Alors les grelots se changent tous en larmes !…", "zh": "那晚，他忘了玻璃球，或者绵羊在夜色中悄无声息地溜了出来……于是，铃铛全都变成了泪珠！", "t": [5938, 14737]}]}, {"id": "ch27p05", "audio": true, "sents": [{"fr": "C’est là un bien grand mystère.", "zh": "这是一个重大的谜团。", "t": [100, 2512]}, {"fr": "Pour vous qui aimez aussi le petit prince, comme pour moi, rien de l’univers n’est semblable si quelque part, on ne sait où, un mouton que nous ne connaissons pas a, oui ou non, mangé une rose…", "zh": "对于你们这些也喜爱小王子的人，如同我一样，宇宙中若在某个角落，不知何地，有一只我们不认识的绵羊，是或不是，吃掉了一朵玫瑰……", "t": [2512, 12587]}]}, {"id": "ch27p06", "audio": true, "sents": [{"fr": "Regardez le ciel.", "zh": "仰望星空。", "t": [100, 2112]}, {"fr": "Demandez-vous : le mouton oui ou non a-t-il mangé la fleur ?", "zh": "请问：绵羊是否真的吃掉了那朵花？", "t": [2112, 7462]}, {"fr": "Et vous verrez comme tout change…", "zh": "你们就会看到，一切都变了……", "t": [7462, 8912]}]}, {"id": "ch27p07", "audio": true, "sents": [{"fr": "Et aucune grande personne ne comprendra jamais que ça a tellement d’importance !", "zh": "大人永远无法理解这有多么重要！", "t": [100, 4425]}]}, {"id": "ch27p08", "audio": true, "sents": [{"fr": "Ça c’est, pour moi, le plus beau et le plus triste paysage du monde.", "zh": "这是，对我来说，世上最美又最凄凉的风光。", "t": [100, 4912]}, {"fr": "C’est le même paysage que celui de la page précédente, mais je l’ai dessiné une fois encore pour bien vous le montrer.", "zh": "这画面与前页的风景相同，但我又画了一次，以便你们能更清楚地看到。", "t": [4912, 11600]}, {"fr": "C’est ici que le petit prince a apparu sur terre, puis disparu.", "zh": "这里是小王子降临地球，又消失的地方。", "t": [11600, 14937]}]}, {"id": "ch27p09", "audio": true, "sents": [{"fr": "Regardez attentivement ce paysage afin d’être sûrs de le reconnaître, si vous voyagez un jour en Afrique, dans le désert.", "zh": "仔细观察这幅风景，以便在你们有朝一日穿越非洲沙漠时能认出它。", "t": [100, 7700]}, {"fr": "Et, s’il vous arrive de passer par là, je vous en supplie, ne vous pressez pas, attendez un peu juste sous l’étoile !", "zh": "若您经过此地，恳请您，别急匆匆，就在那颗星星下稍作停留！", "t": [7700, 15300]}, {"fr": "Si alors un enfant vient à vous, s’il rit, s’il a des cheveux d’or, s’il ne répond pas quand on l’interroge, vous devinerez bien qui il est.", "zh": "若有个孩子向你走来，他笑得灿烂，金发飘逸，当你问他时却缄默不语，你便能猜出他是谁了。", "t": [15300, 23350]}, {"fr": "Alors soyez gentils !", "zh": "那么，请你们行行好！", "t": [23350, 26050]}, {"fr": "Ne me laissez pas tellement triste : écrivez-moi vite qu’il est revenu…", "zh": "别让我如此悲伤：快写信告诉我，他回来了……", "t": [26050, 29900]}]}, {"id": "ch27p10", "audio": true, "sents": []}]}]}